(window.SOURCERER_I18N = window.SOURCERER_I18N || {})["vi"] = {"nav.skip":"Chuyển đến nội dung","nav.home":"Trang chủ","nav.features":"Tính năng","nav.documentation":"Tài liệu","nav.changelog":"Nhật ký thay đổi","nav.language":"Ngôn ngữ","hero.tagline":"Một lần tìm. Mọi nguồn. Mọi hệ điều hành.","hero.sub":"Tìm bất kỳ tệp nào ngay khi bạn gõ: theo tên, theo chữ bên trong, theo âm thanh của nó, theo những gì phần header ghi, hoặc theo một cái tên chỉ gần giống với tên bạn nhớ.","notice.price":"Freally Sourcerer hiện miễn phí. Các phiên bản sau này có thể được bán.","hero.chipApp":"Ứng dụng máy tính","hero.chipCli":"Dòng lệnh","hero.chipLanguages":"18 ngôn ngữ","hero.noDownloads":"Đang phát triển. Chưa có bản tải xuống nào cho đến phiên bản 1.0.0, và mã nguồn là riêng tư.","what.title":"Đây là gì","what.p1":"Hệ điều hành nào cũng có một ô tìm kiếm, và mỗi ô lại hụt hơi theo một kiểu riêng. Everything của voidtools đã khiến việc tìm theo tên tệp trên Windows trở nên tức thì từ nhiều năm trước, và nó vẫn chỉ ở trên Windows.","what.p2":"Freally Sourcerer là kiểu tìm kiếm đó cho Windows, macOS và Linux. Nó giữ một chỉ mục duy nhất cho các ổ đĩa của bạn, luôn được cập nhật nhờ chính bản ghi thay đổi tệp của từng hệ thống — nhật ký thay đổi NTFS trên Windows, FSEvents trên macOS, inotify và fanotify trên Linux — nên tệp mới và tệp vừa đổi tên đều được tìm thấy mà không cần quét lại.","what.p3":"Rồi nó còn đọc xa hơn cái tên. Một truy vấn có thể hỏi về tên, về chữ bên trong tài liệu, về độ to đo được của một tệp âm thanh, về những gì một bức ảnh hay một chương trình tự khai trong header của nó, và về những cái tên chỉ gần giống với những gì bạn đã gõ.","features.title":"Bên trong có gì","features.filename.title":"Tên tệp, tức thì","features.filename.body":"Chuỗi con, ký tự đại diện, biểu thức chính quy, AND, OR và NOT, cùng các công cụ sửa đổi riêng của Everything cho kích thước, ngày, phần mở rộng và đường dẫn, được trả lời từ chỉ mục ngay khi bạn gõ.","features.content.title":"Chữ bên trong tệp","features.content.body":"Tìm kiếm toàn văn trong tệp PDF, Word, Excel và PowerPoint, Markdown, mã nguồn bằng 32 ngôn ngữ, JSON, CSV và YAML, thư điện tử, và cả bên trong tệp lưu trữ mà không cần giải nén.","features.audio.title":"Âm thanh theo cách nó vang lên","features.audio.body":"Tìm âm thanh theo độ to đo được tính bằng LUFS, true peak, khoảng lặng, dải động, độ dài, codec và tần số lấy mẫu — chứ không theo thẻ mà ai đó đã gõ vào.","features.properties.title":"Những gì một tệp tự nói về mình","features.properties.body":"Bảy mươi hai thuộc tính đọc từ header của tệp: kích thước ảnh và máy ảnh, codec và độ dài video, tác giả và số trang tài liệu, kiến trúc và chữ ký của một chương trình, cùng nhiều thứ khác.","features.similar.title":"Những cái tên chỉ gần giống","features.similar.body":"Ống kính tương đồng tìm những cái tên gần với những gì bạn gõ — một lỗi đánh máy, một số phiên bản, một tiền tố khác — và một lần tìm không thấy gì sẽ gợi ý cái tên thật gần nhất.","features.everything.title":"Quen thuộc ngay nếu bạn đến từ Everything","features.everything.body":"Cú pháp tìm kiếm của Everything cũng dùng được ở đây, và danh sách tệp của nó có thể mở và xuất ra, nên danh mục của một ổ đĩa có thể chuyển qua lại giữa hai bên.","features.results.title":"Làm gì đó với những gì bạn tìm thấy","features.results.body":"Mở, hiện trong thư mục, sao chép, đổi tên cả một nhóm kết quả với bản xem trước rồi hoàn tác, tìm tệp trùng lặp và thư mục trống, và chạy các lệnh của riêng bạn.","features.platforms.title":"Một ứng dụng, ba hệ thống","features.platforms.body":"Cùng một ứng dụng, cùng ngôn ngữ truy vấn và cùng chỉ mục trên Windows, macOS và Linux, một dòng lệnh cho các tập lệnh, và mười tám ngôn ngữ.","ladder.title":"Con đường đến 1.0","ladder.intro":"Mỗi phiên bản một dòng. Các phiên bản sau 0.23 là kế hoạch, theo thứ tự chúng sẽ được xây dựng.","ladder.version":"Phiên bản","ladder.state":"Trạng thái","ladder.lands":"Nó mang lại gì","ladder.state.done":"Xong","ladder.rung.v0.19.84":"Bản dựng công khai đầu tiên: tìm theo tên tệp, luôn được cập nhật nhờ nhật ký thay đổi riêng của từng hệ thống, ngôn ngữ truy vấn, ứng dụng và phần cài đặt, bằng mười tám ngôn ngữ trên Windows, macOS và Linux.","ladder.rung.v0.21.0":"Tính năng thiết yếu, phần 1 trên 3: tệp trùng lặp, thư mục trống, danh sách tệp của Everything, và mọi thao tác trên một kết quả từ menu chuột phải.","ladder.rung.v0.22.0":"Tính năng thiết yếu, phần 2 trên 3: chỉ mục theo sát ổ đĩa theo thời gian thực, Tình trạng chỉ mục, đổi tên hàng loạt có hoàn tác, ổ đĩa đã rút ra vẫn tìm kiếm được, và một dòng lệnh cho các tập lệnh.","ladder.rung.v0.23.0":"Tính năng thiết yếu, phần 3 trên 3, và bản phát hành ổn định: chế độ di động, âm thanh và video trong khung xem trước, Xem nhanh, trình tạo biểu thức chính quy, và báo cáo về những thư mục mà việc tìm kiếm không nhìn thấy được. Bản sửa lỗi của nó, 0.23.2, là phiên bản hiện tại.","ladder.state.planned":"Đã lên kế hoạch","ladder.rung.v0.24.0":"Ống kính thuộc tính cho ảnh và video: kích thước, dữ liệu máy ảnh, codec và thời lượng, tìm kiếm được và hiển thị thành cột.","ladder.rung.v0.25.0":"Ống kính thuộc tính cho tài liệu, chương trình và gói cài đặt: tác giả và số trang, kiến trúc và chữ ký, trình cài đặt, lối tắt, tệp lưu trữ, phông chữ, thư điện tử và cơ sở dữ liệu.","ladder.rung.v0.26.0":"Thẻ nhạc, và nhiều hơn nữa cho người làm việc với âm thanh.","ladder.rung.v0.27.0":"Tệp trùng lặp và dọn dẹp ổ đĩa.","ladder.rung.v0.28.0":"Thẻ, ghi chú và bộ sưu tập cho tệp của bạn.","ladder.rung.v0.29.0":"Tìm kiếm nâng cao: macro, ảnh chụp nhanh, theo dõi và mã băm tệp.","ladder.rung.v0.30.0":"Khung xem và cửa sổ.","ladder.rung.v0.31.0":"Một trình khởi chạy, và gắn kết chặt hơn với hệ điều hành của bạn.","ladder.rung.v0.32.0":"Dòng lệnh, giao diện terminal và tự động hóa.","ladder.rung.v0.33.0":"Tìm kiếm trên mạng cục bộ của bạn, danh mục, và công cụ chỉ mục cho người dùng chuyên sâu.","ladder.state.goal":"Mục tiêu","ladder.rung.v1.0.0":"Ống kính mã nguồn và tri thức, cùng bản phát hành: phiên bản 1.0.","ladder.note":"Một phiên bản hoàn tất đã được dựng và gắn thẻ. Đó không phải là bản tải xuống: chưa có, và sẽ không có cho đến 1.0.0.","honest.title":"Những điều mà hầu hết các trang web đặt ở cuối trang","honest.firstIndex.title":"Lần lập chỉ mục đầu tiên lâu hơn trên macOS và Linux","honest.firstIndex.body":"Trên Windows, nhật ký thay đổi NTFS cho phép lập chỉ mục cả một ổ đĩa rất nhanh. macOS và Linux không có thứ gì tương tự, nên lần lập chỉ mục đầu tiên ở đó phải đi qua từng thư mục: tính bằng phút chứ không phải giây trên một ổ đĩa lớn. Sau đó, chính các sự kiện thay đổi của hệ thống giữ cho chỉ mục luôn cập nhật.","honest.network.title":"Những gì kết nối mạng, và những gì không bao giờ","honest.network.body":"Không có đo từ xa, và không có gì về tệp hay các lần tìm kiếm của bạn được gửi đi đâu cả. Tự bản thân nó, ứng dụng chỉ kết nối mạng vì một việc: hỏi xem có phiên bản mới hơn không, mỗi ngày một lần trừ khi bạn thay đổi, và bạn có thể tắt việc đó. Một báo cáo lỗi chỉ được gửi khi bạn chọn gửi, sau khi bạn đã xem nó chứa những gì.","honest.unreadable.title":"Nó cho bạn biết những gì nó không nhìn thấy","honest.unreadable.body":"Một thư mục không đọc được trông y hệt một thư mục trống. Sourcerer liệt kê những thư mục nó buộc phải bỏ qua, kèm lý do và cách khắc phục cho hệ thống của bạn, thay vì lặng lẽ trả về ít kết quả hơn.","honest.lenses.title":"Hai trong năm ống kính chưa được kết nối","honest.lenses.body":"Ống kính nội dung, thứ đọc chữ bên trong tệp, và ống kính tương đồng, thứ tìm những cái tên chỉ gần giống, đã được xây dựng nhưng chưa trả lời các lần tìm kiếm. Hiện nay, ống kính tên tệp, âm thanh và thuộc tính là những ống kính trả lời. Kết nối hai ống kính còn lại là một phần của con đường đến 1.0.","honest.downloads.title":"Chưa có bản tải xuống nào trước 1.0.0","honest.downloads.body":"Không có bản beta trên trang này, không có bản dựng xem trước, không có quyền truy cập sớm. Phiên bản 1.0.0 là bản đầu tiên trang này sẽ cung cấp.","footer.licence":"Phần mềm độc quyền — Bảo lưu mọi quyền. © Mike Weaver. Hiện miễn phí sử dụng; các phiên bản sau này có thể được bán. Không phải mã nguồn mở.","footer.everything":"Everything là nhãn hiệu của voidtools, được nhắc đến ở đây chỉ để so sánh. Freally Sourcerer không liên kết với voidtools.","featuresPage.title":"Mọi thứ nó làm được","featuresPage.lead":"Một thanh tìm kiếm cho mọi tệp trên Windows, macOS và Linux: tên, chữ bên trong tài liệu, âm thanh theo cách nó vang lên, những gì chính header của tệp ghi, và những cái tên chỉ gần giống — từ một chỉ mục duy nhất tự giữ mình luôn cập nhật.","featuresPage.version":"Trang này mô tả Freally Sourcerer phiên bản 1.0: mọi thứ trên trang đều có trong 1.0, và không có gì dự kiến cho sau 1.0 xuất hiện ở đây.","featuresPage.numbers.title":"Qua những con số","featuresPage.numbers.intro":"Mỗi con số đều được đếm từ chính mã nguồn của ứng dụng và nhật ký thay đổi của nó. Không có gì được làm tròn lên.","featuresPage.numbers.lenses":"cách tìm trong một chỉ mục: tên tệp, nội dung, âm thanh, thuộc tính và tên tương tự","featuresPage.numbers.properties":"thuộc tính tệp đọc từ header","featuresPage.numbers.code":"ngôn ngữ lập trình mà tìm kiếm nội dung đọc được","featuresPage.numbers.audioTypes":"loại tệp âm thanh trong bộ lọc Âm thanh","featuresPage.numbers.matchModes":"chế độ khớp, từ Phân biệt chữ hoa/thường đến Bỏ qua dấu câu","featuresPage.numbers.systems":"hệ điều hành: Windows, macOS và Linux","featuresPage.numbers.languages":"ngôn ngữ","featuresPage.numbers.price":"giá hiện nay","featuresPage.free.title":"Hiện miễn phí","featuresPage.free.body":"Mọi thứ Sourcerer làm hiện nay đều miễn phí, cho tất cả mọi người: không có gói trả phí, không có thuê bao và không có bản dùng thử hết hạn.","featuresPage.cards.title":"Phiên bản 1.0 làm được gì","featuresPage.cards.index.title":"Một chỉ mục trực tiếp cho mọi ổ đĩa","featuresPage.cards.index.body":"Một chỉ mục duy nhất cho tất cả các ổ đĩa của bạn, luôn được cập nhật nhờ luồng thay đổi riêng của từng hệ thống — nhật ký thay đổi NTFS trên Windows, FSEvents trên macOS, inotify và fanotify trên Linux — nên tệp mới, tệp đổi tên và tệp đã xóa đều hiện ra mà không cần quét lại. Một ổ đĩa bạn rút ra vẫn tìm kiếm được, và kết quả của nó cho biết chúng nằm trên ổ đĩa nào.","featuresPage.cards.names.title":"Tên tệp, theo cách Everything tìm chúng","featuresPage.cards.names.body":"Chuỗi con, ký tự đại diện, biểu thức chính quy, AND, OR, NOT và nhóm, với các công cụ sửa đổi và cách viết của Everything cho kích thước, ngày, phần mở rộng, thuộc tính và đường dẫn, cùng bảy chế độ khớp, từ Phân biệt chữ hoa/thường đến Bỏ qua dấu câu và khớp tên tiếng Trung, tiếng Nhật và tiếng Hàn theo cách đọc.","featuresPage.cards.content.title":"Chữ bên trong tệp","featuresPage.cards.content.body":"Tìm kiếm toàn văn trong tệp PDF, Word, Excel và PowerPoint, văn bản thuần và Markdown, mã nguồn bằng 32 ngôn ngữ, JSON, CSV và YAML, thư điện tử, và bên trong tệp lưu trữ zip, 7z và tar mà không cần giải nén. Một trình xem đi qua từng kết quả khớp trong ngữ cảnh.","featuresPage.cards.audio.title":"Âm thanh theo cách nó vang lên","featuresPage.cards.audio.body":"Được đo, không phải được gắn thẻ: độ to tính bằng LUFS, true peak, khoảng lặng, dải động, độ dài, codec, tần số lấy mẫu và số kênh. Sắp xếp theo độ to hoặc độ dài, và phát một tệp trong khung xem trước mà không rời khỏi danh sách.","featuresPage.cards.properties.title":"Những gì một tệp tự nói về mình","featuresPage.cards.properties.body":"Bảy mươi hai thuộc tính đọc từ header của tệp và tìm kiếm được như mọi công cụ sửa đổi khác: kích thước ảnh và dữ liệu máy ảnh, codec và thời lượng video, tác giả và số trang tài liệu, kiến trúc và chữ ký của chương trình, phiên bản trình cài đặt, đích của lối tắt, nội dung tệp lưu trữ, phông chữ, header thư điện tử và bảng cơ sở dữ liệu. Bất kỳ thuộc tính nào cũng có thể thành một cột.","featuresPage.cards.similar.title":"Những cái tên chỉ gần giống","featuresPage.cards.similar.body":"Ống kính tương đồng tìm những cái tên gần với những gì bạn gõ — một lỗi đánh máy, một số phiên bản, một tiền tố khác — và một lần tìm không thấy gì sẽ gợi ý cái tên thật gần nhất như một lần sửa chỉ bằng một cú nhấp.","featuresPage.cards.results.title":"Mọi điều bạn làm với một kết quả","featuresPage.cards.results.body":"Mở, hiện trong thư mục, Mở bằng, sao chép đường dẫn, tên, nội dung hoặc chính tệp, mở terminal tại đó, và chạy các lệnh do bạn tự định nghĩa. Phím cách mở Xem nhanh, âm thanh và video phát ngay trong khung xem trước, và số lượng kết quả mở ra thống kê cho toàn bộ tập kết quả.","featuresPage.cards.rename.title":"Đổi tên, hoàn tác, dọn dẹp","featuresPage.cards.rename.body":"Đổi tên cả một nhóm kết quả bằng tìm và thay thế, biểu thức chính quy, bộ đếm và đổi chữ hoa/thường, được xem trước trước khi làm và bị từ chối nếu hai tên sẽ trùng nhau. Hoàn tác đảo ngược một lần đổi tên, kể cả sau khi khởi động lại. Tìm tệp trùng lặp và thư mục trống ngay từ chỉ mục.","featuresPage.cards.everything.title":"Quen thuộc ngay nếu bạn đến từ Everything","featuresPage.cards.everything.body":"Cú pháp tìm kiếm, bộ lọc nhanh và danh sách tệp của Everything, cả nhập lẫn xuất, cộng thêm CSV, văn bản thuần, danh sách phát và NDJSON. Một chế độ nghiêm ngặt kiểm tra rằng truy vấn chỉ dùng những gì Everything hiểu được.","featuresPage.cards.cli.title":"Một dòng lệnh cho các tập lệnh","featuresPage.cards.cli.body":"Lệnh freally dùng cùng ngôn ngữ truy vấn, in ra JSON, NDJSON, CSV hoặc đường dẫn phân cách bằng NUL, trả về mã thoát có ý nghĩa, và hỗ trợ tự hoàn thành trong bash, zsh, fish và PowerShell.","featuresPage.cards.portable.title":"Di động, nếu bạn muốn","featuresPage.cards.portable.body":"Chạy từ một USB: chỉ mục, cài đặt, dấu trang và nhật ký nằm trong một thư mục Data bên cạnh ứng dụng, và không có gì được đăng ký vào chiếc máy tính mà USB đang cắm vào.","featuresPage.cards.languages.title":"Mười tám ngôn ngữ, sáng hoặc tối","featuresPage.cards.languages.body":"Menu, cài đặt và mọi hộp thoại đổi ngôn ngữ ngay lập tức, và tiếng Ả Rập được trình bày từ phải sang trái. Ứng dụng theo giao diện sáng hoặc tối của hệ thống, hoặc giữ giao diện bạn chọn.","featuresPage.compare.title":"Đặt cạnh các công cụ thương mại","featuresPage.compare.intro":"Freally Sourcerer 1.0 đặt cạnh các công cụ tìm kiếm trên máy tính thương mại mà mọi người đang dùng hiện nay. Mỗi ô cho một sản phẩm khác đều lấy từ chính các trang của nhà sản xuất, được kiểm tra vào ngày 2 tháng 10 năm 2026, và giá là giá niêm yết tại Mỹ vào tháng 10 năm 2026 — trừ khi nhà sản xuất không công bố giá tại Mỹ, điều mà ô đó sẽ ghi rõ.","featuresPage.compare.legend.yes":"có","featuresPage.compare.legend.partly":"một phần","featuresPage.compare.legend.no":"không","featuresPage.compare.legend.unknown":"chưa xác minh","featuresPage.compare.feature":"Tính năng","featuresPage.compare.note.beta":"đang beta","featuresPage.compare.row.price":"Giá (USD, tháng 10 năm 2026)","featuresPage.compare.freeToday":"Hiện miễn phí","featuresPage.compare.note.freeware":"phần mềm miễn phí","featuresPage.compare.note.oneTime":"trả một lần","featuresPage.compare.note.perYear":"mỗi năm, gói Basic","featuresPage.compare.note.euros":"trả một lần, chỉ bằng euro","featuresPage.compare.row.systems":"Windows, macOS và Linux","featuresPage.compare.row.liveIndex":"Tìm tệp theo tên từ một chỉ mục luôn được cập nhật khi tệp thay đổi","featuresPage.compare.note.scheduled":"chỉ mục cập nhật theo lịch","featuresPage.compare.note.spotlight":"chỉ mục của Spotlight","featuresPage.compare.note.chosenFolders":"các thư mục bạn chọn","featuresPage.compare.row.content":"Tìm chữ bên trong tài liệu như tệp PDF và Office","featuresPage.compare.note.notIndexed":"không lập chỉ mục, chậm","featuresPage.compare.row.audio":"Tìm âm thanh theo độ to đo được, codec, tần số lấy mẫu hoặc độ dài","featuresPage.compare.note.noLoudness":"không có độ to","featuresPage.compare.note.tagsBitRate":"thẻ và bit rate","featuresPage.compare.note.mp3Tags":"thẻ MP3 và FLAC","featuresPage.compare.row.properties":"Tìm những gì header của tệp ghi: kích thước ảnh, máy ảnh, tác giả, số trang","featuresPage.compare.note.exifIptc":"EXIF và IPTC","featuresPage.compare.row.similar":"Tìm một tệp từ một cái tên chỉ gần giống","featuresPage.compare.note.similarWords":"từ tương tự trong tài liệu","featuresPage.compare.row.cli":"Một dòng lệnh để tìm kiếm","featuresPage.compare.row.portable":"Chạy mà không cần cài đặt, từ một USB","featuresPage.compare.row.duplicates":"Tìm tệp trùng lặp","featuresPage.compare.summary":"Nói ngắn gọn: chỉ Sourcerer có tất cả — cả ba hệ thống, chỉ mục trực tiếp, chữ bên trong tài liệu, âm thanh theo độ to, những gì header của tệp ghi, và những cái tên chỉ gần giống.","featuresPage.compare.theyWin":"Những chỗ họ hơn: Everything không mất tiền, và bản beta 1.5 của nó còn tìm được tệp theo mã băm; FileLocator Pro tìm trong tệp thư của Outlook; Copernic còn tìm trong Google Drive, Dropbox và OneDrive; và DocFetcher Pro tìm trong tài liệu những từ tương tự với từ bạn đã gõ.","featuresPage.compare.asOf":"Cột của Sourcerer là phiên bản 1.0, bản chưa ra mắt, và giá của nó là giá hiện nay: Sourcerer hiện miễn phí, và các phiên bản sau này có thể được bán. Các sản phẩm khác cũng thay đổi; bảng này đúng tại ngày 2 tháng 10 năm 2026.","featuresPage.why.title":"Vì sao nó được làm như vậy","featuresPage.why.journal.title":"Nó lắng nghe thay vì quét lại","featuresPage.why.journal.body":"Mọi hệ thống vốn đã ghi lại các thay đổi đối với tệp của mình. Sourcerer đọc bản ghi đó thay vì định kỳ đi qua các thư mục của bạn, nên chỉ mục luôn cập nhật mà không phải đọc lại ổ đĩa.","featuresPage.why.lazy.title":"Nó chỉ đọc những gì câu hỏi cần","featuresPage.why.lazy.body":"Thuộc tính của một tệp được đọc vào lần đầu tiên một lần tìm kiếm hỏi đến nó, chỉ từ header, và được giữ lại cho đến khi tệp thay đổi. Không có gì giải mã một bức ảnh hay mở các hàng của một cơ sở dữ liệu chỉ để trả lời một bức ảnh rộng bao nhiêu.","featuresPage.why.honest.title":"Nó nói ra những gì nó không nhìn thấy","featuresPage.why.honest.body":"Một thư mục không đọc được trông y hệt một thư mục trống, nên Sourcerer nêu tên những thư mục nó đã bỏ qua và lý do. Một con số đã chạm giới hạn được hiển thị là mức tối thiểu, không bao giờ là một con số chính xác.","featuresPage.why.careful.title":"Nó cẩn thận với tệp của bạn","featuresPage.why.careful.body":"Một lần đổi tên được xem trước và diễn ra trọn vẹn hoặc không diễn ra chút nào, một tệp bị xóa sẽ vào Thùng rác hoặc Recycle Bin, và một lệnh của riêng bạn chạy dưới dạng chương trình có đối số, không bao giờ dưới dạng một dòng shell, sau khi hỏi bạn một lần.","featuresPage.why.local.title":"Mọi thứ ở lại trên máy của bạn","featuresPage.why.local.body":"Không có đo từ xa. Chỉ mục nằm trên chính ổ đĩa của bạn, và không có gì về tệp hay các lần tìm kiếm của bạn được gửi đi đâu cả. Việc kiểm tra cập nhật chỉ hỏi xem có phiên bản mới hơn không, và bạn có thể tắt nó.","featuresPage.why.everything.title":"Nó tôn trọng những gì bạn đã biết","featuresPage.why.everything.body":"Cú pháp, bộ lọc và danh sách tệp của Everything hoạt động y như ở đó, được kiểm chứng bằng các bài kiểm thử, nên thói quen nhiều năm được giữ nguyên — trên thêm hai hệ điều hành nữa.","featuresPage.coming.title":"Những gì vẫn đang đến","featuresPage.coming.intro":"Nói thẳng ra, vì một danh sách tính năng che giấu chỗ thiếu thì không đáng đọc. Trang này mô tả phiên bản 1.0, và Sourcerer được xây dựng từng phiên bản một: các phiên bản sau 0.23 vẫn còn ở phía trước. Mỗi phiên bản trên con đường đến 1.0 đều được đánh dấu trạng thái.","featuresPage.coming.lenses":"Hai trong năm ống kính — chữ bên trong tệp và những cái tên chỉ gần giống — đã được xây dựng nhưng chưa được kết nối với việc tìm kiếm. Chúng có trên trang này vì chúng nằm trong 1.0.","featuresPage.coming.done":"đã dựng và gắn thẻ, nhưng chưa phải bản tải xuống","featuresPage.coming.planned":"vẫn cần xây dựng, trên đường đến 1.0","featuresPage.coming.goal":"chính phiên bản 1.0, và những bản tải xuống đầu tiên trang này sẽ cung cấp","featuresPage.coming.ladder":"Xem mọi nấc trên con đường đến 1.0","featuresPage.limits.title":"Những gì 1.0 không làm","featuresPage.limits.headers":"Nó chỉ đọc thuộc tính từ header của tệp: nó không giải mã ảnh, phát video hay kết xuất tài liệu để tìm chúng, nên một thuộc tính mà header không mang thì không thể tìm kiếm được.","featuresPage.limits.firstIndex":"Trên macOS và Linux, lần lập chỉ mục đầu tiên đi qua từng thư mục, nên trên một ổ đĩa lớn sẽ mất vài phút thay vì vài giây.","featuresPage.limits.portable":"Bản di động không tự cập nhật: hãy thay thư mục của nó bằng một phiên bản mới hơn.","featuresPage.coming.downloads":"Không có bản tải xuống nào trước phiên bản 1.0, và cũng không có trên trang này.","docs.title":"Tài liệu","docs.intro":"Cách dùng Freally Sourcerer như nó đang được xây dựng hiện nay, trên con đường đến 1.0; hướng dẫn này lớn dần theo mỗi phiên bản. Trên macOS, hãy hiểu Ctrl là Cmd: các menu hiển thị phím của chính hệ thống bạn.","search.placeholder":"Tìm kiếm trong tài liệu","docs.contents":"Mục lục","docs.start.title":"Bắt đầu","docs.search.title":"Tìm kiếm","docs.lenses.title":"Năm ống kính","docs.syntax.title":"Cú pháp truy vấn","docs.filters.title":"Bộ lọc nhanh","docs.bookmarks.title":"Dấu trang và thanh bên","docs.results.title":"Làm việc với kết quả","docs.rename.title":"Đổi tên hàng loạt","docs.preview.title":"Xem trước và Xem nhanh","docs.drives.title":"Ổ đĩa đã rút ra và danh sách tệp","docs.health.title":"Tình trạng chỉ mục và thư mục bị bỏ qua","docs.portable.title":"Chế độ di động","docs.settings.title":"Cài đặt và phím tắt toàn cục","docs.language.title":"Ngôn ngữ","docs.cli.title":"Dòng lệnh","docs.privacy.title":"Quyền riêng tư và mạng","docs.faq.title":"Câu hỏi","docs.start.p1":"Sourcerer chạy thành hai phần: một trình lập chỉ mục chạy nền, <code>freally-indexd</code>, giữ cho chỉ mục luôn cập nhật, và ứng dụng mà bạn dùng để tìm kiếm. Trình cài đặt thiết lập cả hai, và trình lập chỉ mục khởi động khi bạn đăng nhập.","docs.start.id":"Mã định danh của ứng dụng là <code>com.freallyproducts.sourcerer</code>, và cài đặt, dấu trang cùng chỉ mục của bạn được lưu dưới tên đó trong thư mục dữ liệu ứng dụng của hệ thống. Các phiên bản đến 0.23.2 dùng <code>io.mikeweaver.freally</code>; phiên bản mới hơn sẽ chuyển thư mục đó sang tên mới ở lần khởi động đầu tiên, nên không có gì phải lập chỉ mục lại.","docs.start.p2":"Lần đầu tiên ứng dụng mở ra, một bước thiết lập ngắn sẽ hỏi những thư mục nào cần lập chỉ mục, phím tắt dùng để gọi ứng dụng lên, cùng ngôn ngữ và giao diện của bạn. Bạn có thể đổi tất cả những thứ đó sau trong Cài đặt.","docs.start.p3":"Sau đó nó xây dựng chỉ mục. Trên Windows nó đọc nhật ký thay đổi NTFS, việc này nhanh; trên macOS và Linux nó đi qua các thư mục của bạn, việc này mất vài phút trên một ổ đĩa lớn. Bạn có thể tìm kiếm trong lúc nó làm việc: kết quả sẽ lần lượt hiện ra.","docs.start.p4":"Chưa có bản tải xuống nào trước phiên bản 1.0.0, và mã nguồn là riêng tư.","docs.search.type":"Gõ vào thanh tìm kiếm. Kết quả hiện ra ngay khi bạn gõ, được nhóm theo ống kính, mỗi nhóm kèm thời gian nó cần. Mỗi ký tự lại thu hẹp kết quả; không có gì phải gửi đi.","docs.search.move":"Di chuyển qua các kết quả bằng phím mũi tên, và nhấn Enter hoặc nhấp đúp vào một hàng để mở tệp bằng ứng dụng thường dùng cho nó.","docs.search.within":"<kbd>Ctrl+Shift+F</kbd> tìm trong những kết quả bạn đã có. Mỗi cụm từ trở thành một thẻ chip mà bạn có thể gỡ riêng, nên bạn có thể lùi lại mà không phải gõ lại.","docs.search.bold":"Những gì bạn gõ được hiển thị <strong>in đậm</strong> trong tên và đường dẫn. Một công cụ sửa đổi như <code>ext:json</code> thu hẹp danh sách chứ không phải là thứ bạn đang tìm, nên nó không được đánh dấu.","docs.search.clear":"<kbd>Esc</kbd> xóa thanh tìm kiếm.","docs.lenses.intro":"Sourcerer có năm ống kính, tất cả cùng đọc một chỉ mục. Hiện nay ống kính tên tệp, âm thanh và thuộc tính trả lời các lần tìm kiếm của bạn; ống kính nội dung và tương đồng đã được xây dựng nhưng chưa được kết nối với thanh tìm kiếm — việc đó sẽ đến trên con đường đến 1.0.","docs.lenses.filename":"Tên tệp: tên và đường dẫn, với ký tự đại diện, biểu thức chính quy và các công cụ sửa đổi của Everything. Nhanh nhất trong năm ống kính.","docs.lenses.content":"Nội dung: chữ bên trong tệp PDF, Word, Excel và PowerPoint, văn bản thuần và Markdown, mã nguồn bằng 32 ngôn ngữ, JSON, CSV và YAML, thư điện tử, và tệp lưu trữ zip, 7z và tar, mà không cần giải nén. Chưa được kết nối với thanh tìm kiếm.","docs.lenses.audio":"Âm thanh: những gì một tệp âm thanh đo được — độ to tính bằng LUFS, khoảng lặng, dải động, độ dài, codec và tần số lấy mẫu — được tính vào lần đầu tiên một lần tìm kiếm hỏi đến, và được giữ lại cho đến khi tệp thay đổi.","docs.lenses.properties":"Thuộc tính: những gì chính header của tệp ghi — bảy mươi hai thuộc tính cho ảnh, dữ liệu máy ảnh, video, tài liệu, chương trình, trình cài đặt, lối tắt, tệp lưu trữ, phông chữ, thư điện tử và cơ sở dữ liệu SQLite.","docs.lenses.similar":"Tương đồng: những cái tên gần với những gì bạn gõ, cho những lúc bạn chỉ nhớ mang máng về một tệp. Chưa được kết nối với thanh tìm kiếm; cho đến khi đó, một lần tìm không thấy gì sẽ gợi ý cái tên thật gần nhất thay vào đó.","docs.lenses.prefix":"Có thể bật và tắt các ống kính trong <strong>Xem → Ống kính</strong>.","docs.syntax.intro":"Sourcerer hiểu cú pháp Everything của voidtools, và bổ sung các công cụ sửa đổi cho những ống kính khác của nó.","docs.syntax.basics":"Những điều cơ bản","docs.syntax.terms":"Từ thông thường khớp ở bất kỳ đâu trong tên, và mọi từ đều phải khớp: <code>report 2024</code>.","docs.syntax.wildcards":"<code>*</code> khớp với một chuỗi ký tự bất kỳ và <code>?</code> với một ký tự, so với toàn bộ tên: <code>invoice_202?.pdf</code>.","docs.syntax.boolean":"Dấu cách hoặc <code>AND</code> nghĩa là cả hai, <code>|</code> hoặc <code>OR</code> là một trong hai, <code>!</code> hoặc <code>NOT</code> là không, và dấu ngoặc dùng để nhóm: <code>(budget | forecast) !draft</code>.","docs.syntax.regex":"<code>regex:</code> bắt đầu một biểu thức chính quy: <code>regex:^report-\\d+</code>. Cú pháp là của Rust, nên không có tham chiếu ngược và không có lookaround.","docs.syntax.modifiers":"Công cụ sửa đổi","docs.syntax.modifiersIntro":"Công cụ sửa đổi thu hẹp kết quả theo những gì đã biết về một tệp. Kết hợp bao nhiêu tùy thích.","docs.syntax.col.modifier":"Công cụ sửa đổi","docs.syntax.col.matches":"Nó khớp với gì","docs.syntax.col.example":"Ví dụ","docs.syntax.mod.size":"Kích thước, với kb, mb và gb, phép so sánh và khoảng","docs.syntax.mod.date":"Ngày sửa đổi; <code>dc:</code> ngày tạo, <code>da:</code> ngày truy cập","docs.syntax.mod.ext":"Phần mở rộng, một hoặc nhiều cái phân cách bằng dấu chấm phẩy","docs.syntax.mod.attrib":"Thuộc tính tệp, chẳng hạn như ẩn","docs.syntax.mod.path":"Đường dẫn đầy đủ chứa đoạn văn bản đó","docs.syntax.mod.parent":"Tệp nằm trực tiếp trong thư mục đó","docs.syntax.mod.anchors":"Tên bắt đầu bằng, hoặc kết thúc bằng, đoạn văn bản đó","docs.syntax.mod.loudness":"Độ to đo được tính bằng LUFS, và dải động tính bằng dB","docs.syntax.mod.length":"Độ dài của một tệp âm thanh","docs.syntax.mod.codec":"Codec âm thanh, và tần số lấy mẫu tính bằng Hz","docs.syntax.mod.silence":"Bao nhiêu phần của tệp âm thanh là im lặng, từ 0 đến 1","docs.syntax.mod.property":"Bất kỳ thuộc tính nào trong bảy mươi hai thuộc tính; <code>property:</code> là dạng đầy đủ","docs.syntax.mod.dupe":"Các tệp có cùng tên và cùng kích thước; <code>name-dupe:</code> và <code>size-dupe:</code> chỉ so một trong hai","docs.syntax.mod.empty":"Tệp và thư mục trống; <code>empty:roots</code> tìm đỉnh của mỗi chuỗi thư mục không chứa tệp nào","docs.syntax.mod.children":"Thư mục theo số mục chúng chứa trực tiếp; <code>descendant-count:</code> ở mọi độ sâu","docs.syntax.mod.volume":"Các tệp trên một ổ đĩa, theo tên của ổ, kể cả khi ổ đã được rút ra","docs.syntax.modes":"Chế độ khớp","docs.syntax.modesMenu":"Menu <strong>Tìm kiếm</strong> bật/tắt Phân biệt chữ hoa/thường (<kbd>Ctrl+I</kbd>), Khớp toàn bộ từ (<kbd>Ctrl+B</kbd>), Khớp đường dẫn (<kbd>Ctrl+U</kbd>) và Khớp dấu thanh (<kbd>Ctrl+M</kbd>).","docs.syntax.ignore":"<strong>Bỏ qua dấu câu</strong> cho phép <code>foobar</code> tìm thấy <code>foo-bar</code>, và <strong>Bỏ qua khoảng trắng</strong> cho phép <code>myreport</code> tìm thấy <code>my report</code>. Cả hai đều tắt theo mặc định.","docs.syntax.cjk":"<strong>Khớp phiên âm CJK</strong> tìm tên tiếng Trung, tiếng Nhật và tiếng Hàn theo cách đọc: <code>wenjian</code> tìm thấy 文件.","docs.syntax.regexBuilder":"<strong>Bật regex</strong> (<kbd>Ctrl+R</kbd>) coi toàn bộ truy vấn là một biểu thức chính quy. Trình tạo biểu thức chính quy cạnh thanh tìm kiếm kiểm tra một mẫu với các tên trên màn hình ngay khi bạn gõ, kèm thông báo lỗi của chính bộ máy nếu mẫu không hợp lệ.","docs.filters.p1":"Bộ lọc nhanh giới hạn kết quả vào một loại tệp chỉ bằng một cú nhấp: Âm thanh, Đã nén, Tài liệu, Tệp thực thi, Thư mục, Hình ảnh và Video. Mỗi bộ lọc chứa mọi phần mở rộng mà bộ lọc của chính Everything có, và nhiều hơn — 65 loại âm thanh, 79 video, 77 hình ảnh, 86 tài liệu và 70 tệp lưu trữ.","docs.filters.p2":"Bạn cũng có thể gõ chúng, với những bí danh dễ đoán: <code>audio:</code>, <code>video:</code>, <code>image:</code>, <code>document:</code>, <code>executable:</code> và <code>archive:</code>, hoặc <code>music:</code>, <code>photos:</code>, <code>docs:</code> và <code>zip:</code>.","docs.filters.p3":"Mã nguồn không được xếp vào Tài liệu, khác với Everything; <code>ext:c;cpp;h</code> mang tập đó trở lại. Để giữ một lần tìm kiếm của riêng bạn thành bộ lọc, hãy chọn <strong>Tìm kiếm → Thêm vào bộ lọc…</strong>, và chỉnh sửa chúng bằng <strong>Sắp xếp bộ lọc…</strong> (<kbd>Ctrl+Shift+O</kbd>).","docs.bookmarks.add":"<kbd>Ctrl+D</kbd> lưu lần tìm kiếm hiện tại thành dấu trang, và <kbd>Ctrl+Shift+B</kbd> sắp xếp chúng.","docs.bookmarks.recall":"Gõ <code>:</code> rồi đến tên một dấu trang để chạy nó.","docs.bookmarks.sidebar":"<strong>Xem → Thanh bên</strong> hiển thị một cột với các dấu trang, bộ lọc nhanh, ổ đĩa và các lần tìm kiếm gần đây của bạn. Kéo dấu trang để sắp xếp lại; nhấp vào một ổ đĩa để chỉ tìm trên ổ đó.","docs.bookmarks.history":"Các lần tìm kiếm gần đây không được ghi lại khi Chế độ riêng tư đang bật hoặc lịch sử tìm kiếm đã tắt.","docs.results.intro":"Mỗi hàng là một tệp thật trên ổ đĩa của bạn. Nhấp chuột phải vào một hàng để xem những gì bạn có thể làm với nó:","docs.results.open":"Mở, Hiện trong trình quản lý tệp, và Mở bằng, mục liệt kê những ứng dụng mà hệ thống của bạn đã đăng ký cho loại tệp đó.","docs.results.copy":"Sao chép nội dung để lấy phần thân của một tệp văn bản, Sao chép dưới dạng tệp để dán chính tệp vào một thư mục, và Sao chép danh sách đường dẫn — mỗi dòng một đường dẫn, trong dấu ngoặc kép, cách nhau bằng dấu cách hoặc thoát ký tự cho shell.","docs.results.hits":"Xem kết quả khớp trong ngữ cảnh hiển thị mọi chỗ khớp trong một tài liệu; <kbd>F3</kbd> và <kbd>Shift+F3</kbd> đi qua từng chỗ.","docs.results.terminal":"Mở terminal tại đây mở một terminal trong thư mục của tệp.","docs.results.commands":"Các lệnh của riêng bạn, từ <strong>Cài đặt → Chung → Lệnh tùy chỉnh</strong>, với <code>{path}</code>, <code>{dir}</code>, <code>{name}</code>, <code>{stem}</code> và <code>{ext}</code> trong đối số. Mỗi lệnh chạy dưới dạng chương trình có đối số, không bao giờ dưới dạng một dòng shell, và ứng dụng sẽ hỏi một lần trước khi một chương trình chạy lần đầu.","docs.results.delete":"Xóa chuyển tệp vào Thùng rác hoặc Recycle Bin.","docs.results.view":"Kéo một hàng vào ứng dụng khác như kéo từ trình quản lý tệp. Nhấp vào tiêu đề cột để sắp xếp, hoặc dùng <kbd>Ctrl+1</kbd> đến <kbd>Ctrl+9</kbd>; dấu <strong>+</strong> ở cuối hàng tiêu đề thêm một thuộc tính thành cột. Menu <strong>Xem</strong> chuyển giữa Chi tiết và Hình thu nhỏ. Nhấp vào số lượng kết quả trên thanh trạng thái để xem thống kê cho toàn bộ tập kết quả: kích thước và số lượng theo loại, cùng các tệp lớn nhất, cũ nhất và mới nhất.","docs.rename.intro":"Chọn các kết quả cần đổi tên và nhấn <kbd>F2</kbd>. Bạn mô tả thay đổi một lần, và mọi tên cũ lẫn tên mới đều được hiển thị trước khi có bất cứ thứ gì chạm vào ổ đĩa.","docs.rename.find":"Tìm và thay thế, dưới dạng văn bản thường hoặc biểu thức chính quy, với <code>$1</code>, <code>$2</code> cho những gì nó bắt được.","docs.rename.number":"<code>{n}</code> trong phần thay thế đánh số các tệp theo thứ tự của bản xem trước; <code>{n:03}</code> độn số đó thành ba chữ số.","docs.rename.case":"Đổi chữ hoa/thường, và chọn xem quy tắc áp dụng chỉ cho tên hay cho cả phần mở rộng. Theo mặc định, phần mở rộng được giữ nguyên.","docs.rename.check":"Những hàng sẽ trùng nhau, ghi đè lên một tệp hoặc tạo ra một tên mà hệ thống từ chối sẽ được đánh dấu, và không có gì được đổi tên khi còn hàng nào bị đánh dấu: cả loạt diễn ra trọn vẹn hoặc không diễn ra chút nào.","docs.rename.undo":"<kbd>Ctrl+Z</kbd> hoàn tác một lần đổi tên, kể cả sau khi bạn khởi động lại ứng dụng, và <kbd>Ctrl+Shift+Z</kbd> làm lại nó. Trên Windows và Linux, Hoàn tác còn đưa tệp đã xóa trở về từ Recycle Bin hoặc Thùng rác. Trên macOS thì không thể: bạn hãy tự khôi phục tệp từ Thùng rác.","docs.preview.pane":"<strong>Xem → Xem trước</strong> (<kbd>Alt+P</kbd>) hiển thị tệp đang chọn bên cạnh kết quả: ảnh, văn bản và mã, và tài liệu.","docs.preview.play":"Âm thanh và video phát ngay trong khung, với phát và tạm dừng, tua, lặp lại và âm lượng. Âm thanh vẽ ra một dạng sóng mà bạn có thể nhấp vào, kèm codec, tần số lấy mẫu, số kênh và độ to bên dưới.","docs.preview.quickLook":"<kbd>Space</kbd> mở Xem nhanh, một bản xem trước lớn phủ lên cửa sổ. Các phím mũi tên vẫn di chuyển qua kết quả khi nó đang mở, và <kbd>Space</kbd> hoặc <kbd>Esc</kbd> đóng nó lại.","docs.preview.mac":"Trên macOS, Xem nhanh còn đề nghị mở tệp bằng Xem nhanh của chính macOS, cho những định dạng mà hệ thống hiển thị được còn Sourcerer thì không.","docs.drives.unplugged":"Khi bạn rút một ổ đĩa ra, mọi thứ đã được lập chỉ mục trên nó vẫn tìm kiếm được. Kết quả của nó mang một nhãn ghi tên ổ đĩa, nên chúng cũng cho biết một tệp nằm trên ổ nào, và <code>volume:</code> tìm trên một ổ đĩa theo tên của nó. Một ổ đĩa quay lại với ký tự ổ hoặc điểm gắn kết khác vẫn được nhận ra.","docs.drives.lists":"<strong>Tệp → Xuất kết quả…</strong> (<kbd>Ctrl+S</kbd>) lưu kết quả dưới dạng danh sách tệp <code>.efu</code> của Everything, CSV, văn bản thuần, một danh sách phát M3U gồm các tệp âm thanh, hoặc NDJSON cho tập lệnh. <strong>Tệp → Mở danh sách tệp…</strong> (<kbd>Ctrl+O</kbd>) tìm bên trong một danh sách, kể cả danh sách của Everything, thay vì trong chỉ mục, cho đến khi bạn chọn <strong>Đóng danh sách tệp</strong>.","docs.health.index":"<strong>Công cụ → Bảo trì chỉ mục → Tình trạng chỉ mục…</strong> cho biết, với từng nơi đang được theo dõi, thay đổi đến theo thời gian thực hay chỉ khi quét lại, chỉ mục chậm bao xa, và bao nhiêu thay đổi đã bị bỏ mất. Khi có gì đó sai, nó nói rõ là gì, kèm nút dựng lại chỉ bằng một cú nhấp nếu đó là cách khắc phục.","docs.health.permissions":"Một thư mục mà ứng dụng không đọc được trông y hệt một thư mục trống. <strong>Tình trạng quyền truy cập…</strong>, trong cùng menu đó hoặc từ nhãn \"thư mục bị bỏ qua\" trên thanh trạng thái, liệt kê các thư mục đã bị bỏ qua, lý do hệ thống đưa ra, và cách khắc phục. Trên macOS, nó kiểm tra xem Quyền truy cập toàn bộ đĩa đã được cấp chưa và mở đúng trang cài đặt nếu chưa.","docs.portable.p1":"Để chạy Sourcerer từ một USB, hãy đặt một tệp trống tên là <code>portable.flag</code> cạnh ứng dụng, hoặc khởi động nó với <code>--portable</code>. Khi đó chỉ mục, cài đặt, dấu trang và nhật ký nằm trong một thư mục <code>Data</code> cạnh ứng dụng, và không có gì được đăng ký vào máy tính: không có dịch vụ chạy nền, không có trình xử lý liên kết và không có trình cập nhật. Hãy cập nhật bản di động bằng cách thay thư mục của nó.","docs.portable.mac":"Trên macOS, thư mục <code>Data</code> được tạo cạnh ứng dụng, không phải bên trong, vì ghi vào bên trong một ứng dụng sẽ làm hỏng chữ ký của nó.","docs.settings.open":"<strong>Công cụ → Tùy chọn…</strong> (<kbd>Ctrl+,</kbd>) mở Cài đặt, được bố trí giống cửa sổ Options của Everything: một cây bảng điều khiển ở bên trái, một ô phía trên lọc các bảng và tùy chọn ngay khi bạn gõ, cùng các nút <strong>OK</strong>, <strong>Hủy</strong> và <strong>Áp dụng</strong>.","docs.settings.panels":"Các bảng bao gồm giao diện của ứng dụng, cách tìm kiếm hoạt động, kết quả, phím tắt, các thư mục, ổ đĩa và mục loại trừ tạo nên chỉ mục, từng ống kính, quyền riêng tư và cập nhật, nhật ký, sao lưu và đặt lại, và ngôn ngữ.","docs.settings.hotkey":"Một phím tắt toàn cục gọi ứng dụng lên từ bất cứ đâu, với thanh tìm kiếm sẵn sàng. Đặt nó trong <strong>Cài đặt → Chung → Bàn phím</strong>. Một liên kết dạng <code>freally://search?q=…</code> mở ứng dụng với lần tìm kiếm đó.","docs.language.p1":"Sourcerer nói được mười tám ngôn ngữ. Chọn một ngôn ngữ trong <strong>Cài đặt → Ngôn ngữ</strong> và toàn bộ ứng dụng — menu, cài đặt, hộp thoại và thanh trạng thái — đổi ngay lập tức, không cần khởi động lại. Tiếng Ả Rập trình bày cửa sổ từ phải sang trái.","docs.cli.intro":"Lệnh <code>freally</code> tìm trong cùng chỉ mục với ứng dụng, qua cùng trình lập chỉ mục, bằng cùng ngôn ngữ truy vấn.","docs.cli.formats":"<code>--json</code>, <code>--ndjson</code> và <code>--csv</code> in kết quả cho tập lệnh, <code>-0</code> in đường dẫn phân cách bằng NUL cho <code>xargs -0</code>, và <code>--fields</code> chọn các cột. Mã thoát cho biết có gì khớp hay không.","docs.cli.strict":"<code>--strict-everything</code> từ chối mọi truy vấn dùng thứ mà Everything không có, và nêu tên thứ đó — cách để kiểm tra rằng một truy vấn chạy được ở cả hai bên.","docs.cli.manage":"<code>freally index</code> hiển thị trạng thái của trình lập chỉ mục và có thể tạm dừng, tiếp tục, xác minh, nén gọn hoặc dựng lại nó; <code>freally bookmark</code> lưu, liệt kê và xóa dấu trang.","docs.cli.completions":"<code>freally completions</code> in phần tự hoàn thành cho bash, zsh, fish và PowerShell, bao gồm tên các công cụ sửa đổi và dấu trang của bạn.","docs.privacy.telemetry":"Không có đo từ xa. Chỉ mục được xây dựng và lưu trên chính máy tính của bạn, và không có gì về tệp hay các lần tìm kiếm của bạn được gửi đi đâu cả.","docs.privacy.updates":"Ứng dụng hỏi xem có phiên bản mới hơn không mỗi ngày một lần; trong <strong>Cài đặt → Quyền riêng tư &amp; Cập nhật</strong> bạn có thể đổi thành hằng tuần, hằng tháng hoặc không bao giờ, hoặc kiểm tra ngay. Nó hỏi trước khi cài đặt bất cứ thứ gì, kèm tên cả hai phiên bản, và bản di động không bao giờ kiểm tra.","docs.privacy.mode":"Chế độ riêng tư ngừng ghi lại các lần tìm kiếm gần đây và tắt ống kính thuộc tính, thứ đọc vào bên trong tệp.","docs.privacy.reports.title":"Báo cáo sự cố","docs.privacy.reports.where":"Khi ứng dụng gặp lỗi, thông báo lỗi có một nút <strong>Báo cáo</strong> bên cạnh. Sau một lần sự cố, lần khởi chạy tiếp theo sẽ đưa ra <strong>Báo cáo</strong> hoặc <strong>Bỏ qua</strong>.","docs.privacy.reports.page":"<strong>Báo cáo</strong> mở trang báo cáo, <code>freallyproducts.com/freally-sourcerer/report/</code>, trong trình duyệt của bạn, với các thông tin kỹ thuật đã được điền sẵn: bạn có thể đọc nhưng không thể thay đổi chúng. Bạn thêm vào những gì mình đang làm và, nếu muốn, một địa chỉ email.","docs.privacy.reports.send":"Không có gì được gửi đi trừ khi bạn nhấn <strong>Gửi</strong> trên trang đó, và không bao giờ có gì được gửi đi trong nền.","docs.faq.missing.title":"Vì sao một tệp không có trong kết quả?","docs.faq.missing.indexing":"Lần lập chỉ mục đầu tiên có thể vẫn đang chạy: thanh trạng thái sẽ cho biết.","docs.faq.missing.roots":"Thư mục của nó có thể chưa được lập chỉ mục: hãy kiểm tra các thư mục, ổ đĩa và mục loại trừ trong <strong>Cài đặt → Chỉ mục</strong>.","docs.faq.missing.permissions":"Thư mục của nó có thể không đọc được: hãy mở <strong>Tình trạng quyền truy cập…</strong>.","docs.faq.smaller.title":"Làm sao để chỉ mục nhỏ hơn?","docs.faq.smaller.body":"Loại trừ những thư mục đầy tệp mà bạn không bao giờ tìm, chẳng hạn <code>node_modules</code> và <code>.git</code>, trong <strong>Cài đặt → Chỉ mục → Loại trừ</strong>.","docs.faq.rebuild.title":"Làm sao để bắt đầu lại chỉ mục?","docs.faq.rebuild.body":"<strong>Công cụ → Bảo trì chỉ mục → Buộc dựng lại chỉ mục…</strong> xóa chỉ mục và xây dựng lại từ đầu. <strong>Xác minh chỉ mục…</strong> và <strong>Nén gọn chỉ mục…</strong> trong cùng menu đó kiểm tra chỉ mục và làm cho nó nhỏ hơn.","search.none":"Không có gì trên trang này khớp với điều đó.","changelog.5f64b4441a71":"Mọi thay đổi đáng chú ý đều được ghi lại ở đây. Định dạng: <a href=\"https://keepachangelog.com/en/1.1.0/\">Keep a Changelog</a>. Đánh số phiên bản: <a href=\"https://semver.org\">SemVer</a>.","changelog.69c6a54708de":"[Chưa phát hành]","changelog.6b02e0d363a4":"Đã thêm","changelog.1e07f27ea3ab":"<strong>[mọi nền tảng]</strong> <strong>Ống kính thuộc tính</strong> (SRC-N01 … SRC-N15) — ống kính thứ năm, đọc <em>header của container</em>. <code>width:&gt;1920</code>, <code>camera-model:R5</code>, <code>author:lovelace</code>, <code>binary-type:arm64</code>, <code>package-version:0.23</code>, <code>broken-link:</code>, <code>entry-count:&gt;1000</code>, <code>font-scripts:cyrillic</code>, <code>from:ada@example.com</code>, <code>table-names:notes</code> — bảy mươi hai thuộc tính thuộc mười một nhóm, thuộc tính nào cũng gõ được như một công cụ sửa đổi và cũng có sẵn làm cột kết quả. Crate mới <code>freally-properties</code>; không gian tên DSL mới <code>property:</code> cho dạng tổng quát (<code>property:duration&gt;60</code>, cách để chạm tới một khóa mà tên của nó đã bị một công cụ sửa đổi cũ hơn dùng mất).","changelog.a87ab2c792bf":"<strong>Lười và bị nhật ký vô hiệu hóa.</strong> Không có gì chạy lúc lập chỉ mục. Một thuộc tính được đọc vào lần đầu tiên một truy vấn hỏi đến tệp, sau đó được lưu đệm theo <code>mtime_ns</code> của tệp, nên nhật ký thay đổi làm ống kính này mất hiệu lực mà ống kính không cần đăng ký theo dõi nhật ký — cùng một hợp đồng mà ống kính âm thanh đã có từ giai đoạn 9. Các lần không tìm thấy cũng được lưu đệm: một thư mục toàn tệp <code>.txt</code> chỉ tốn một lần <code>open</code> cho mỗi tệp trong mỗi thế hệ chỉ mục, thay vì một lần cho mỗi phím gõ.","changelog.ca8eac0102ce":"<strong>Chỉ đọc header.</strong> Không trình phân tích nào giải mã một bức ảnh, tách luồng, kết xuất một trang hay đọc một hàng trong cơ sở dữ liệu của ai đó. Chính ranh giới đó giữ cho <code>width:&gt;1920</code> vẫn trả lời được với tốc độ gõ phím trên cả một thư mục đầy tệp RAW.","changelog.982e60011610":"<strong>Toàn phần.</strong> Không tệp nào có thể làm một truy vấn thuộc tính thất bại. Một header bị cắt cụt, một tệp <code>.png</code> thực ra là tệp văn bản, một đường dẫn không đọc được: tất cả đều có nghĩa là &quot;hàng này không có thuộc tính&quot;, và đó là một lý do hoàn toàn chính đáng để không khớp.","changelog.020bc33d94a7":"<strong>Định dạng.</strong> Kích thước và chi tiết bên trong của PNG / JPEG / GIF / WebP / BMP / TIFF / AVIF-HEIC (SRC-N02, N04); dữ liệu chụp EXIF với cờ has-GPS và <strong>không lưu tọa độ</strong> (N03); thông số kỹ thuật của MP4 / MOV / MKV / WebM / AVI (N05); từ điển thông tin PDF và <code>core.xml</code> / <code>app.xml</code> của OOXML (N08); kiến trúc PE / ELF / Mach-O, chuỗi VERSIONINFO của Windows và trạng thái Authenticode (N09); siêu dữ liệu gói MSI / deb / rpm / pkg (N10); đích của <code>.lnk</code> / <code>.desktop</code> / symlink kèm bộ tìm <code>broken-link:</code> (N11); số mục, tỷ lệ nén, mã hóa và phát hiện tệp chia nhiều phần của zip / 7z / tar (N12); họ phông, độ đậm, số glyph và các hệ chữ được hỗ trợ của TTF / OTF / WOFF, đọc từ <em>cmap</em> thay vì từ một dải được khai báo (N13); header RFC-822 và mbox (N14); lược đồ SQLite (N15).","changelog.2f4f9e89e8ed":"<strong>Hai trình trích xuất nội dung mới.</strong> Header và phần thân của <code>.eml</code> / <code>.mbox</code> được đưa vào ống kính nội dung, với tệp đính kèm được liệt kê thành các mục ảo theo cách viết <code>container!inner</code> của archive-peek — <em>byte</em> của tệp đính kèm không bao giờ được giải mã (N14). <code>.db</code> / <code>.sqlite</code> luôn đóng góp tên bảng và tên cột, còn những hàng đầu tiên của các cột văn bản thì <strong>chỉ</strong> sau một cài đặt mặc định tắt (N15): một cơ sở dữ liệu trong thư mục tải xuống là dữ liệu ứng dụng của ai đó.","changelog.58bf7de69c7c":"<strong>Cột thuộc tính</strong> (SRC-N06) — bất kỳ thuộc tính nào cũng có thể thành một cột kết quả từ menu <code>+</code> của hàng tiêu đề, sắp xếp được, với bố cục tự động theo từng bộ lọc nhanh (Hình ảnh hiện kích thước, Video hiện thời lượng và độ phân giải). ID cột giờ là <code>name</code> … <code>ext</code> cộng với <code>prop:&lt;key&gt;</code>, dựa trên dữ liệu từ sổ đăng ký thay vì một union cố định.","changelog.aa4087512231":"<strong>Thống kê kết quả</strong> (SRC-N07) — nhấp vào số lượng kết quả trên thanh trạng thái sẽ mở ra tổng số byte, số lượng và kích thước theo phần mở rộng và theo loại, hàng lớn nhất / cũ nhất / mới nhất, và một biểu đồ tần suất cho mỗi thuộc tính mà tập kết quả thực sự có. Được tính ở phía daemon trên toàn bộ tập kết quả, không phải trên trang đang hiển thị, và giới hạn ở 200 000 hàng kèm ghi chú &quot;đây là mức sàn&quot; khi chạm giới hạn.","changelog.47c227c9a823":"<strong>Cài đặt → Ống kính → Thuộc tính</strong> — bật hoặc tắt ống kính, công tắc theo từng nhóm, giới hạn thời gian trích xuất mỗi tệp, công tắc cho các hàng SQLite và công tắc cột tự động. Chế độ riêng tư tắt toàn bộ ống kính, vì nó đọc vào bên trong tệp, và chế độ riêng tư sinh ra chính là vì chuyện đó.","changelog.2662e0d9c21f":"<strong>Những điểm khác biệt, được nói rõ thay vì che đậy.</strong> Việc xác minh chữ ký trên macOS báo một chữ ký <em>nhúng</em> thay vì một chữ ký đã được xác thực: kiểm tra công chứng qua <code>Security.framework</code> là FFI không an toàn với một framework mà không máy nào trong dự án này thử nghiệm được, và một <code>valid</code> không kiểm chứng được còn tệ hơn một <code>embedded</code> trung thực. Phông chữ WOFF2 không cho ra gì cả — brotli cộng các phép biến đổi glyf/loca là cả một thư viện phông chữ thứ hai, chứ không còn là việc đọc header. Tệp nhị phân ELF hoàn toàn không có thuộc tính <code>signature</code>, vì Linux ký gói chứ không ký tệp nhị phân, và câu trả lời đó thuộc về SRC-N10. <em>Tên</em> thuộc tính được suy ra từ khóa của chúng (<code>aspect-ratio</code> → &quot;Aspect ratio&quot;) ở mọi ngôn ngữ thay vì được dịch; phần giao diện xung quanh vẫn được bản địa hóa bình thường.","changelog.bc802b748761":"<strong>[mọi nền tảng]</strong> <strong>Những gì bạn gõ được hiển thị in đậm trong kết quả</strong>, ngay khi bạn gõ, ở cả cột Tên lẫn cột Đường dẫn. Chỉ các từ tìm kiếm của bạn được đánh dấu: một công cụ sửa đổi như <code>ext:json</code> thu hẹp danh sách chứ không phải là thứ bạn đang tìm, nên <code>json</code> không bị in đậm trong mọi tên tệp. Đánh dấu bằng độ đậm của chữ thay vì một khối tô sáng, nên vẫn dễ đọc trên hàng đang chọn và ở cả hai giao diện.","changelog.0a3eaf604faf":"<strong>[mọi nền tảng]</strong> <strong>Báo lỗi</strong> — <code>Help → Report a Bug…</code>, cùng một lời nhắc xuất hiện ở lần khởi chạy tiếp theo sau một sự cố. Một panic hook ghi một báo cáo sự cố <strong>đã được làm sạch</strong> ngay trên máy (đường dẫn thư mục nhà và tên người dùng bị che đi trước khi tệp chạm vào ổ đĩa), và hộp thoại cho bạn xem <strong>chính xác</strong> đoạn văn bản sẽ được gửi — chỉ gồm phiên bản ứng dụng và hệ điều hành — trước khi đề nghị mở một issue GitHub hoặc một bản nháp thư đã điền sẵn. <strong>Không có gì tự động được gửi đi</strong>; không có đo từ xa và không có máy chủ nào do chúng tôi vận hành. Hai bài diễn tập nằm trong Cài đặt → Nhật ký &amp; Gỡ lỗi.","changelog.09c294b4b464":"<strong>[mọi nền tảng]</strong> <strong>Kiểm tra cập nhật</strong> — Cài đặt → Quyền riêng tư &amp; Cập nhật giờ hỏi trình cập nhật thay vì mở một trang web. Nó cho biết phiên bản bạn đang chạy, hiển thị ghi chú phát hành với các liên kết hoạt động được, và khi có bản cập nhật thì hỏi bằng <strong>một hộp Có/Không nêu tên cả hai phiên bản</strong> trước khi cài đặt bất cứ thứ gì. Nếu chọn có, nó dừng daemon lập chỉ mục, cài đặt rồi đóng lại; trên Windows, trang cuối của trình cài đặt đề nghị khởi chạy phiên bản mới. Lần kiểm tra khi khởi động tuân theo cài đặt tần suất, tạm lui khi có một báo cáo sự cố đang chờ, và giữ <strong>im lặng</strong> khi máy đang ngoại tuyến.","changelog.59f3ea0ca50a":"<strong>[Windows]</strong> <code>freally-indexd status</code> cho biết daemon có được đăng ký thành dịch vụ hay không và trình quản lý dịch vụ nhìn nhận nó thế nào. Trước đây đã có cài đặt và gỡ cài đặt, nhưng không có cách nào để hỏi chuyện gì đã xảy ra.","changelog.5b14114e2f2b":"<strong>[tài liệu]</strong> <code>docs/EVERYTHING_MIGRATION_GUIDE.md</code> — những gì chuyển sang được từ Everything của voidtools, những gì mới, và ba điều sẽ làm bạn bất ngờ. <code>docs/MENU_REFERENCE.md</code> — cả 112 mục menu cùng phím tắt của chúng, được sinh ra từ đặc tả menu nên không thể lỗi thời.","changelog.2643567f0f72":"<strong>[đóng gói]</strong> <code>packaging/</code> chứa các manifest cho winget, Chocolatey, Homebrew Cask, Flathub và Snap, được <code>scripts/gen-packaging.mjs</code> sinh ra từ một bản phát hành đã công bố, nên các checksum chính là những checksum mà GitHub phục vụ.","changelog.013883122f3c":"<strong>[phát hành]</strong> <code>scripts/verify-updater-chain.mjs</code> chứng minh rằng một bản phát hành đã công bố thực sự cập nhật được: nó so sánh ID khóa bên trong chữ ký của từng nền tảng với khóa công khai được biên dịch vào các tệp nhị phân. Trình cập nhật thất bại theo kiểu đóng <strong>và im lặng</strong>, nên không có gì khác bắt được một bản phát hành bị ký bằng nhầm khóa.","changelog.0c8009384b06":"<strong>[mọi nền tảng]</strong> Giờ có thể hoàn tác việc xóa tệp. <code>files_delete</code> chuyển các hàng vào thùng rác của hệ điều hành, nơi có thể khôi phục, nhưng trước đây không ghi lại gì — nên Hoàn tác của chính ứng dụng chưa bao giờ đề nghị lấy lại một lần xóa trên bất kỳ nền tảng nào. Giờ việc xóa được ghi vào nhật ký, và Ctrl+Z khôi phục từ Recycle Bin (Windows) hoặc thùng rác freedesktop (Linux).","changelog.e370b0fcd2c3":"<strong>[chỉ macOS]</strong> Một lần xóa được ghi lại là <strong>không thể hoàn tác, kèm lý do được hiển thị</strong>, vì Finder sở hữu Đưa trở lại và không cung cấp API nào cho nó. Hoàn tác giờ nói rõ điều đó thay vì im lặng: <code>next_undo</code> từ chối đúng cách việc nhảy qua một mục không thể hoàn tác, điều đó trước đây khiến Ctrl+Z hoàn toàn không làm gì sau một lần xóa và không bao giờ giải thích vì sao.","changelog.63589b7d0b3f":"<strong>[mọi nền tảng]</strong> Lệnh tùy chỉnh hỏi một lần, qua một hộp thoại gốc của hệ điều hành, trước khi chạy một chương trình lần đầu tiên. Việc chấp thuận gắn với chương trình, nên đổi tên một lệnh sẽ không bị hỏi lại, và lời hỏi nêu cả đối số lẫn chương trình. Các chấp thuận được lưu bên ngoài <code>settings.json</code> — lưu chúng trong đó sẽ đặt danh sách cho phép sau cùng một đường dẫn mà webview ghi được, chính thứ mà lời hỏi sinh ra để bảo vệ. Xem <code>docs/SECURITY.md</code>.","changelog.549a5f40d4d8":"<strong>[mọi nền tảng]</strong> Tay nắm đổi kích thước cột giờ thao tác được bằng bàn phím: phím mũi tên nhích từng chút, Home/End nhảy tới giới hạn. Trước đây chúng nhận được tiêu điểm nhưng không làm gì cả, còn tệ hơn là không nhận được tiêu điểm.","changelog.2a6141e43be0":"Đã thay đổi","changelog.484caa95cf9c":"<strong>[mọi nền tảng]</strong> <strong>Tìm theo tên tệp nhanh hơn hẳn với các truy vấn có lọc.</strong> Đo trên một triệu tệp, <code>ext:json</code> giảm từ 229 ms → 11 ms (20.7×), <code>regex:^report-</code> 76 ms → 9.5 ms (7.9×), <code>*.rs</code> 60 ms → 19 ms (3.1×), và <code>report path:horizon</code> 31 ms → 12 ms (2.6×). Các lần tìm một từ đơn giản vốn đã nhanh và không thay đổi. Bốn điều đã làm nên chuyện này: các dạng truy vấn đó giờ tạo ra một hạt giống trigram thay vì duyệt qua mọi tên đã lập chỉ mục; chỉ mục tên mang theo phần mở rộng, kích thước, ngày và các bit thuộc tính của từng hàng, nên các bộ lọc đó được trả lời từ bộ nhớ thay vì phải lấy từng hàng khớp ra khỏi SQLite; đường dẫn của một thư mục được lưu một lần thay vì một lần cho mỗi tệp bên trong, giúp <code>path:</code> loại bỏ hàng trước khi chúng được lấy ra; và gõ một từ dài hơn giờ thu hẹp kết quả của lần gõ phím trước thay vì bắt đầu lại từ đầu. Trên Linux với 200 000 tệp, mọi kịch bản benchmark giờ đều dưới 8 ms. Xem mục <strong>Search performance</strong> (hiệu năng tìm kiếm) trong README để có các bảng đầy đủ, chiếc máy đã dùng để đo, và lý do máy của bạn sẽ cho kết quả khác.","changelog.89b30b76bb7e":"<strong>[mọi nền tảng]</strong> <strong>Bộ lọc nhanh bao quát nhiều hơn hẳn trên ổ đĩa của bạn.</strong> Âm thanh tăng từ 22 phần mở rộng lên 65, Video 23 → 79, Hình ảnh 24 → 77, Tài liệu 25 → 86, Tệp nén 23 → 70. Mọi phần mở rộng mà chính các bộ lọc của Everything có giờ đều có mặt — được kiểm tra bằng một bài kiểm thử nêu tên từng cái một — nên không có gì bạn tìm được dưới một bộ lọc trong Everything lại bị thiếu ở đây. Phần bổ sung là những định dạng ra đời sau các mặc định của Everything: Opus, AVIF, JXL, HEIC, RAW máy ảnh của mọi hãng lớn, zstd, OpenDocument, sách điện tử và các định dạng Apple iWork. Bạn cũng có thể gõ chúng, với những bí danh dễ đoán — <code>music:</code>, <code>movies:</code>, <code>photos:</code>, <code>docs:</code>, <code>compressed:</code>, <code>zip:</code>. Mã nguồn vẫn nằm ngoài <strong>Tài liệu</strong> (Everything gộp <code>c</code>/<code>cpp</code>/<code>h</code>/<code>java</code> vào); <code>ext:c;cpp;h</code> cho bạn lại tập cũ.","changelog.170d6493da10":"<strong>[mọi nền tảng]</strong> <strong>Một bộ lọc trên phần lớn ổ đĩa của bạn không còn chậm nữa.</strong> Chọn Âm thanh hoặc Đã nén trước đây phải duyệt từng hàng đã lập chỉ mục một, vì hợp của sáu mươi phần mở rộng không dùng được chỉ mục trigram — thu hẹp theo một trong số đó sẽ đánh rơi kết quả khớp của năm mươi chín cái còn lại. Giờ Freally đọc thẳng cột phần mở rộng của nó trong bộ nhớ, bốn byte mỗi hàng. Đo trên 2.7 triệu tệp, một bộ lọc khớp với một phần năm số tệp đó đã chuyển từ dạng truy vấn chậm nhất thành nhanh nhất.","changelog.30a936879584":"<strong>[mọi nền tảng]</strong> <strong>Số lượng kết quả giờ là số lần khớp, không phải số hàng trên màn hình.</strong> Một bộ lọc khớp với nửa triệu tệp sẽ nói đúng như vậy, giống &quot;531,129 objects&quot; của Everything, trong khi vẫn chỉ lấy trang mà bạn nhìn thấy. Khi một truy vấn đủ rộng để chạm trần ứng viên, con số được báo là mức sàn thay vì một con số trông có vẻ chính xác mà thực ra không phải.","changelog.6af3be76b723":"<strong>[mọi nền tảng]</strong> Bộ lọc nhanh giờ khớp theo phần mở rộng thật của tệp thay vì theo bất cứ thứ gì đứng sau dấu chấm cuối cùng trong tên. Một dotfile như <code>.jsonrc</code> không có phần mở rộng, nên nó không còn xuất hiện dưới bộ lọc nhanh JSON nữa — đó vốn là điều <code>ext:json</code> luôn làm, và giờ hai bên đã thống nhất.","changelog.d37659a5fceb":"<strong>[mọi nền tảng]</strong> <strong>Lập chỉ mục một ổ đĩa lớn nhanh hơn khoảng 20×.</strong> Mỗi lần commit trong lúc quét lại dựng lại một chỉ mục đã sắp xếp trên mọi tên tệp đã thấy cho đến lúc đó — ở 200 000 tệp, việc đó chiếm 1.34 giây của một lần commit 1.4 giây, và càng quét xa càng tệ hơn. Không có gì đọc kết quả của nó. Lần quét đầu tiên trên một ổ đĩa có hàng triệu tệp đã giảm từ hàng giờ xuống hàng phút.","changelog.e2099089ef3b":"<strong>[mọi nền tảng]</strong> Menu con giờ là <strong>nhấp để ghim</strong>. Một cú nhấp giữ menu con mở bất kể con trỏ sau đó đi đâu, đúng thứ mà bàn di chuột cần và một bài kiểm thử tự động đòi hỏi; di chuột qua vẫn mở được chúng.","changelog.fb8d168729ab":"<strong>[mọi nền tảng]</strong> <code>freally index pause</code> và <code>resume</code> giờ thực sự tạm dừng và tiếp tục, bằng cách đặt <code>monitor_changes</code> trên mọi ổ đĩa được phát hiện. Trước đây mỗi lệnh gửi một khóa cài đặt chẳng liên quan rồi báo thành công.","changelog.1246fc93bca0":"Đã sửa","changelog.40cc68328345":"<strong>[mọi nền tảng]</strong> Bảng Tình trạng chỉ mục làm luồng chính chạy hết công suất và dội các lệnh gọi <code>index_health</code> vào daemon nhanh nhất mức nó trả lời được, thay vì thăm dò mỗi 2 s. <code>$effect</code> của nó khởi chạy bộ thăm dò ngay tại chỗ, và bộ thăm dò đọc và ghi đúng trạng thái mà effect sau đó đăng ký theo dõi, nên mỗi câu trả lời lại khởi động lại nó. Bảng này không dùng được và ứng dụng ngừng phản hồi khi nó đang mở. Lỗi này đã có mặt từ M13; bản đặc tả e2e lẽ ra bắt được nó lại đang ở trạng thái <code>test.fixme</code> vì một lý do không liên quan.","changelog.3e288bea5aec":"<strong>[mọi nền tảng]</strong> <code>path:</code> và <code>parent:</code> cấp phát một chuỗi viết thường cho mỗi hàng đã nạp dữ liệu, trong khi <code>path:</code> đã có sẵn một bản sao trong bộ đệm.","changelog.760a29ec7c23":"<strong>[mọi nền tảng]</strong> Các hộp thoại có hai bán kính góc và ba kiểu đổ bóng, vì prop <code>style</code> nội tuyến của <code>Modal</code> lặng lẽ thắng class riêng của shell. Prop đó giờ chỉ dành cho kích thước, và việc lách qua nó sẽ bị báo trong chế độ dev.","changelog.adfeb89fa1aa":"<strong>[mọi nền tảng]</strong> Hai trong sáu lựa chọn của <strong>Xem → Định dạng hiển thị → Định dạng kích thước</strong> không làm gì cả. Lược đồ cài đặt đưa ra <code>b | kb | mb | gb | auto_binary | auto_decimal</code>; <code>formatBytes</code> lại chấp nhận một bộ từ vựng năm giá trị khác, và mọi chỗ gọi đều ép kiểu để lách qua chỗ lệch đó, nên <code>b</code> và <code>auto_decimal</code> rơi xuống nhánh tự động nhị phân. Giờ chỉ còn một bộ từ vựng, <code>auto_decimal</code> đếm theo hàng nghìn, và mỗi lựa chọn đều được một bài kiểm thử ghim lại.","changelog.8fe7422dc893":"<strong>[mọi nền tảng]</strong> Thêm một cột thuộc tính lẽ ra đã lặng lẽ thất bại trên một bản cài đặt thật. <code>ColumnId</code> bên TypeScript có thêm dạng <code>prop:&lt;key&gt;</code>; còn bên Rust vẫn là một enum đóng sáu biến thể, nên <code>settings_set</code> từ chối toàn bộ bản vá — không chỉ cột đó — với <code>unknown variant</code>, và giao diện ghi nhật ký rồi cứ thế chạy tiếp. Phía Rust giờ xác thực <code>prop:&lt;key&gt;</code> theo sổ đăng ký thuộc tính, nhờ đó lược đồ vẫn đóng. Bài kiểm thử Playwright thêm một cột chạy trên bản giả lập IPC nên không thể bắt được lỗi này; giờ ba bài kiểm thử khứ hồi trong <code>settings.rs</code> bắt được.","changelog.c4182c80506c":"<strong>[mọi nền tảng]</strong> Không thuộc tính văn bản hay boolean nào chạm tới được qua không gian tên <code>property:</code>. Dấu phân cách <code>=</code> của ngữ pháp bị chuyển thẳng vào giá trị, nên <code>property:camera-make=canon</code> tìm chuỗi nguyên văn <code>=canon</code> và không trả về gì, còn <code>property:has-alpha=yes</code> thì báo lỗi. Chỉ các loại số và ngày là từng bỏ nó đi.","changelog.9d558fa75e7e":"<strong>[mọi nền tảng]</strong> Việc khớp thuộc tính văn bản phân biệt chữ hoa/thường theo một chiều với mọi giá trị không phải ASCII: từ cần tìm được chuyển chữ bằng <code>to_ascii_lowercase</code> lúc phân tích cú pháp, còn giá trị của hàng thì bằng <code>to_lowercase</code> Unicode đầy đủ lúc khớp, nên <code>camera-model:MÜLLER</code> không bao giờ tìm thấy <code>Müller</code>.","changelog.a37ae4d3cefc":"<strong>[mọi nền tảng]</strong> Sắp xếp theo một cột thuộc tính đặt các hàng <em>không có</em> thuộc tính đó lên đầu khi sắp giảm dần, chứ không xuống cuối như tài liệu mô tả — hàm so sánh trả về một giá trị <code>1</code> cố định rồi bị hệ số hướng đảo dấu. Một trang toàn ô trống xuất hiện ở chỗ lẽ ra là các giá trị lớn nhất.","changelog.1847045d095f":"<strong>[mọi nền tảng]</strong> Nhấp vào một chip bộ lọc loại tệp lại xin daemon bộ cột cũ: bố cục tự động được áp dụng sau khi thay đổi lựa chọn đã kích hoạt lần tìm kiếm, nên các cột thuộc tính mới hiển thị trống cho đến khi một phím gõ không liên quan tìm lại.","changelog.39af32b4d343":"<strong>[mọi nền tảng]</strong> Cài đặt của ống kính thuộc tính không sống sót qua một lần khởi động lại daemon. Phía daemon không lưu lại gì, và chỉ có thao tác <em>lưu</em> cài đặt mới từng đẩy chúng sang, nên một ống kính mà người dùng đã tắt — hoặc chế độ riêng tư đã tắt — lại bật trở lại ở lần khởi động daemon tiếp theo, trong khi giao diện vẫn hiển thị là tắt. Giờ các cài đặt đã nạp được phát lại cho daemon khi khởi động.","changelog.426b2fbb21fa":"<strong>[mọi nền tảng]</strong> Menu thêm cột mở ra ngoài màn hình. Nút <code>+</code> mở nó được ghim ở mép phải cửa sổ, nên một <code>left: clientX</code> không bị giới hạn đẩy gần như toàn bộ menu ra ngoài mép, chỉ chừa lại một mẩu nhỏ, mà không có gì để cuộn.","changelog.1be320f46969":"<strong>[mọi nền tảng]</strong> Một header ảnh bị hỏng có thể làm tràn <code>i64</code> khi tính số megapixel — <code>0xFFFFFFFF</code> bình phương vượt quá <code>i64::MAX</code> — khiến bản dựng debug bị panic và bản dựng phát hành nhận một con số âm.","changelog.ffa5958e11a4":"<strong>[mọi nền tảng]</strong> Một <code>property_budget_ms</code> bằng <code>0</code> gửi qua kênh truyền đã lặng lẽ biến toàn bộ ống kính thành vô dụng: mọi lần trích xuất bắt đầu khi đã quá hạn và mọi tệp trả về không có thuộc tính lẫn lỗi. Ô số trong cài đặt có áp mức tối thiểu; kênh truyền thì không. Giờ giá trị được nâng lên mức sàn ngay khi nhận.","changelog.065a03b57ec4":"<strong>[mọi nền tảng]</strong> Khi có bất kỳ nhóm thuộc tính nào bị tắt, mỗi lần trúng bộ đệm lại sao chép sâu toàn bộ bản đồ thuộc tính — đúng thứ cấp phát theo từng hàng mà <code>Arc</code> dùng chung sinh ra để tránh, phải trả trên mọi hàng của mọi truy vấn chừng nào cài đặt đó còn hiệu lực. Giờ khung xem đã lọc được ghi nhớ theo từng mục và bị bỏ đi khi tập hợp thay đổi.","changelog.1f99920ac00d":"<strong>[mọi nền tảng]</strong> Việc viết lại <code>length:</code> duyệt và sao chép sâu toàn bộ AST của truy vấn ở mỗi phím gõ của mọi lần tìm kiếm, kể cả những lần tìm không có <code>length:</code>, vì daemon luôn gắn một nhà cung cấp thuộc tính.","changelog.8f6fb4eb7f42":"Bảo mật","changelog.1a1f843d10c5":"<strong>[Windows]</strong> Đích của một lối tắt là các byte lấy từ một tệp không đáng tin, và trả lời <code>broken-link:</code> đồng nghĩa với việc gọi <code>Path::exists</code> lên nó. Trên Windows, điều đó trao một đường dẫn UNC cho SMB redirector, thứ sẽ kết nối tới máy chủ được nêu tên và đưa ra thông tin đăng nhập NTLM của người dùng đang đăng nhập — kiểu tấn công ép xác thực kinh điển qua shell link, và chỉ riêng việc lập chỉ mục đã đủ kích hoạt nó, mỗi tệp một lần bắt tay, không cần nhấp vào thứ gì. Chỉ cần thả một thư mục chứa các tệp <code>.lnk</code> trỏ tới <code>\\attacker\\share\\x</code> vào bất kỳ thư mục nào đang được theo dõi là đủ. Giờ các đích được kiểm tra dạng UNC và URL trước khi được phân giải, và một đích từ xa sẽ để <code>broken-link</code> trống thay vì bị dò thử. Lớp bảo vệ tương tự áp dụng cho đích của symlink, vốn đến theo cùng cách đó bên trong bất kỳ tệp lưu trữ nào.","changelog.c599b83df9e1":"<strong>[Windows]</strong> Việc xác minh Authenticode chạy với <code>dwProvFlags: 0</code>. <code>WTD_REVOKE_NONE</code> chặn CRL và OCSP nhưng không chặn việc chain engine tải AIA, nên một tệp nhị phân tự ký có chứng chỉ trỏ tới <code>http://attacker/&lt;unique&gt;.cer</code> lẽ ra đã biến việc lập chỉ mục thành một biên nhận đã đọc — đã tới, IP này, thời điểm này — từ một daemon mà bảng Quyền riêng tư hứa rằng không có yêu cầu nào đi ra ngoài. Giờ được ghim ở <code>WTD_CACHE_ONLY_URL_RETRIEVAL | WTD_REVOCATION_CHECK_NONE</code>.","changelog.4118fb4fed0e":"Đã xóa","changelog.7e47a128e1ba":"<strong>[mọi nền tảng]</strong> Cài đặt <strong>Tự động xóa ổ đĩa ngoại tuyến</strong>. Nó không điều khiển gì cả — chưa có đoạn mã nào từng đọc nó — và điều nó mô tả lại ngược với hành vi đã phát hành: một ổ đĩa đã rút ra được cố ý <em>giữ lại</em> thành danh mục ngoại tuyến để các hàng của nó vẫn tìm kiếm được và được gắn nhãn. Hiện thực hóa nó đúng như mô tả, với mặc định là bật, lẽ ra đã xóa chỉ mục của mọi ổ đĩa đã rút ra.","changelog.748e7fd40ac8":"[0.23.2] — Xoay vòng khóa trình cập nhật và sửa CI (2026-08-19)","changelog.31b4f34d5ada":"Cùng ứng dụng với <code>0.23.1</code>, bản đã được gắn thẻ nhưng bản phát hành của nó bị thay thế thay vì được công bố. Mọi thứ trong mục <code>0.23.1</code> bên dưới đều có trong bản này; những gì sau đây là phần thay đổi thêm.","changelog.965ce76814aa":"<strong>Khóa ký mới cho trình cập nhật.</strong> Các bản phát hành cho đến <code>0.23.1</code> được ký bằng <code>9F291C936CFA28B7</code>, khóa mà nửa riêng tư chỉ tồn tại dưới dạng một bí mật của kho GitHub. Bí mật của kho không thể đọc ngược ra được, nên khóa đó không thể sao chép, di chuyển hay khôi phục — và giờ nó đã mất. Các bản phát hành từ <code>0.23.2</code> trở đi được ký bằng <code>E5035E2194EB7E04</code>, khóa mà nửa riêng tư, mật khẩu và nửa công khai được lưu cùng nhau bên ngoài GitHub.","changelog.926a99810869":"<strong>Điều này làm hỏng trình cập nhật cho mọi bản cài đặt <code>0.23.1</code> hoặc cũ hơn</strong>: các tệp nhị phân cũ xác minh theo một khóa công khai không còn ký thứ gì, nên một bản cập nhật sẽ thất bại ở bước xác minh chữ ký thay vì được cài đặt. Hãy cài đặt lại từ các bản tải xuống bên dưới. Chưa biết có bản cài đặt nào bị ảnh hưởng — số lượt tải của mọi bản phát hành trước đều khớp với việc kiểm tra liên kết định kỳ.","changelog.95ee6438be83":"<strong><code>apt-get update</code> có thể làm một bản dựng Linux treo vô thời hạn.</strong> Máy chủ gương Ubuntu mà các image runner ưu tiên, <code>azure.archive.ubuntu.com</code>, không trả về gì cho toàn bộ tập chỉ mục jammy trong vài giờ, và vì không cấu hình thời gian chờ nên bước đó cứ chờ thay vì thất bại — tới một giờ so với mức chuẩn 72 giây, bốn lần, lần nào cũng phải hủy thủ công. Giờ các bản dựng dùng <code>archive.ubuntu.com</code>, giới hạn bước đó ở mười phút và thử lại. Sau đó chính bước ấy chạy trong 41 giây.","changelog.7f5127beca31":"<strong><code>workflow_dispatch</code> trên quy trình phát hành dựng nhầm cây mã.</strong> Nó nhận một thẻ làm đầu vào và là cách được ghi trong tài liệu để dựng lại một bản phát hành, nhưng bước checkout của nó không có <code>ref</code>, nên nó checkout bất kỳ nhánh nào mà nó được kích hoạt từ đó, trong khi vẫn đặt tên các artifact theo thẻ đầu vào.","changelog.e492554f1e26":"<strong>Các bài kiểm thử giới hạn thời gian thực chạy dưới tải song song toàn phần trong CI.</strong> <code>scripts/ci-local.mjs</code> đã được đổi để chạy chúng riêng — vì mô hình mỗi bài kiểm thử một tiến trình của nextest đặt máy dưới tải liên tục và khi đó phép khẳng định lại đo chính cái tải ấy — nhưng CI vẫn chạy chúng cùng mọi thứ khác, nên cổng cục bộ đã không còn dự đoán được CI cho đúng những bài kiểm thử khó tái hiện nhất. Giờ CI tách bước nextest của mình theo cùng cách, và mức trần được nới rộng trên các runner dùng chung, nơi phép đo ít ý nghĩa hơn.","changelog.17a56bd3bbd4":"<strong>Hai lỗi clippy riêng cho từng hệ điều hành</strong> trong <code>shell_actions/macos.rs</code> và <code>shell_actions/linux.rs</code>, những tệp mà không bản dựng Windows nào biên dịch và cổng lint của <code>src-tauri</code> lần đầu chạm tới trong đợt này.","changelog.c205924de0fe":"Tài liệu","changelog.9c50b38011d4":"<code>README.md</code> quảng cáo <code>v0.19.84</code> là bản phát hành đầu tiên sắp ra, dù đã bốn bản phát hành trôi qua, và liên kết tới năm tài liệu không thuộc kho này.","changelog.4395f6d7c73f":"Kích thước tải xuống trên trang web vẫn là của <code>0.23.0</code>, bị mang theo cùng các liên kết.","changelog.2d312a56ada7":"[0.23.1] — Nền móng cho Build 4 · khép lại phần bàn giao của Build 3 (2026-08-19)","changelog.957188896a81":"Nền móng cho Build 4 — khép lại phần bàn giao của Build 3","changelog.4dce861a35f4":"Mọi thứ mà lần bàn giao trước còn bỏ ngỏ sau v0.23.0, cộng với ba lỗi được phát hiện trong lúc làm. Không có tính năng mới; đây là đợt dọn dẹp làm nền cho công việc ống kính thuộc tính của Build 4.","changelog.116b07733767":"<strong>Menu <code>Search →</code> không làm gì cả.</strong> SRC-M23 gửi cả bảy cờ chế độ khớp từ <code>query.ts</code> và dạy <code>QueryRunParams</code> của daemon đọc cả bảy — nhưng lệnh Tauri nằm giữa lại không khai báo cờ nào, và Tauri lặng lẽ bỏ những đối số invoke mà một lệnh không nêu tên. Mọi cờ đến executor với giá trị mặc định <code>serde</code> của nó, nên Phân biệt chữ hoa/thường, Khớp toàn bộ từ, Khớp đường dẫn, Khớp dấu thanh, Khớp phiên âm CJK, Bỏ qua dấu câu và Bỏ qua khoảng trắng chỉ di chuyển một dấu kiểm và không thay đổi gì khác. Giờ <code>commands/query.rs</code> có một điểm tiếp nhận <code>QuerySearchOpts</code>, và <code>tests/unit/query_wire.test.ts</code> ghim tên đối số ở cả hai phía.","changelog.3258356b0cdb":"<strong>Phân biệt chữ hoa/thường sai theo cả hai chiều.</strong> Khi bật, một truy vấn viết hoa <em>không</em> trả về gì, còn một truy vấn viết thường vẫn khớp bất kể chữ hoa hay thường. Chỉ mục tên lưu khóa ở dạng viết thường, nên bộ lọc sơ bộ ứng viên không có văn bản giữ nguyên chữ hoa/thường để kiểm tra và loại mọi hàng trước khi bước nạp dữ liệu kịp nhìn thấy tên thật. Điều này đã được biết và bị hoãn lại — một bài kiểm thử khẳng định đúng hành vi hỏng đó và chỉ tới một thay đổi chỉ mục ở giai đoạn 13. Thật ra không cần đến thay đổi đó: giờ Phân biệt chữ hoa/thường bỏ qua bộ lọc sơ bộ, đúng như Khớp đường dẫn vốn đã làm, và vị từ chạy trên tên thật của hàng. Hạt giống trigram vẫn được dùng, vì nó được dựng từ từ cần tìm ở dạng viết thường nên chọn ra một tập lớn hơn chứa câu trả lời có phân biệt hoa/thường, nghĩa là cái giá chỉ là một lần nạp dữ liệu chứ không phải một lần quét toàn bộ. <code>child:</code>, <code>name^:</code> và <code>name$:</code> cũng được chuyển hướng theo cùng cách.","changelog.3fdb374f585c":"<strong>Không cài đặt nào được lưu lại.</strong> <code>custom_commands</code> có giá trị mặc định và cả một bảng Cài đặt → Lệnh tùy chỉnh, nhưng lại vắng mặt trong <code>ALLOWED_PATCH_KEYS</code>. <code>settings_set</code> từ chối một bản vá ở khóa cấp cao nhất đầu tiên mà nó không biết, và <code>flush()</code> của giao diện gửi toàn bộ trạng thái — vốn luôn chứa <code>custom_commands</code> — nên mọi lần lưu đều kết thúc bằng một cảnh báo trong console. Giờ danh sách cho phép được suy ra từ lược đồ (<code>allowed_patch_keys()</code>), và chính nhờ đó mà lỗ hổng lộ ra.","changelog.be64658b8045":"<strong><code>child:</code> / <code>name^:</code> / <code>name$:</code> trả lời khác nhau tùy vào phần còn lại của truy vấn.</strong> Lượt chỉ mục tên đưa chúng qua toàn bộ thang chuẩn hóa, trong khi lượt đã nạp dữ liệu so sánh chuỗi thô, và cả hai lượt đều chạy với mọi truy vấn — nên thêm bất kỳ công cụ sửa đổi nào buộc phải nạp dữ liệu sẽ giao quyền quyết định cho lượt khắt khe hơn. <code>name^:cafe</code> tìm thấy <code>café-notes.txt</code> khi đứng một mình và không còn tìm thấy nó nữa khi thêm <code>size:</code>.","changelog.35d326e420f1":"<strong>Esc không bao giờ đóng được hộp thoại.</strong> Trình xử lý nằm trên lớp nền, một div <code>role=&quot;presentation&quot;</code> không có tabindex, nên nó không thể nhận keydown — mà dù sao bảng cũng đã chặn việc lan truyền. Giờ nó nằm trên <code>window</code>, trong <code>&lt;Modal&gt;</code> dùng chung.","changelog.4f4a3883a9bb":"<strong>Sắp xếp tự nhiên chỉ có ở phía máy khách.</strong> <code>SortSpec.natural</code> mặc định là <code>true</code> và không có gì từng đặt nó, nên Cài đặt → Kết quả → <em>Sắp xếp tự nhiên</em> tắt hàm so sánh của giao diện nhưng vẫn để <code>freally search --json</code> sắp xếp tự nhiên như thường. Giờ cài đặt này được truyền qua kênh truyền.","changelog.1eb006c07967":"<strong><code>src-tauri</code> không được lint.</strong> Nó bị loại khỏi workspace, nên <code>cargo clippy --workspace</code> chưa bao giờ nhìn thấy nó và ba lỗi đã lặng lẽ thất bại. Giờ CI có một bước riêng cho manifest đó. Lệnh chết <code>log_event</code> — được ghi trong tài liệu là cầu nối gỡ lỗi từ TS sang Rust nhưng chưa từng được đăng ký, nên mọi lệnh gọi tới nó đều thất bại — đã bị xóa.","changelog.17d4993eb122":"<strong>Lệnh tùy chỉnh giờ bị giới hạn và được kiểm tra hình dạng.</strong> <code>custom_commands</code> là cài đặt duy nhất có giá trị nêu tên một <em>chương trình sẽ được chạy</em>, và nó đến được <code>settings_set</code> mà không qua bất kỳ bước xác thực nào — vì cho đến bản dựng này nó thậm chí chưa từng đến được <code>settings_set</code> (xem ở trên). Giờ nó có cùng kiểu giới hạn như mọi trường không giới hạn khác — về số lượng lệnh, về độ dài của <code>id</code>/<code>name</code>/<code>program</code>, và về cả hai danh sách chuỗi của nó, <code>args</code> và <code>extensions</code>.","changelog.efc94af8b3c4":"<strong>Nhập một tệp cài đặt không còn lặng lẽ cài đặt trình khởi chạy nữa.</strong> Cài đặt → Sao lưu → <em>Nhập cài đặt</em> đọc một tệp JSON do người dùng cung cấp thẳng vào kho cài đặt. Vì thế một &quot;thiết lập sẵn Freally&quot; được chia sẻ có thể thêm một lệnh tùy chỉnh — một chương trình sẽ được chạy — vào menu ngữ cảnh của mọi kết quả, dưới một nhãn do tác giả của nó chọn, mà không nói gì cả. Giờ việc nhập nêu tên các chương trình và hỏi trước; từ chối thì mọi thứ khác vẫn được nhập. <code>docs/SECURITY.md</code> nói thẳng ranh giới còn lại: bất cứ thứ gì ghi được cài đặt đều có thể nêu tên một chương trình.","changelog.442aded87a55":"Hiệu năng","changelog.ee0c64c3999a":"<strong>Bỏ qua dấu câu / Bỏ qua khoảng trắng không còn quét toàn bộ chỉ mục.</strong> Các chế độ đó viết lại văn bản trước khi so sánh, nên trigram của tên thô không còn mô tả được từ cần tìm và executor phải lùi về việc duyệt mọi tên. Giờ nó lấy hạt giống từ một tập posting song song được dựng trên các tên đã bỏ dấu câu và khoảng trắng. Được dựng lười ở lần dùng đầu tiên và được duy trì dần từ đó, nên người dùng chưa bao giờ bật chế độ nào trong hai chế độ đó sẽ không bao giờ phải trả giá cho nó.","changelog.2bfd60f4ad05":"<strong>Một thang chuẩn hóa thay vì ba.</strong> <code>substring_match</code>, <code>anchored_match</code> và <code>literal_match</code> mỗi cái tự đi qua case-fold → strip-diacritics → strip-ignored và đã bắt đầu lệch nhau. Giờ chúng dùng chung <code>normalized</code>, hàm mượn thay vì cấp phát khi một nấc không có gì để làm — trường hợp phổ biến là một tên ASCII viết thường ở chế độ mặc định giờ không cấp phát gì cho mỗi hàng.","changelog.40253ba25a46":"<strong>Từ cần tìm được chuẩn hóa một lần cho mỗi truy vấn, không phải một lần cho mỗi hàng ứng viên.</strong>","changelog.23f1c76bd888":"Việc chia dạng sóng thành các ô giữ sẵn ranh giới ô thay vì chia theo từng khung đã giải mã (~8 M phép chia cho một bản nhạc stereo dài ba phút); sổ ghi quyền khử trùng lặp qua một <code>HashSet</code> thay vì quét tuyến tính; và việc ghi lại một lần tìm kiếm gần đây không còn trải ra và gán lại gốc cài đặt ~180 khóa ở mỗi phím gõ.","changelog.64ff3a4bbdfd":"<strong>Freally Central đã bị xóa</strong> — cây mã đi kèm, đoạn khai báo trong <code>.gitmodules</code> nêu tên một submodule mà git chưa bao giờ đăng ký, đảo React cùng năm phụ thuộc của nó, hộp thoại và mục menu <em>Thêm ứng dụng Freally</em>, các chuỗi ngôn ngữ của nó, và các mục của nó trên trang tài liệu.","changelog.36e12a600874":"<strong>Một <code>&lt;Modal&gt;</code> dùng chung</strong> thay thế màn xoay xở giữa lớp nền / bảng / Esc / <code>tabindex</code> mà bảy hộp thoại mỗi cái tự làm lại, và dọn sạch cả sáu cảnh báo <code>a11y_interactive_supports_focus</code> còn tồn đọng. <code>HitViewer</code>, <code>QuickLook</code>, <code>RegexBuilder</code> và trình hướng dẫn lần chạy đầu cố ý giữ shell riêng — một lớp nền đặt cạnh, điều hướng bằng phím mũi tên, một popover và một cổng không thể đóng lại không phải là cùng một thành phần.","changelog.05849c3f2c94":"<code>portable::open_log</code>, <code>service::scan</code>, <code>app_data_root</code> và <code>resultsStore.hitById</code> thay thế các bản sao trùng lặp của chúng.","changelog.fe8ee15bb86d":"CI","changelog.44ad89dc0cf1":"<code>cargo nextest</code> thay thế <code>cargo test</code>: phần lớn trong số 760 bài kiểm thử tự dựng chỉ mục Tantivy riêng, và mỗi bài kiểm thử một tiến trình giúp chúng không giẫm lên khóa của nhau. Đo khi đã chạy nóng trên máy phát triển: 100s → 37s.","changelog.2892b412468b":"Một nhóm kiểm thử của nextest giới hạn các gói dựng chỉ mục ở bốn tiến trình đồng thời. Không có giới hạn đó, mức đồng thời tăng thêm đã biến lỗi tranh chấp đã biết giữa Windows Defender và Tantivy, <code>Access is denied (os error 5)</code>, từ thỉnh thoảng thành tái hiện được — hai lần chạy liên tiếp thất bại ở ba bài kiểm thử khác nhau. Giới hạn này tốn ~2s và bộ kiểm thử vẫn chạy trong một phần năm thời gian của <code>cargo test</code>.","changelog.f600da3213ca":"Các lần chạy đã lỗi thời trên một nhánh sẽ bị hủy; <code>main</code> được miễn để nó tiếp tục nạp bộ đệm mà mọi nhánh khôi phục từ đó.","changelog.6811b6eaa5cb":"<code>CARGO_INCREMENTAL=0</code>, bộ đệm chỉ được ghi từ <code>main</code>, <code>--locked</code> ở mọi nơi, một lần cài đặt pnpm bị đóng băng, và các cổng không phụ thuộc hệ điều hành (<code>i18n-lint</code>, doctest) chạy trên một runner thay vì ba.","changelog.8266aee5f502":"<code>scripts/ci-local.mjs</code> có thêm cổng <code>src-tauri</code> còn thiếu và chạy song song làn Rust và làn giao diện: 133s công việc trong 89s.","changelog.9f749fdcd708":"[0.23.0] — Build 3 · Cổng ổn định Must-Have, phần 3 trên 3 (2026-08-03)","changelog.c5819508ac2c":"Bản cuối trong ba bản dựng Must-Have: SRC-M17 … SRC-M24. Phát hành thành v0.23.0, thẻ <strong>ổn định</strong>.","changelog.7c2c8aacfd91":"<strong>SRC-M17 — chế độ di động.</strong> <code>freally --portable</code>, hoặc một tệp <code>portable.flag</code> trống đặt cạnh tệp nhị phân, giữ chỉ mục, cài đặt, dấu trang, con trỏ nhật ký và nhật ký hoạt động trong một thư mục <code>Data/</code> cạnh tệp thực thi, và ngăn ứng dụng đăng ký bất cứ thứ gì với hệ điều hành. Cả ba tệp nhị phân đều nhận công tắc này; chính tệp cờ là thứ khiến một tệp zip hay AppImage được nhấp đúp trở thành di động mà không cần dòng lệnh nào.","changelog.c081711c3fde":"Bố cục nằm trong <code>freally_rpc::portable</code> — crate duy nhất mà shell Tauri, daemon và CLI vốn đều đã phụ thuộc vào.","changelog.260a841f6090":"Những gì chế độ di động cố ý <em>không</em> làm, mỗi điều vì một lý do cụ thể chứ không phải cho gọn gàng:","changelog.e53f7037be43":"<strong>Không có dịch vụ, plist launchd hay unit systemd.</strong> <code>freally-indexd install</code> / <code>uninstall</code> / <code>service</code> đều từ chối khi ở chế độ di động. Mỗi lệnh ghi một mục đăng ký tồn tại lâu hơn cả chiếc USB và trỏ tới một đường dẫn sẽ không còn ở đó trong lần khởi động sau. <code>uninstall</code> bị từ chối vì lý do ngược lại: một bản di động chưa bao giờ đăng ký gì, nên để nó chạy sẽ gỡ đăng ký bản <em>đã cài đặt</em> trên máy chủ.","changelog.d1f534b3e627":"<strong>Không đăng ký giao thức <code>freally://</code>.</strong> Việc đó ghi một trình xử lý ở cấp máy, trỏ tới đường dẫn hiện tại của tệp thực thi; rút USB ra là mọi liên kết <code>freally://</code> trên máy đó trỏ vào hư không. Bộ lắng nghe bên trong tiến trình vẫn chạy, nên một phiên bản di động vẫn xử lý các URL được trao cho nó — nó chỉ không nhận quyền với giao thức đó.","changelog.6320d3fbbef5":"<strong>Không có trình cập nhật tự động.</strong> Trình cập nhật chạy một <em>trình cài đặt</em>. Hướng nó vào một chiếc USB sẽ cài ứng dụng lên máy chủ, chính là điều duy nhất mà người dùng bản di động muốn tránh. Bản cài di động được cập nhật bằng cách thay thư mục.","changelog.01ed92501ea3":"<strong>Không tiếp quản dịch vụ Windows.</strong> Dịch vụ đó sở hữu chỉ mục đã cài đặt dưới <code>%PROGRAMDATA%</code>; một lần khởi chạy di động kết nối với nó sẽ lặng lẽ tìm trong chỉ mục của máy chủ và ghi hoạt động của chiếc USB vào đó.","changelog.9f519044c9bf":"<strong>Không có <code>taskkill</code> giữa các phiên bản.</strong> Cơ chế chỉ cho phép một phiên bản dừng tiến trình theo tên image. Một chiếc USB cắm vào máy đang chạy Freally sẽ đánh sập ứng dụng mà người dùng đang dùng dở.","changelog.f0f408322071":"Có hai phần trạng thái cần được chuyển hướng rõ ràng vì chúng không nằm dưới gốc chỉ mục:","changelog.ada349238a7a":"<strong>Con trỏ nhật ký.</strong> Mỗi bộ đăng ký theo dõi của hệ điều hành mặc định dùng thư mục riêng cho từng người dùng, nên một bản cài di động lẽ ra sẽ để lại con trỏ trên mọi máy mà nó được cắm vào. Giờ chúng được đưa vào <code>Data/cursors</code>.","changelog.8ea42f81060c":"<strong>Socket RPC, thứ cố ý không đặt trên USB.</strong> USB thường dùng FAT32 hoặc exFAT — những hệ thống tệp hoàn toàn không chứa được Unix domain socket, và không có bit quyền cho phép kiểm tra 0600 + peer-uid mà lớp truyền tải dựa vào. Nó nằm trong thư mục tạm của máy chủ, dưới một cái tên được suy ra từ gốc di động, nên một phiên bản di động không bao giờ đụng độ với phiên bản đã cài đặt hay với một chiếc USB thứ hai, và cách xác thực vẫn không đổi.","changelog.f576d6d3c2e0":"Nhật ký được chuyển chỗ vì một tệp nhị phân được nhấp đúp không có console nào để thừa hưởng: cả hai tiến trình ghi vào <code>Data/logs/</code>, và quay về console nếu tệp đó không mở được, thay vì đánh mất chính những thông tin chẩn đoán có thể giải thích vì sao.","changelog.2af97df221d3":"Trên macOS, <code>Data/</code> được đặt cạnh <code>Freally.app</code> chứ không phải bên trong — ghi dữ liệu người dùng vào trong một bundle sẽ phá hỏng chữ ký mã và thất bại ngay trên một ổ gắn kết chỉ đọc.","changelog.8b231cae5059":"<strong>Cũng trong thay đổi này: bảng Giới thiệu báo sai phiên bản.</strong> Nó chứa một giá trị <code>0.19.84</code> viết cứng và đã tụt ba bản phát hành so với những gì được phát hành. Giờ nó đọc phiên bản từ tiến trình đang chạy qua một lệnh mới <code>app_environment</code>, lệnh này còn cho biết đây có phải bản cài di động hay không và nó ghi vào thư mục nào — để người dùng cắm USB vào máy của người khác có thể xác nhận ngay trong ứng dụng rằng không có gì được ghi lên máy chủ.","changelog.9ee660246eb6":"Smoke: <code>tests/smoke/build_03_portable.rs</code> đặt một bản sao của tệp nhị phân daemon thật vào một thư mục tạm (chế độ di động được định nghĩa tương đối với tệp thực thi, nên kiểm thử tại chỗ sẽ biến mọi tệp nhị phân khác trong workspace thành di động suốt phần còn lại của lần chạy) và chứng minh tệp cờ, công tắc, ba lần từ chối đăng ký, và rằng một daemon di động ghi chỉ mục và nhật ký của nó vào <code>Data/</code> chứ không vào đâu khác.","changelog.b20d6ec3f044":"<strong>SRC-M24 — sắp xếp tự nhiên.</strong> Các dãy chữ số trong tên được đọc như số, nên <code>file2</code> đứng trước <code>file10</code> và <code>v1.9</code> đứng trước <code>v1.10</code>. Bật theo mặc định, có thể tắt tại Cài đặt → Kết quả → <em>Sắp xếp tự nhiên</em>.","changelog.88d62d00604a":"Nó áp dụng cho mọi cột chuỗi — tên, đường dẫn, loại và phần mở rộng — chứ không chỉ tên, để &quot;sắp xếp tự nhiên&quot; không lặng lẽ có nghĩa là &quot;sắp xếp tự nhiên cột tên&quot;.","changelog.52f34cd037df":"Có hai hàm so sánh vì có hai lần sắp xếp: daemon sắp xếp những gì nó trả về (<code>crates/freally-query/src/natural.rs</code>) và danh sách kết quả sắp xếp lại ở phía máy khách (<code>apps/freally-ui/src/lib/util/natural.ts</code>). Chúng cố ý không giống hệt nhau — giao diện cho các đoạn không phải chữ số đi qua <code>localeCompare</code> để dấu và chữ hoa/thường vẫn hoạt động như trước, trong khi daemon chỉ bao giờ thấy tên ở dạng viết thường — nên một vectơ trường hợp dùng chung ghim lại hành vi số mà cả hai phải thống nhất, được khẳng định từ cả hai phía.","changelog.4ac049addd1f":"Những chi tiết đáng nói rõ, vì mỗi chi tiết là một cách để làm sai việc này:","changelog.7548bb140901":"<strong>Dãy chữ số được so sánh mà không phân tích thành số.</strong> Việc phân tích bị giới hạn ở <code>u64</code> (hoặc 2^53 trong JS); một dãy 30 chữ số trong tên tệp là hiếm nhưng không sai, và khi đó hai dãy quá dài khác nhau sẽ bị coi là bằng nhau. So sánh số chữ số có nghĩa rồi đến từng chữ số thì chính xác ở mọi độ dài.","changelog.b4e5975dde5b":"<strong>Số không đứng đầu chỉ là cách phân xử cuối cùng.</strong> <code>file07</code> và <code>file7</code> là cùng một số, nên phần độn chỉ quyết định khi không còn gì khác quyết định — quyết định dựa vào nó ngay khi nó xuất hiện sẽ khiến <code>file07b</code> thắng <code>file7a</code>.","changelog.b682aa249886":"<strong>Giao diện chỉ so sánh một đoạn không phải chữ số đến chừng nào cả hai bên đều còn đoạn đó.</strong> Một đoạn có thể bị một chữ số cắt ngắn ở bên này mà không ở bên kia — <code>img.png</code> so với <code>img1.png</code> cho ra các đoạn dài 7 và 3 — và so sánh nguyên cả hai đoạn sẽ phân thắng thua theo độ dài thay vì theo <code>.</code> so với <code>1</code>, khiến <code>img.png</code> bị xếp cuối. Đã được vectơ dùng chung bắt được.","changelog.efabda690420":"<strong>Chuỗi không có chữ số vẫn đi nguyên vẹn qua <code>localeCompare</code></strong>, nên trường hợp phổ biến giữ đúng cách đối chiếu mà nó vốn có.","changelog.e3d8b9588796":"<strong>Cột đường dẫn là nơi duy nhất mà công tắc này thay đổi nhiều hơn chữ số.</strong> Khi tắt sắp xếp tự nhiên, nó vẫn là <code>PathBuf::cmp</code>, thứ sắp xếp theo từng thành phần chứ không theo byte; sắp xếp tự nhiên phải đọc đường dẫn như văn bản thì mới thấy được các dãy chữ số.","changelog.52750ba0909a":"<strong>Tệp không có phần mở rộng vẫn được xếp đầu tiên</strong>, như <code>Option::cmp</code> đã làm.","changelog.67df3bc8e4ae":"Mô tả tính năng yêu cầu thứ tự này phải &quot;được các chỉ mục sắp xếp nhanh tôn trọng&quot;. Không có chỉ mục nào như vậy để tôn trọng: việc sắp xếp diễn ra trong <code>sort_rows</code> trên các hàng ứng viên mà executor đã dựng sẵn, và hiện chưa có chỉ mục tăng tốc sắp xếp nào trong kho lưu trữ. Xây dựng một chỉ mục như thế là công việc cỡ SRC-N, nên điều này được nói rõ thay vì lặng lẽ bỏ qua.","changelog.bd0993897678":"Smoke: <code>tests/smoke/build_03_natural_sort.rs</code> lập chỉ mục những cái tên mà thứ tự byte và thứ tự tự nhiên khác nhau ở mọi mục, và ghim lại hành vi mặc định, việc tắt, thứ tự giảm dần, cột đường dẫn, và việc một cột số được để nguyên.","changelog.b190e0af1450":"<strong>SRC-M23 — bỏ qua dấu câu, bỏ qua khoảng trắng và khớp neo.</strong> Hai công tắc mới dưới <code>Search →</code> (<code>Ignore Punctuation</code>, <code>Ignore Whitespace</code>) và hai công cụ sửa đổi DSL mới, <code>name^:report</code> (bắt đầu bằng) và <code>name$:final</code> (kết thúc bằng).","changelog.e35e30b09372":"<strong>Bốn công tắc khớp có sẵn giờ thực sự làm được việc.</strong> Cho đến Build 2, chỉ có <code>match_phonetic</code> được truyền qua kênh truyền: <code>Match Case</code>, <code>Match Whole Word</code>, <code>Match Path</code> và <code>Match Diacritics</code> chỉ di chuyển một dấu kiểm mà không thay đổi gì, vì <code>query.run</code> chỉ gửi đúng một cờ đó và daemon dựng <code>MatchMode</code> từ <code>Default</code>. Executor thì vẫn luôn tôn trọng cả năm cờ. Giờ toàn bộ tập cờ được gửi đi và được đọc.","changelog.827fa9647b52":"<strong>Một lỗi liên quan, phát hiện trong lúc nối dây: <code>Match CJK Phonetics</code> chưa bao giờ được lưu lại.</strong> <code>settings_set</code> tuần tự hóa lại struct cài đặt rồi phân tích kết quả trở lại, mà <code>SearchOpts</code> bên Rust không có trường <code>match_phonetic</code> — nên cờ này bị đánh rơi ở <em>mỗi lần ghi cài đặt</em>. Build 2 chỉ thêm nó ở phía TypeScript. Giờ cả ba cờ mới cũng có trong struct Rust.","changelog.32c9128fe95e":"Ghi chú triển khai:","changelog.c4202016a76a":"<strong>Cả hai phía đều được lược bỏ, không chỉ phía đích.</strong> Chỉ lược bỏ ở tên sẽ khiến <code>foobar</code> tìm thấy <code>foo-bar</code> trong khi <code>foo-bar</code> lại không tìm thấy <code>foobar</code> — điều đó trông như một lỗi chứ không phải một chế độ khớp.","changelog.09e51f90e5b3":"<strong>Hạt giống trigram bị bỏ khi một chế độ viết lại văn bản.</strong> <code>foo-bar</code> lập chỉ mục các trigram <code>foo</code>, <code>oo-</code>, <code>o-b</code>, <code>-ba</code>, <code>bar</code>; từ cần tìm <code>foobar</code> đòi <code>oob</code> và <code>oba</code>, những thứ hàng đó không có, nên việc gieo hạt sẽ lặng lẽ trả về <em>hoàn toàn không gì cả</em>. Executor lùi về quét toàn bộ, đúng sự đánh đổi mà <code>match_path</code> vốn đã chấp nhận. Các cờ này tắt theo mặc định, nên không ai phải trả giá nếu không yêu cầu.","changelog.24e406c88eff":"<strong>Khớp toàn bộ từ bị bỏ qua khi một chế độ lược bỏ đang bật</strong>, vì bỏ các dấu phân cách đi cũng là bỏ đi ranh giới từ vốn định nghĩa nó.","changelog.c0189eb66ffc":"<strong><code>name:foo-bar</code> hoạt động như cụm từ trơn <code>foo-bar</code>.</strong> Đây là cùng một truy vấn viết theo hai cách, nên nhánh <code>name:</code>/<code>child:</code> cũng tôn trọng các chế độ lược bỏ chứ không chỉ nhánh cụm từ nguyên văn.","changelog.5d357f0cb708":"<strong>Dấu câu theo định nghĩa của Unicode, không phải một danh sách ASCII</strong>, nên <code>’</code> và <code>–</code> cũng bị bỏ cùng với <code>'</code> và <code>-</code>.","changelog.8b12742c48b5":"Với các công cụ sửa đổi neo, <code>^</code> và <code>$</code> chỉ được cho phép cho đúng hai khóa thay vì được thêm vào bộ ký tự khóa chung — cùng cơ chế mà các khóa có dấu gạch nối dùng, và cùng lý do theo Quy tắc thường trực #8: mở rộng bộ ký tự sẽ biến <code>x^2:3</code> và <code>total$:5</code> từ cụm từ nguyên văn thành lỗi phân tích cú pháp cứng. Cả hai đều bị từ chối dưới <code>--strict-everything</code>, vì Everything của voidtools không có cú pháp neo. <code>name$:</code> neo vào toàn bộ tên kể cả phần mở rộng, nên <code>name$:report</code> không khớp với <code>report.txt</code>.","changelog.573c5bc71314":"Đăng ký một công cụ sửa đổi mới chạm tới nhiều thứ hơn trình phân tích, và bỏ sót bất kỳ chỗ nào cũng khiến nó chỉ chạy được một nửa: biến thể AST, bốn vị trí trong planner/evaluator ở <code>exec.rs</code>, <code>optimizer::selectivity_rank</code> (một phép khớp neo hẹp hơn chuỗi con mà nó ngụ ý, nên được xếp hạng trước <code>child:</code>), danh sách chế độ nghiêm ngặt ở <em>hai</em> nơi, bộ ký tự khóa bị nhân bản trong <code>report.rs</code> — bỏ sót chỗ đó thì truy vấn vẫn chạy đúng trong khi thanh tìm kiếm tô nó như văn bản nguyên văn — cộng thêm <code>modifier_name</code>, <code>ModifierDetail</code> và bảng <code>MODIFIER_KEYS</code> được công bố mà phần tự hoàn thành của CLI đọc.","changelog.5b298995d56c":"Chỗ cuối cùng đó có một lỗ hổng đáng ghi nhận: <code>every_advertised_modifier_is_known_to_the_parser</code> không thể bắt được một khóa có ký tự đặc biệt bị thiếu, vì một khóa nằm ngoài bộ ký tự sẽ bị hạ xuống thành <em>văn bản nguyên văn</em> thay vì thành <code>UnknownModifier</code>, nên bài kiểm thử vẫn qua dù thế nào. Một phép khẳng định dương đã được thêm vào.","changelog.7cd3e842fd15":"<strong>SRC-M20 — trình tạo biểu thức chính quy và bộ kiểm tra trực tiếp.</strong> Một popover cạnh công tắc regex mới trên thanh tìm kiếm: một ô nhập mẫu, lỗi biên dịch của chính bộ máy, một bảng tra nhanh theo kiểu Rust, và việc tô sáng trực tiếp những gì mẫu khớp trong 50 tên kết quả đầu hiện tại, kèm số đếm &quot;3 trong 50 tên đang hiển thị khớp&quot;. Xác nhận mẫu sẽ viết lại truy vấn thành <code>regex:&lt;pattern&gt;</code> và bật Bật regex, để menu không bao giờ mâu thuẫn với những gì truy vấn đang làm.","changelog.fc32c438e9b3":"Viên thông báo lỗi phân tích cú pháp và phần di chuột xem AST đã xác thực một truy vấn mà bạn <em>đã viết</em>; không có gì giúp bạn viết mẫu cả. Thời gian mất chính ở đó — bạn gõ gì đó, chạy, không được gì, và không biết là mẫu sai hay đơn giản là tệp không có ở đó. Popover cho thấy cả hai câu trả lời cùng lúc.","changelog.8f5e99706420":"<strong>Việc kiểm tra diễn ra trong Rust, có chủ đích.</strong> Cách làm hiển nhiên là xác thực bằng <code>RegExp</code> của webview, và nó sẽ sai đúng ở những trường hợp mà người soạn mẫu gặp phải: executor của truy vấn chạy crate <code>regex</code>, thứ không có tham chiếu ngược và không có lookaround, xử lý <code>\\d</code> theo Unicode, và nhận <code>(?i)</code> dạng nội tuyến chứ không phải cờ ở cuối. Một trình tạo dựa trên <code>RegExp</code> sẽ vui vẻ chấp nhận <code>(?&lt;=foo)bar</code> rồi thất bại khi truy vấn chạy. <code>regex_test</code> biên dịch bằng cùng bộ máy, nên &quot;ở đây khớp&quot; nghĩa là &quot;ở đó sẽ khớp&quot; — có một bài kiểm thử đơn vị khẳng định rằng lookaround bị từ chối, chính vì lý do này.","changelog.6e60e7b42f67":"Những quyết định nhỏ hơn, mỗi cái bảo vệ một điều có thật: các đoạn khớp được trả về dưới dạng vị trí <strong>ký tự</strong>, vì giao diện cắt chúng bằng chỉ số chuỗi JavaScript và một vị trí byte sẽ cắt đôi một tên có ký tự nhiều byte; các phép khớp có độ rộng bằng không bị bỏ, vì <code>a*</code> khớp ở mọi vị trí và tô sáng khoảng trống ở mọi vị trí chỉ là nhiễu; một mẫu trống hoàn toàn không báo lỗi thay vì nháy lỗi ngay ở phím gõ đầu tiên; và giới hạn kích thước của automaton đã biên dịch được ghim ở 256 KB thay vì mặc định 10 MB của crate. Bộ máy dựa trên automaton hữu hạn, nên một mẫu độc hại không thể quay lui theo cấp số mũ — giới hạn kích thước là đòn bẩy duy nhất có ý nghĩa, và nó đã được đặt.","changelog.11270a28687b":"<strong>SRC-M19 — Xem nhanh bằng phím cách.</strong> Nhấn phím cách trên một kết quả mở ra một bản xem trước dạng hộp thoại lớn; các phím mũi tên đi qua tập kết quả trong khi nó vẫn mở, và phím cách hoặc Esc đóng nó lại. Phần đầu hiển thị &quot;7 trên 50&quot; để bạn biết mình đang ở đâu trong tập kết quả.","changelog.d3e1342a48af":"Đây không phải một bản cài đặt xem trước thứ hai — nó gọi cùng <code>files_preview</code> như khung xem trước được neo, nên định dạng nào hiển thị được ở bên này thì cũng hiển thị được ở bên kia. Thứ nó thêm vào là kích thước và luồng thao tác bằng bàn phím: khung neo là thứ bạn liếc qua, còn đây là cử chỉ &quot;tệp này <em>là</em> gì?&quot;, và điểm mấu chốt là tay bạn không bao giờ rời bàn phím.","changelog.273a049cb91a":"<strong>Phím cách được xử lý trong bộ gán phím toàn cục, không phải trong thành phần</strong>, và đây là phần tinh tế: phím cách cũng là một ký tự, nên nó bị bỏ qua mỗi khi con trỏ nhập liệu nằm trong một input, textarea, select hoặc contenteditable. Làm sai chỗ này đồng nghĩa với việc ô tìm kiếm không còn nhận dấu cách — một lỗi tệ hơn nhiều so với việc thiếu một phím tắt.","changelog.ca26390b3e56":"Việc điều hướng đi theo đúng thứ tự mà danh sách thực sự <em>hiển thị</em> (các lô theo thứ tự ống kính, áp dụng kho sắp xếp bên trong từng lô, trừ những lô cụm trùng lặp mà daemon đã sắp xếp hàng sẵn và sắp xếp lại sẽ làm vỡ các cụm). Đi theo bất kỳ thứ tự nào khác sẽ khiến phím mũi tên trông như nhảy lung tung. Việc di chuyển dừng lại ở cả hai đầu thay vì quay vòng, vì quay vòng từ hàng cuối về hàng đầu trông như một trục trặc khi giữ phím, và nó thay thế lựa chọn thay vì mở rộng lựa chọn.","changelog.f6f10923fe43":"<strong>Khác biệt so với mô tả tính năng, được nói rõ thay vì lướt qua.</strong> Mô tả yêu cầu QuickLook gốc trên macOS và trình lưu trữ riêng của Freally ở các nơi khác. <code>qlmanage -p</code> mở một <em>cửa sổ hệ điều hành riêng</em> mà phần xử lý phím của Freally không điều khiển được, nên lấy nó làm mặc định trên macOS sẽ phá vỡ luồng thao tác bằng phím mũi tên vốn là toàn bộ tính năng. Vì vậy hộp thoại trong ứng dụng là giao diện trên cả ba nền tảng — điều này cũng khiến hành vi kiểm thử được và giống nhau ở mọi nơi — và macOS còn có thêm một nút rõ ràng &quot;Mở bằng Xem nhanh của macOS&quot; cho những định dạng mà hệ thống hiển thị được còn trình xem trước của Freally thì không. Đường dẫn đi qua cùng cổng <code>KnownPaths</code> như mọi lệnh tệp khác và được truyền dưới dạng một đối số <code>Command</code>, không bao giờ qua shell.","changelog.6fba87d13646":"<strong>SRC-M22 — thanh bên dấu trang và bộ lọc.</strong> Một cột bên trái tùy chọn (Xem → Thanh bên, mặc định tắt) với bốn phần: dấu trang có thể kéo để sắp xếp lại, bảy bộ lọc loại tệp, các ổ đĩa đã lập chỉ mục, và tìm kiếm gần đây. Cả bốn thứ này vốn đã có, nhưng nằm sau ba danh sách thả xuống khác nhau và một menu, nên thu hẹp phạm vi tìm kiếm đồng nghĩa với việc phải biết tìm ở chỗ nào trong bốn chỗ; giờ chúng được gom vào một cột gồm các mục bấm được.","changelog.2af93b3b0eaf":"<strong>&quot;Tìm kiếm gần đây&quot; phải được nghĩ ra từ đầu, vì việc tìm kiếm ở đây diễn ra trực tiếp.</strong> <code>run()</code> chạy ở mỗi phím gõ, nên ghi lại nguyên văn từng lần chạy sẽ tạo ra <code>r</code>, <code>re</code>, <code>rep</code>, <code>repo</code>, <code>repor</code>, <code>report</code> và chôn vùi mục duy nhất mà người ta muốn. Hai quy tắc giải quyết chuyện này mà không cần một cử chỉ xác nhận rõ ràng mà giao diện không có: một truy vấn mới loại bỏ mọi mục hiện có là tiền tố của nó (các phím gõ trên đường tới đó), và một truy vấn mà bản thân nó là tiền tố của mục mới nhất thì không được ghi lại (đó là một lần xóa lùi). Gõ &quot;report&quot; rồi &quot;invoice&quot; sẽ để lại đúng <code>[&quot;invoice&quot;, &quot;report&quot;]</code>.","changelog.97fe3ffe9b63":"Danh sách này tôn trọng <strong>Chế độ riêng tư và công tắc Lịch sử tìm kiếm</strong> — cả hai vốn đã có nghĩa là &quot;đừng lưu lại những gì tôi đã tìm&quot;, và một phần trên thanh bên chính là một bản ghi như vậy, nên nó không lặng lẽ giữ bản sao của riêng mình.","changelog.736397e92eea":"Thứ tự kéo thả được lưu dưới dạng một danh sách ID dấu trang trong cài đặt thay vì trên bản ghi dấu trang, nên việc sắp xếp lại không cần một đường ghi mới qua IPC dấu trang. ID của dấu trang đã xóa bị bỏ qua thay vì để lại một chỗ trống, và một dấu trang được thêm sau lần kéo cuối được nối vào cuối thay vì bị bỏ mất.","changelog.bb58e9012e27":"Các mục ổ đĩa tạo ra <code>volume:&quot;&lt;label&gt;&quot;</code> <strong>có dấu ngoặc kép</strong>, vì nhãn ổ đĩa thường chứa dấu cách (<code>Orange WD 4TB</code>) và nếu không có ngoặc kép sẽ bị phân tích thành hai cụm từ.","changelog.3ce317440cef":"Thanh bên được hiển thị bên trong <code>.result-area</code>, dùng chung một hàng flex với danh sách kết quả và khung xem trước, nên bật hay tắt nó không làm xáo trộn phần menu / tìm kiếm / trạng thái ở phía trên và phía dưới.","changelog.d5f690fcafa4":"<strong>Một chỗ trùng lặp phát hiện trong lúc nối dây</strong>, đáng ghi lại vì nó vốn đã sai: phần điều hướng của Xem nhanh được thêm vào ở SRC-M19 duyệt thẳng <code>resultsStore.batches</code>. Các lô được lưu theo thứ tự <em>đến</em> và mang cả kết quả từ những ống kính người dùng đã tắt lẫn những hàng mà một bộ lọc tinh chỉnh đã loại ra — trong khi danh sách được hiển thị qua <code>viewForLens</code> theo một thứ tự ống kính cố định. <code>resultsStore.visibleHits</code> vốn đã có và làm đúng việc này. Giờ hàm trợ giúp điều hướng được dựng trên cùng <code>viewForLens</code>, nên các phím mũi tên đi qua những gì đang có trên màn hình chứ không phải những gì daemon tình cờ gửi trước.","changelog.357a743ccb54":"<strong>SRC-M21 — báo cáo tình trạng quyền truy cập + trình hướng dẫn Quyền truy cập toàn bộ đĩa trên macOS.</strong> Công cụ → Tình trạng quyền truy cập, cùng một nhãn trên thanh trạng thái chỉ xuất hiện khi có điều cần nói, mở ra phần chi tiết về những thư mục mà trình quét không đọc được, trên ổ đĩa nào, vì lý do gì — kèm cách khắc phục có hướng dẫn cho nền tảng mà <em>chỉ mục</em> đang chạy.","changelog.b5aa6e1796c3":"<strong>Cái nhãn mà mô tả tính năng bảo hãy mở rộng thì không hề tồn tại.</strong> Không có dòng &quot;bỏ qua n đường dẫn (quyền truy cập)&quot; nào ở đâu cả: một thư mục mà trình quét không mở được chỉ tạo ra một dòng <code>warn!</code> và không gì khác, nên một cây con không đọc được trông y hệt một cây con trống. Sổ ghi (<code>crates/freally-indexd/src/permissions.rs</code>) phải được xây dựng trước. Đây là lần thứ tư trong đợt chạy tới cổng ổn định này mà điểm xuất phát được nêu của một tính năng Must-Have hóa ra không hề có.","changelog.62ca3f92cd3e":"Sổ ghi lưu lại những gì và vì sao:","changelog.d8706bc2b337":"<strong>Gốc, không phải tệp.</strong> <code>walkdir</code> báo một lỗi cho thư mục mà nó không mở được và không đi xuống sâu hơn, nên thứ đi vào sổ ghi tự nhiên là gốc của từng cây con không đọc được. Đó cũng là câu trả lời hữu ích: &quot;hãy cấp quyền truy cập thư mục này&quot;, chứ không phải mười nghìn tên tệp.","changelog.0917b96f248e":"<strong>Một đường dẫn biến mất không phải là lỗi.</strong> <code>NotFound</code> bị bỏ hoàn toàn — một tệp bị xóa giữa lúc quét là chuyện bình thường trên một hệ thống tệp đang hoạt động, và tính cả nó vào sẽ khiến mọi báo cáo trên một máy bận rộn trông đáng báo động.","changelog.4df4fedc30d4":"<strong>Giới hạn ở 2,000 mục, phần dư được đếm.</strong> Danh sách này được giữ trong bộ nhớ, tuần tự hóa và gửi qua IPC; quá vài nghìn mục thì nó không còn là một bản báo cáo mà người ta đọc. Giao diện ghi &quot;và 12,043 mục khác&quot; thay vì ngụ ý rằng danh sách đã đầy đủ.","changelog.45a8fa9b22b3":"<strong>Một lần quét lại sẽ xóa các mục của gốc đó trước</strong>, nên một quyền mà người dùng thực sự đã sửa sẽ không còn bị báo nữa. Không có điều đó, bản báo cáo chỉ có thể dài thêm.","changelog.8c83c3941420":"<strong>Được lưu lại</strong> vào <code>config/permissions.json</code>, vì &quot;những tệp tôi không lập chỉ mục được&quot; phải sống sót qua một lần khởi động lại thì mới có giá trị.","changelog.2272ff2f607f":"Hướng dẫn khắc phục được xác định <strong>ở phía daemon</strong>, không phải từ user-agent của trình duyệt: chỉ mục có thể nằm trên một máy khác với cửa sổ đang hiển thị báo cáo mỗi khi một máy khách được trỏ tới một điểm cuối từ xa, và cách khắc phục thuộc về chiếc máy đã không đọc được thư mục.","changelog.7bd109d95768":"Trên macOS, báo cáo <strong>phát hiện Quyền truy cập toàn bộ đĩa</strong> bằng cách đọc một thư mục được TCC bảo vệ: đọc được nghĩa là đã cấp, <code>PermissionDenied</code> nghĩa là chưa. Mọi lỗi khác được báo là <em>chưa xác định</em> thay vì &quot;chưa cấp&quot; — bảo ai đó sửa một cài đặt vốn đã đúng còn tệ hơn là không nói gì. Khi quyền chưa được cấp, một nút sẽ mở thẳng bảng Quyền truy cập toàn bộ đĩa.","changelog.bea94a4860c8":"Smoke: <code>tests/smoke/build_03_permissions.rs</code> chứng minh trình quét thực sự giữ sổ ghi — một cây sạch để sổ trống, và một lần quét thật bỏ các mục của lượt trước cho gốc đó mà vẫn để nguyên các gốc khác. Nó cố ý không thử tạo một thư mục bị từ chối truy cập: việc đó không mang đi được (<code>chmod 000</code> không có tác dụng với root, còn Windows sẽ cần can thiệp ACL), nên các nhánh bị từ chối được kiểm thử đơn vị bằng cách dựng trực tiếp <code>io::Error</code> thay vì nhờ hệ điều hành tạo ra.","changelog.a0e48a175453":"<strong>SRC-M18 — phát âm thanh/video ngay trong khung xem trước.</strong> Điều khiển phát (phát/tạm dừng, tua, lặp lại), một thanh trượt âm lượng, một dạng sóng được vẽ ra mà bạn có thể nhấp để tua, và các nhãn codec / tần số lấy mẫu / kênh / LUFS phủ lên trên. Nghe thử một kết quả <code>lufs:&lt;-14</code> không còn đồng nghĩa với việc rời khỏi Freally, và đó chính là quy trình mà ống kính âm thanh tồn tại để giữ bạn ở lại bên trong.","changelog.5677c3279dd5":"<strong>Dạng sóng không tốn thêm một lần giải mã nào.</strong> Một <code>PeakCollector</code> đi kèm lượt phân tích có sẵn trong <code>freally-audio</code>: chính các khung xen kẽ nuôi bộ tích lũy độ to và khoảng lặng cũng nuôi nó, nên mở một bản nhạc trong một khung được mở lại ở mỗi lần nhấn phím mũi tên không phải giải mã tệp lần thứ hai chỉ để vẽ hình của nó. Số ô là cố định thay vì theo từng giây, vì khung vẽ có chiều rộng cố định — lấy mẫu lại một đường bao theo giây cho vừa sẽ vứt bỏ đúng những đỉnh làm cho hình dạng dễ đọc — và các ô lấy đỉnh trên mọi kênh, vì một dạng sóng thể hiện thứ to nhất đang diễn ra ở thời điểm đó, chứ không phải ý kiến của kênh trái về nó.","changelog.cdfeb4ff1549":"<strong>Các byte đi qua IPC, không qua giao thức asset — một cách có chủ đích.</strong> Cách thông thường để nạp dữ liệu cho một phần tử media là giao thức asset của Tauri, và nó đã bị gạt đi: bật nó lên đồng nghĩa với việc khai báo một phạm vi hệ thống tệp mà <em>webview</em> được đọc trực tiếp, và bất kỳ phạm vi nào đủ rộng để bao trùm &quot;bất cứ nơi nào chứa media của người dùng&quot; cũng đủ rộng để vô hiệu hóa cổng <code>KnownPaths</code> mà Build 1 đã gia cố — đảm bảo rằng một phụ thuộc frontend bị xâm phạm không thể chạm tới một tệp mà daemon chưa bao giờ trả về. Đưa các byte qua một lệnh giữ cho mọi lần đọc nằm sau cùng phép kiểm tra như mọi thao tác tệp khác.","changelog.92840d3c1b10":"Cái giá phải trả là việc phát được đệm chứ không truyền phát, nên có một mức trần 192 MB — được ghi rõ trong giao diện, nơi đề nghị mở các tệp lớn hơn bằng trình phát của hệ thống, thay vì lặng lẽ thất bại. Các byte được trả về dưới dạng <code>tauri::ipc::Response</code> thô thay vì một data URL base64, thứ sẽ làm phình payload thêm một phần ba và tốn một lần mã hóa lại toàn bộ ở cả hai phía.","changelog.712f85c29448":"Hai điều nhỏ hơn mà mỗi điều đều có thể là một lỗi thật: object URL bị thu hồi khi lựa chọn thay đổi (không có điều đó, mỗi lần nhấn phím mũi tên sẽ rò rỉ cả một tệp đã giải mã), và một độ to tích hợp không hữu hạn được hiển thị là <em>không có nhãn</em> thay vì <code>-inf LUFS</code> — một đoạn ngắn hơn một khối gating thì không có giá trị tích hợp nào có ý nghĩa.","changelog.d91a498a29f7":"Việc phát được hay không được quyết định từ phần mở rộng của kết quả, không phải từ payload xem trước: payload của một tệp media là <code>unsupported</code>, mà đó lại chính là trường hợp đáng để phát.","changelog.7c9e53ab0e65":"Khép lại Build 3 — những gì các đợt rà soát đã thay đổi","changelog.4519ec9bebde":"<code>/simplify</code> cho bốn người rà soát đi qua toàn bộ diff của bản dựng. Ba người trong số đó độc lập chỉ ra cùng một điều, và hai phát hiện là lỗi thật chứ không phải chuyện văn phong:","changelog.8ce21698a623":"<strong>Thanh bên đánh rơi các bộ lọc đã lưu của một dấu trang.</strong> <code>applyBookmark</code> tự cài đặt lại luồng nạp của danh sách thả xuống và bỏ sót <code>typeFilterStore.setFromIds(...)</code>, nên mở một dấu trang từ thanh bên tạo ra tiền tố ống kính khác với khi mở cùng dấu trang đó từ danh sách thả xuống. Giờ cả hai đều gọi một <code>bookmarksStore.apply</code> duy nhất.","changelog.eac5108065c7":"<strong><code>visibleHits</code> tồn tại hai lần, với hai câu trả lời khác nhau.</strong> Bản sao của Xem nhanh có sắp xếp; <code>resultsStore.visibleHits</code> — thứ mà xuất, chọn tất cả và số đếm trên thanh trạng thái đọc — thì không. Hai bên lệch nhau ngay khi có một cột đang được sắp xếp. Việc sắp xếp đã được chuyển vào getter của kho và bản sao đã bị bỏ, điều này cũng khiến lời chú thích của getter đó, &quot;câu trả lời duy nhất cho những gì người dùng đang nhìn thấy&quot;, trở thành sự thật thay vì chỉ là mong muốn.","changelog.c773525b8054":"<strong>Hai danh sách chế độ nghiêm ngặt được đồng bộ bằng tay đã lệch nhau.</strong> Danh sách các công cụ sửa đổi chỉ Freally có của trình phân tích chứa <code>volume:</code>, còn bản sao trong <code>report.rs</code> thì không, nên một truy vấn strict-everything dùng <code>volume:</code> bị trình phân tích từ chối trong khi bản báo cáo mà thanh tìm kiếm dựa vào để hiển thị lại coi là ổn. Giờ chỉ còn một <code>is_freally_only_modifier</code>.","changelog.67e8b82d717f":"Những phát hiện về hiệu năng đáng ghi lại, tất cả đều trên các nhánh mã mà bản dựng này thêm vào:","changelog.193b3787c53e":"Effect của nhãn quyền truy cập chạy lại ở mỗi lần thăm dò trạng thái chỉ mục — <code>indexStateStore</code> gán lại toàn bộ đối tượng trạng thái, nên &quot;đọc <code>phase</code>&quot; bị vô hiệu bất kể <code>phase</code> có thay đổi hay không. Nó thực hiện một vòng khứ hồi IPC mỗi năm giây mãi mãi, mỗi lần nhân bản toàn bộ sổ ghi dưới một mutex. Giờ được canh theo pha thăm dò gần nhất.","changelog.25ff7799a027":"Hàm so sánh của sắp xếp tự nhiên chạy một regex cho mỗi <em>ký tự</em> và dựng một collator mới cho mỗi đoạn. Giờ là một phép kiểm tra code point và một <code>Intl.Collator</code> dùng chung.","changelog.282cbf6f5b04":"Sắp xếp theo đường dẫn chuyển đổi cả hai <code>PathBuf</code> ở mỗi lần so sánh — O(n log n) lần quét WTF-8. Giờ là decorate-sort-undecorate, mỗi hàng chuyển đổi một lần.","changelog.fa6395a85e8e":"Trình phát media nạp byte và dạng sóng lần lượt dù chúng độc lập với nhau; và khiến cả ~800 thanh của dạng sóng phụ thuộc vào tiến độ phát, nên mỗi <code>timeupdate</code> lại tính lại 800 biểu thức. Giờ hai việc chạy chồng lên nhau theo kiểu <code>Promise.all</code> và chỉ có một lớp phủ <code>--progress</code>.","changelog.1a1162f4da54":"Ngoài ra: <code>AnalysisOpts::peak_buckets</code> giờ là riêng tư, vì khi là trường <code>pub</code> thì nơi gọi có thể đặt nó trên <code>analyze_with_opts</code>, hàm không có chỗ nào để trả về các đỉnh và sẽ lặng lẽ bỏ chúng đi; và <code>media.rs</code> gọi <code>files::verify_readable</code> dùng chung thay vì bản sao riêng, nên mức nguồn gốc cho các lần đọc do frontend khẳng định được quyết định ở đúng một nơi.","changelog.c70a3b9f1590":"Khép lại Build 3 — những gì <code>/security-review</code> đã thay đổi","changelog.ccce544a9b0c":"Hai phát hiện mức HIGH, cả hai đều do bản dựng này đưa vào, cả hai đều đã được sửa.","changelog.de5618b9e06c":"<strong><code>media_bytes</code> được bảo vệ ở mức mà frontend tự cấp được cho mình.</strong> Nó trả về <em>toàn bộ</em> nội dung của một tệp được nêu tên cho webview, và nó dùng <code>Provenance::FrontendAsserted</code> — mức mà <code>files_whitelist_user_chosen</code> cấp cho bất kỳ chuỗi nào lớp JS yêu cầu. Một phụ thuộc frontend bị xâm phạm đã có thể đưa <code>~/.ssh/id_ed25519</code> vào danh sách trắng rồi đọc nó, không cần hộp thoại nào và không có daemon tham gia. Hai lệnh khác trả về nội dung tệp, <code>content_document</code> và <code>copy_file_contents</code>, vốn đã đòi <code>QueryHit</code>; giờ hai lệnh này cũng vậy. Nơi gọi hợp lệ được điều khiển từ các hàng kết quả, vốn đã mang mức đó, nên người dùng không thấy gì thay đổi.","changelog.ec04c33c4cd8":"<strong>Socket của chế độ di động nằm thẳng trong thư mục tạm dùng chung.</strong> <code>/tmp</code> có chế độ 1777 và cái tên là một hàm băm FNV của một đường dẫn dễ đoán, nên bất kỳ tài khoản cục bộ nào cũng có thể chiếm nó trước. Lớp truyền tải xác thực <em>phía bên kia</em> của một bộ lắng nghe mà nó sở hữu; còn một máy khách kết nối ra ngoài thì không kiểm tra gì, nên chiếm đường dẫn đó đồng nghĩa với mạo danh daemon hoàn toàn — và <code>register_hit_paths</code> biến mọi thứ đến trong một <code>query:batch</code> thành <code>Provenance::QueryHit</code>, chính là cổng cho xóa, đổi tên và mọi lệnh phá hủy khác. Ba thay đổi:","changelog.7cf7132d7226":"Socket được chuyển vào một thư mục riêng cho từng người dùng — <code>$XDG_RUNTIME_DIR</code> nếu có, nếu không thì là một thư mục con gắn uid mà tiến trình này tạo ra và chmod 0700, đồng thời từ chối thẳng nếu hóa ra nó thuộc sở hữu của người khác.","changelog.aadc9d78386e":"<code>transport::unix::connect</code> giờ từ chối một socket không thuộc sở hữu của người dùng này, hoặc có chế độ cho phép người khác truy cập. Nó dùng <code>symlink_metadata</code>, nên một symlink trỏ tới một socket mà chúng ta sở hữu không qua được phép kiểm tra. Đây là mảnh ghép còn thiếu tương ứng với phép kiểm tra peer-uid của bộ lắng nghe.","changelog.0ed10670ac32":"<code>listen</code> không còn thất bại cứng khi không thể siết chặt thư mục cha của socket. <code>chmod 0700 /tmp</code> trả về <code>EPERM</code> cho mọi người dùng không phải root, nên <strong>chế độ di động hoàn toàn không khởi động được daemon của nó trên Linux</strong> — bước gia cố đã đánh sập chính thứ nó định bảo vệ. Giờ nó ghi nhật ký và dựa vào chế độ 0600 riêng của socket.","changelog.ba70757e3b85":"[0.22.0] — Build 2 · Cổng ổn định Must-Have, phần 2 trên 3 (2026-08-02)","changelog.9bd054757229":"Bản thứ hai trong ba bản dựng Must-Have: SRC-M09 … SRC-M16. Đa nền tảng trừ khi có ghi chú riêng cho từng hệ điều hành. Tài liệu đầy đủ về tính năng nằm trong <code>docs/documentation.html</code>.","changelog.d9bb66b60223":"<strong>SRC-M09 — đầu ra CLI cho máy đọc.</strong> <code>freally search</code> có thêm <code>--json</code>, <code>--ndjson</code> (mỗi kết quả một đối tượng, truyền phát), <code>--csv</code>, <code>--fields</code> để chọn cột, <code>-0</code> cho <code>xargs -0</code>, <code>--limit</code> / <code>--offset</code>, và mã thoát có ý nghĩa (0 có kết quả, 1 không có, 2 lỗi).","changelog.758c601a0121":"<strong>SRC-M10 — tự hoàn thành cho shell.</strong> <code>freally completions &lt;shell&gt;</code> in phần tự hoàn thành cho bash, zsh, fish và PowerShell, bao gồm các lệnh con, cờ, và — một cách động — các từ khóa công cụ sửa đổi và tên các lần tìm kiếm đã lưu.","changelog.88b57e0c662b":"<strong>SRC-M11 — &quot;có phải ý bạn là&quot; chịu được lỗi đánh máy.</strong> Khi ống kính tên tệp không trả về gì, các ứng viên tương đồng được xếp hạng lại theo khoảng cách Damerau-Levenshtein có giới hạn, và ứng viên gần nhất được đề xuất như một lần sửa chỉ bằng một cú nhấp.","changelog.651b223b2f18":"<strong>SRC-M12 — khớp phiên âm CJK.</strong> Gõ <code>wenjian</code> hoặc <code>wj</code> sẽ khớp với <code>文件</code>; romaji khớp với kana; jamo đầu khớp với Hangul. Cách đọc được lập chỉ mục thành các khóa tên phụ và chỉ bật khi bạn chọn qua <strong>Tìm kiếm → Khớp phiên âm CJK</strong>. Mọi phép chuyển đổi đều là tra bảng hoặc tính toán số học — tách Hangul hoàn toàn là phép tính trên khối âm tiết Unicode, kana dùng một bảng có sẵn trong cây mã, và cách đọc chữ Hán lấy từ crate <code>pinyin</code>.","changelog.1bd2b09ee538":"<strong>Ghi nhật ký thay đổi trực tiếp.</strong> Chỉ mục giờ được cập nhật khi tệp thay đổi, chứ không chỉ khi chạy một lần quét. Mọi bộ đăng ký theo dõi của hệ điều hành đều đã cài đặt <code>subscribe()</code> và <code>freally-index</code> đã có sẵn <code>EventQueue</code> có giới hạn, nhưng chưa có gì từng nối chúng lại: <code>Index::apply</code> và <code>EventQueue</code> chỉ chạm tới được từ benchmark và một bài kiểm thử đơn vị. <code>freally-indexd::watcher</code> chính là đường ống đó — một luồng sản xuất rút luồng thay đổi của hệ điều hành vào hàng đợi, và một bên tiêu thụ áp dụng và commit từng lô. Trên Windows, nhật ký USN tính theo từng ổ đĩa, nên các thư mục trên cùng một ổ được gộp vào một bộ theo dõi duy nhất lọc theo tiền tố đường dẫn; FSEvents và inotify theo dõi trực tiếp một cây con.","changelog.eaa3eb8d8d9f":"<em>Vì sao bên sản xuất bỏ sự kiện thay vì chặn lại:</em> chặn lại cũng không cứu được các sự kiện — bộ đệm phía hệ điều hành vẫn tiếp tục đầy lên trong lúc chúng ta chờ, và khi nó tràn thì sự kiện mất đi không để lại dấu vết. Bỏ ở ranh giới của chính chúng ta cũng mất đúng những sự kiện đó nhưng để lại một sổ ghi có đếm số và đóng dấu thời gian, và đó là thứ mà trình tư vấn bên dưới báo cáo.","changelog.71e6a83277bd":"<strong>SRC-M13 — bảng Tình trạng chỉ mục + trình tư vấn dựng lại.</strong> <strong>Công cụ → Bảo trì chỉ mục → Tình trạng chỉ mục</strong> báo cáo, cho từng vị trí đang được theo dõi, độ trễ từ sự kiện đến lúc truy vấn nhìn thấy được, một sổ ghi các sự kiện bị bỏ mất, thay đổi gần nhất đã thấy, và độ sâu hàng đợi, cùng lời khuyên dựa trên quy tắc kèm nút dựng lại chỉ bằng một cú nhấp khi dựng lại là cách khắc phục. Phần tồn đọng trích xuất nội dung được báo là <em>không theo dõi</em> thay vì bằng không — daemon không chạy worker trích xuất háo hức nào, và &quot;0&quot; sẽ bị hiểu là &quot;đang rảnh&quot;.","changelog.946db255ad4d":"<strong>SRC-M14 — danh mục ngoại tuyến cho ổ đĩa rời.</strong> Rút một ổ đĩa ra vẫn giữ các tệp trên đó tìm kiếm được, và kết quả từ một thiết bị đã tháo mang nhãn <em>ngoại tuyến — Orange WD 4TB</em>. <code>volume:</code> lọc theo cái tên mà bạn biết về ổ đĩa đó, hoặc theo ID ổ đĩa. Một ổ đĩa quay lại với ký tự ổ hoặc điểm gắn kết khác vẫn được nhận ra là cùng một danh mục.","changelog.f637da61fd70":"<em>Bên dưới:</em> cột <code>volume</code>, chỉ mục SQLite của nó và trường Tantivy đều đã có từ giai đoạn 4, nhưng hàm dựng hàng duy nhất trên đường nạp dữ liệu lại viết cứng một chuỗi rỗng, nên cả cột đó là cột chết. Giờ các hàng được đóng dấu bằng phép khớp tiền tố dài nhất trên bảng gắn kết thật, thứ duy nhất phân biệt được một điểm gắn kết với một thư mục bình thường.","changelog.4ec8be883d22":"<strong>SRC-M15 — đổi tên hàng loạt.</strong> Chọn bao nhiêu kết quả cũng được, nhấn <code>F2</code>, và mô tả thay đổi một lần: tìm và thay thế theo văn bản nguyên văn hoặc regex có nhóm bắt, bộ đếm <code>{n}</code> / <code>{n:03}</code>, đổi chữ hoa/thường, và lựa chọn đổi tên phần tên không có phần mở rộng hay toàn bộ tên. Một bảng trực tiếp hiển thị từng cặp trước/sau và đánh dấu những hàng sẽ trùng nhau, ghi đè lên một tệp có sẵn, hoặc tạo ra một tên mà hệ thống không chấp nhận. Cả loạt diễn ra theo kiểu tất cả hoặc không gì cả, và một lỗi giữa chừng sẽ được hoàn nguyên.","changelog.46851cce7744":"<em>Ghi chú:</em> lộ trình ghi rằng việc đổi tên một tệp đã được phát hành. Thực ra chưa — chỉ có đổi tên <em>dấu trang</em> là có — nên bản dựng này thêm cả thao tác đổi tên cơ bản lẫn lớp hàng loạt phía trên nó.","changelog.3fc85f03e023":"<strong>SRC-M16 — hoàn tác/làm lại cho thao tác tệp.</strong> <code>Ctrl+Z</code> đảo ngược một lần đổi tên hoặc đổi tên hàng loạt, <code>Ctrl+Shift+Z</code> làm lại nó, và nhật ký được daemon lưu lại nên 50 thao tác gần nhất sống sót qua một lần khởi động lại. Một loạt được tháo gỡ theo thứ tự ngược, nên một chuỗi đổi tên (<code>a→b</code>, <code>b→c</code>) được hoàn tác mà không tự đụng độ.","changelog.51f9c128a973":"<em>Ngoại lệ được ghi trong tài liệu:</em> các lần xóa được ghi vào lịch sử nhưng không có hoàn tác. Freally xóa vào thùng rác của hệ điều hành, và API khôi phục đa nền tảng duy nhất (<code>trash::os_limited</code>) được cài đặt cho Windows và Linux freedesktop nhưng <strong>không có cho macOS</strong>. Thay vì đưa ra một nút bấm rồi mới thất bại, một lần xóa mang theo lý do giải thích rằng khôi phục là việc của hệ điều hành. Sao chép vào thư mục và di chuyển vào thư mục không được ghi nhật ký vì chúng hiện chưa thực sự sao chép hay di chuyển gì.","changelog.c75a49fc28b8":"<strong>Hình dạng bảo mật của các lệnh phía ghi.</strong> Một lần đổi tên có đích đến, và khác với nguồn, đích đến chưa bao giờ nằm trong tập kết quả nào — nên theo quy tắc của Build 1 rằng IPC phía ghi không được nhận đường dẫn do nơi gọi chọn, frontend không bao giờ gửi đích đến. Nó gửi các đường dẫn đã chọn và <em>quy tắc</em>; backend tự suy ra mọi tên và suy ra lại lúc áp dụng thay vì tin vào bản xem trước, nên một bảng xem trước bị can thiệp không thay đổi được gì. Tên suy ra bị từ chối nếu chứa dấu phân cách đường dẫn, là <code>.</code> hoặc <code>..</code>, chứa ký tự mà không nền tảng nào chấp nhận, sẽ bị Windows lặng lẽ viết lại (một dấu chấm hoặc dấu cách ở cuối, khiến tên được áp dụng khác với tên đã duyệt), hoặc trùng với một tên thiết bị được dành riêng. Sau đó đích đến được dựng lại từ chính thư mục cha của nguồn.","changelog.b2289135440f":"<strong>Kiểm thử.</strong> <code>tests/smoke/build_02_index_health.rs</code>, <code>build_02_volume_catalogs.rs</code> và <code>build_02_rename_undo.rs</code> canh giữ các phần mới theo cách không phụ thuộc hệ điều hành; các bài kiểm thử đơn vị bao quát bộ máy đổi tên, nhật ký thao tác, các quy tắc của trình tư vấn, việc gộp sự kiện, việc tính độ trễ, bản đồ ổ đĩa và sổ đăng ký danh mục. <code>apps/freally-ui/tests/unit/build_02.test.ts</code> bao quát phần nối dây ở frontend.","changelog.b1d319c1818b":"<strong>i18n.</strong> 68 khóa mới trên cả 18 ngôn ngữ (tổng cộng 782); <code>xtask i18n-lint</code> xanh.","changelog.7d87f19cc769":"<code>volume:</code> là công cụ sửa đổi chỉ Freally có, nên nó bị từ chối trong chế độ strict-Everything cùng với <code>similar:</code> và họ âm thanh.","changelog.7df7bfeaffe7":"<code>freally-journal</code> cung cấp một <code>JournalPosition</code> không phụ thuộc hệ điều hành (<code>generation</code> + <code>offset</code>) trên cả ba bộ đăng ký theo dõi, để daemon phát hiện được một luồng thay đổi đã quay vòng hoặc được tạo lại mà không cần biết kiểu con trỏ của từng hệ điều hành.","changelog.f787e991d5ac":"Những thiếu sót đã biết","changelog.cea8b98efa00":"<code>auto_remove_offline</code> vẫn không làm gì. Hiện thực hóa nó theo nghĩa đen đồng nghĩa với việc xóa các hàng của một thiết bị ngoại tuyến khỏi chỉ mục; điều đó mang tính phá hủy, nằm ngoài phạm vi của SRC-M14, và giá trị mặc định <code>true</code> của nó lẽ ra đã lặng lẽ áp dụng cho mọi bản cài đặt hiện có. Giữ lại mới là điều tính năng này muốn, và cũng là điều daemon vốn đã làm.","changelog.8d7633d7bfb2":"Bốn công tắc chế độ khớp có sẵn (chữ hoa/thường, toàn bộ từ, đường dẫn, dấu thanh) vẫn chỉ có tác dụng ở giao diện — daemon dựng <code>ExecOpts::default()</code> và chỉ cờ phiên âm của SRC-M12 được truyền qua kênh truyền. Vấn đề này có từ trước Build 2; nối dây cho chúng sẽ thay đổi kết quả của các truy vấn hiện có.","changelog.6faa3e79208e":"[0.21.0] — Build 1 · Cổng ổn định Must-Have, phần 1 trên 3 (2026-07-31)","changelog.d178abfc569c":"Bản đầu tiên trong ba bản dựng Must-Have: SRC-M01 … SRC-M08. Đa nền tảng trừ khi có ghi chú riêng cho từng hệ điều hành. Tài liệu đầy đủ về tính năng nằm trong <code>docs/documentation.html</code>.","changelog.8290eb7e3829":"<strong>SRC-M01 — trình xem nội dung có kết quả khớp trong ngữ cảnh.</strong> Một khung xem toàn bộ tài liệu cho mọi tệp mà đường ống trích xuất đọc được: mọi chỗ khớp được tô sáng, dòng có đánh số, một nhãn đếm số chỗ khớp, <code>F3</code> / <code>Shift+F3</code> để chuyển giữa các chỗ khớp, và nhảy tới chỗ khớp đầu tiên khi mở. Mở được từ menu chuột phải mới của kết quả. Các từ được tô sáng là các thành phần nguyên văn và trong ngoặc kép của truy vấn cùng mọi chip tinh chỉnh đang bật. Giới hạn ở 20,000 dòng, và có nói rõ điều đó.","changelog.90356999c878":"<strong>SRC-M02 — tìm trong kết quả.</strong> <code>Ctrl+Shift+F</code> mở một ô tìm kiếm tầng thứ hai để thu hẹp tập đang có trên màn hình thay vì chạy lại truy vấn. Mỗi cụm từ trở thành một chip có thể gỡ bỏ, nên lỡ đi quá đà chỉ tốn một cú nhấp thay vì phải gõ lại. Một cụm từ chứa dấu phân cách đường dẫn sẽ khớp với đường dẫn đầy đủ, còn không thì với tên tệp. Xuất và Chọn tất cả đọc tập đã tinh chỉnh, nên chúng không bao giờ tác động lên những hàng mà một chip đã loại ra. <em>(Sắp xếp bộ lọc chuyển sang <code>Ctrl+Shift+O</code>.)</em>","changelog.e01ea66e064f":"<strong>SRC-M03 — nhập/xuất tương thích với Everything.</strong> <code>File → Export Results…</code> chọn định dạng theo phần mở rộng được chọn trong hộp thoại lưu: <code>.efu</code>, <code>.csv</code>, <code>.txt</code>, <code>.m3u</code> / <code>.m3u8</code>, <code>.ndjson</code>, <code>.json</code>. <code>.efu</code> tương thích đến từng byte với Everything của voidtools — dòng tiêu đề nguyên văn <code>Filename,Size,Date Modified,Date Created,Attributes</code>, các dòng CRLF, dấu ngoặc kép theo RFC-4180, và tick FILETIME của Windows được chuyển đổi ở ranh giới, nên một danh sách được ghi trên Linux hay macOS vẫn nạp vào Everything trên Windows mà không cần sửa. Xuất danh sách phát chỉ mang âm thanh và cho biết đã ghi bao nhiêu hàng trên tổng số bao nhiêu. <code>File → Open File List…</code> nạp một danh sách và tìm trong đó <em>thay cho</em> chỉ mục trực tiếp — câu trả lời cho câu hỏi &quot;tệp đó nằm trên ổ nào?&quot; với một ổ đĩa đã rút ra. Việc khớp trên một danh sách đã nạp là khớp chuỗi con theo tên hoặc đường dẫn, không phải DSL.","changelog.d5c8d8b6e6ed":"<strong>SRC-M04 — Mở bằng…</strong> Liệt kê theo từng hệ điều hành những ứng dụng được đăng ký cho loại tệp của một kết quả: <code>SHAssocEnumHandlers</code> trên Windows (chính nguồn mà Explorer dùng), khớp <code>MimeType=</code> trong tệp <code>.desktop</code> với cơ sở dữ liệu MIME dùng chung trên Linux, và các loại tài liệu mà bundle khai báo cộng với <code>/usr/bin/open -a</code> trên macOS.","changelog.00c9693a1527":"<strong>SRC-M05 — các thao tác sao chép nâng cao.</strong> Sao chép <em>nội dung</em> của một tệp văn bản; sao chép chính các tệp dưới dạng đối tượng tệp trên bảng tạm của hệ điều hành (<code>CF_HDROP</code>, URL tệp của <code>NSPasteboard</code>, <code>x-special/gnome-copied-files</code>); và sao chép một lựa chọn nhiều mục thành danh sách đường dẫn theo bốn kiểu đặt ngoặc.","changelog.678cdb17b71c":"<em>Ngoại lệ theo hệ điều hành được ghi trong tài liệu:</em> Linux không có bảng tạm nội tiến trình nào sống sót sau khi tiến trình ghi thoát, nên việc sao chép đối tượng tệp cần <code>wl-clipboard</code> hoặc <code>xclip</code>, và sẽ nói rõ khi cả hai đều chưa được cài.","changelog.c00e9441825d":"<strong>SRC-M06 — terminal tại đây và lệnh tùy chỉnh.</strong> &quot;Mở terminal tại đây&quot; khởi chạy terminal của nền tảng trong thư mục của kết quả. Các lệnh do người dùng định nghĩa nằm trong <strong>Cài đặt → Chung → Lệnh tùy chỉnh</strong> với các chỗ giữ chỗ <code>{path}</code> / <code>{dir}</code> / <code>{name}</code> / <code>{stem}</code> / <code>{ext}</code> và phạm vi theo từng phần mở rộng tùy chọn. Mỗi lần thay thế trở thành một vị trí <code>argv</code>.","changelog.561fa38bf46d":"<strong>SRC-M07 — họ <code>dupe:</code> đi vào hoạt động.</strong> <code>dupe:</code> (cùng tên <em>và</em> cùng kích thước), <code>name-dupe:</code> / <code>dupe:name</code>, và <code>size-dupe:</code> / <code>dupe:size</code> giờ được thực thi thay vì bị phân tích thành <code>ModifierKind::Reserved</code>. Việc phát hiện chạy thẳng trên chỉ mục — không băm, đó là việc của SRC-N22. Các hàng khớp được gom dưới một tiêu đề nhóm. Thư mục không bao giờ vào nhóm. Giống <code>similar:</code>, họ này chỉ được đứng ở vị trí gốc.","changelog.0610973d550f":"<em>Ghi chú về Quy tắc thường trực #8:</em> <code>dupe:foo</code> trước đây phân tích được rồi thất bại lúc thực thi. Giờ nó thất bại ngay lúc <em>phân tích</em> với <code>InvalidModifierValue</code> — đúng sự nâng cấp mà các công cụ sửa đổi âm thanh nhận được ở giai đoạn 9. Không truy vấn nào từng trả về kết quả bị đổi hành vi.","changelog.761324a5cfcc":"<strong>SRC-M08 — công cụ sửa đổi về sự trống rỗng.</strong> <code>empty:</code> (đứng một mình, hoặc có phạm vi với <code>empty:file</code> / <code>empty:folder</code> / <code>empty:roots</code>), <code>child-count:</code> và <code>descendant-count:</code>, được trả lời từ dữ liệu chỉ mục mà không cần duyệt hệ thống tệp. <code>empty:roots</code> báo <em>đỉnh</em> của mỗi chuỗi thư mục không chứa tệp nào ở bất kỳ độ sâu nào; các công cụ sửa đổi đếm chỉ bao giờ khớp với thư mục. <code>freally_index::DirStats</code> mới suy ra hình dạng thư mục của chỉ mục trong một lượt duy nhất qua <code>files.db</code>, được ghi nhớ theo bộ đếm sự kiện đã áp dụng.","changelog.b3468cd50e03":"<strong>Giao diện hỗ trợ.</strong> Một menu chuột phải cho kết quả, một vùng thông báo trên cửa sổ chính, và thanh tinh chỉnh — tất cả đều với tới được bằng bàn phím.","changelog.53d34aa4b652":"<strong>Kiểm thử.</strong> <code>tests/smoke/build_01_dsl.rs</code> và <code>build_01_interop.rs</code> canh giữ hai họ công cụ sửa đổi và định dạng truyền <code>.efu</code>; các bài kiểm thử đơn vị bao quát <code>DirStats</code>, các codec, việc đặt ngoặc, việc thay chỗ giữ chỗ, phân tích <code>.desktop</code>, vị trí kết quả khớp, cổng nguồn gốc, và sự đồng bộ của các bảng giữa các crate; <code>tests/unit/build_01.test.ts</code> bao quát các kho ở frontend.","changelog.73bc8a5d676f":"<strong>i18n.</strong> 55 khóa mới trên cả 18 ngôn ngữ; <code>xtask i18n-lint</code> xanh.","changelog.f56c4fe5f08d":"<strong>[mọi nền tảng]</strong> <code>KnownPaths</code> không có ai ghi vào. Giai đoạn 12 chuyển kết quả truy vấn sang thông báo của daemon và không có gì tiếp quản việc đăng ký chúng, nên mọi thao tác tệp có canh giữ đều từ chối mọi hàng kết quả. Giờ <code>daemon.rs</code> đăng ký chúng khi <code>query:batch</code> đi qua.","changelog.fe76b18c0f5e":"<strong>[mọi nền tảng]</strong> <code>finalize_bootstrap</code> không tăng <code>applied_events</code>, nên một <code>DirStats</code> được suy ra giữa lúc quét vẫn nằm trong bộ đệm gắn với chỉ mục đã hoàn tất — khiến <code>empty:folder</code> khớp với mọi thư mục cho đến lô nhật ký tiếp theo.","changelog.83072c3967c3":"<strong>[mọi nền tảng]</strong> Một <code>dupe:</code> ở vị trí không được hỗ trợ bị lặng lẽ gỡ bỏ mỗi khi có một cái khác ở cấp cao nhất (<code>dupe:name !size-dupe:</code> trả về không kết quả nào mà không báo lỗi). Giờ bộ canh vị trí đếm số nút thay vì chỉ kiểm tra xem có vắng mặt hay không.","changelog.abf1376b827c":"<strong>[mọi nền tảng]</strong> <code>empty:roots</code> không báo gì khi toàn bộ cây được quét không có tệp nào: mỗi hàng tự tạo một mục đếm cho thư mục cha của nó, nên chính thư mục cha của gốc quét trông như đã được lập chỉ mục.","changelog.24ee98d1fa85":"<strong>[mọi nền tảng]</strong> Phủ định một vị từ mà chỉ mục tên không quyết định được (<code>!empty:file</code>, <code>!size:&gt;1mb</code>) trả về không hàng nào — quy ước &quot;cứ cho qua&quot; của tầng tên bị đảo thành từ chối dưới <code>NOT</code>. Lỗi này có từ trước; Build 1 làm nó lộ rõ.","changelog.8d60d2e391a7":"<strong>[mọi nền tảng]</strong> Trình xem kết quả khớp tìm chỗ khớp trong một <em>bản sao</em> viết thường của mỗi dòng trong khi giao diện cắt bản gốc, làm lệch mọi chỗ tô sáng trên một dòng chứa <code>İ</code>. Giờ các vị trí đánh chỉ số theo văn bản gốc, và từ cần tìm lẫn văn bản được tìm đều được chuyển chữ theo cùng một cách.","changelog.83b5581b542c":"<strong>[Linux]</strong> Một lần <code>wl-copy</code> thất bại (khi chạy dưới X11) lại báo thành công, nên &quot;Sao chép dưới dạng tệp&quot; tuyên bố đã chạy, để nguyên bảng tạm, và không bao giờ chuyển sang <code>xclip</code>.","changelog.4695c56f4771":"<strong>[Windows]</strong> Bộ canh COM gọi <code>CoUninitialize</code> ngay cả khi <code>CoInitializeEx</code> trả về <code>RPC_E_CHANGED_MODE</code> — tháo bỏ COM dưới chân bên thực sự đã khởi tạo luồng đó.","changelog.e39b26f32960":"<strong>[CI]</strong> <code>vendor/freally-central</code> (bảng Thêm ứng dụng Freally) là một submodule trỏ tới một kho không còn tồn tại, nên mọi lần chạy trên mọi hệ điều hành đều thất bại ở bước <em>checkout</em>. Giờ bảng này được đưa vào dưới dạng mã nguồn thường và cả hai quy trình đều đặt <code>submodules: false</code>, nên kho dựng được từ một bản clone mà không cần thêm gì khác.","changelog.0cb6b784b78e":"<strong>[mọi nền tảng]</strong> <code>wasmtime</code> 44.0.1 → 47.0.3 trong trình chạy trình trích xuất tùy chỉnh, khép lại <strong>RUSTSEC-2026-0222</strong> (chỉ số kiểu có thể bị lẫn giữa các engine). Chỉ chạm tới được qua một trình trích xuất WASM do người dùng cài, nhưng dù sao <code>cargo-deny</code> vẫn chặn bản dựng vì nó.","changelog.e131be0feec2":"<strong>[mọi nền tảng]</strong> Xuất và nhập danh sách tệp giờ mở hộp thoại của hệ điều hành <strong>trong Rust</strong> và làm việc với đường dẫn mà chúng đọc lại được. Cho đích đến đi qua webview đồng nghĩa với việc <code>file_list_export</code> — lệnh phía <em>ghi</em> đầu tiên của Build 1 — sẽ ghi đè lên bất kỳ đường dẫn nào frontend nêu tên, và mục đăng ký mà nó dùng để kiểm tra lại là thứ frontend tự tạo ra được. <code>KnownPaths</code> cũng có thêm một chiều <code>Provenance</code> để một quyền mà frontend với tới được không bao giờ có thể trao quyền ghi.","changelog.d1a9848c839b":"<strong>[mọi nền tảng]</strong> <code>run_custom_command</code> nhận một <strong>ID</strong> lệnh và phân giải nó theo cài đặt đã lưu của backend. Nhận trường <code>program</code> qua IPC đã biến nó thành một công cụ thực thi tiến trình tùy ý: truyền đối số qua <code>Command::arg</code> không bảo vệ được gì khi nơi gọi còn chọn cả tệp thực thi.","changelog.ed41b394f8fd":"Xem <code>docs/SECURITY.md</code> để biết toàn bộ phần thay đổi trong mô hình mối đe dọa.","changelog.c99d8fed1d7c":"[0.20.1] — 2026-07-10","changelog.2cd4002ecd32":"Một bản vá không có tính năng mới. Nó tồn tại vì v0.20.0 không thể tự sửa mình: điểm cuối của trình cập nhật được biên dịch vào tệp nhị phân đã phát hành, nên mọi bản cài đặt đều kiểm tra một kho không tồn tại và sẽ không bao giờ được đề nghị cập nhật. Đây là bản dựng sửa điều đó, và nó mang theo các bản nâng cấp bảo mật ra đời sau v0.20.0.","changelog.4bffda6c3827":"<strong>[mọi nền tảng]</strong> <code>quick-xml</code> 0.39.4 → 0.41.0, khép lại <strong>RUSTSEC-2026-0194</strong> (thời gian chạy bậc hai khi kiểm tra một thẻ mở có tên thuộc tính trùng lặp) và <strong>RUSTSEC-2026-0195</strong> (cấp phát khai báo không gian tên không giới hạn trong <code>NsReader</code>, một kiểu từ chối dịch vụ do cạn bộ nhớ). Cả hai đều chạm tới được: các trình trích xuất docx và pptx trong <code>freally-extractors</code> đưa XML Office không đáng tin thẳng vào <code>quick_xml::Reader</code>. Một tài liệu độc hại có thể làm trình chạy trình trích xuất bị treo hoặc cạn tài nguyên. Giấy phép không đổi (MIT).","changelog.68001f921152":"<strong>[mọi nền tảng]</strong> <code>calamine</code> 0.34.0 → 0.36.0 — bản phát hành đầu tiên chấp nhận <code>quick-xml ^0.41</code>, nên đây là điều kiện cần cho thay đổi ở trên chứ không phải một thay đổi riêng. Giấy phép không đổi (MIT). Phụ thuộc gián tiếp <code>zip</code> của nó lên từ 7 → 8; <code>zip</code> của chính workspace vẫn được ghim ở 5.","changelog.d7a4cb594270":"<strong>[mọi nền tảng]</strong> <code>crossbeam-epoch</code> 0.9.18 → 0.9.20, khép lại <strong>RUSTSEC-2026-0204</strong> (giải tham chiếu con trỏ không hợp lệ trong impl <code>fmt::Pointer</code> cho <code>Atomic</code> và <code>Shared</code> khi con trỏ bên dưới không hợp lệ). Phụ thuộc gián tiếp và tương thích semver. Giấy phép không đổi (MIT OR Apache-2.0).","changelog.4aabc8b9de68":"Cả ba đều được sửa bằng cách nâng cấp. Không có cảnh báo nào được thêm vào danh sách bỏ qua của <code>deny.toml</code>.","changelog.6fd7a68afb1a":"<strong>[mọi nền tảng]</strong> Trình cập nhật tự động giờ trỏ tới đúng kho mà dự án này thực sự nằm trong đó. <code>tauri.conf.json</code> ghi <code>MikesRuthless12/Freally</code>, một kho không tồn tại, nên <code>latest.json</code> trả về 404 và <strong>cập nhật tự động chưa từng hoạt động ở bất kỳ bản dựng nào đã phát hành</strong>. Vì điểm cuối được nhúng cứng vào tệp nhị phân, v0.19.84 và v0.20.0 vẫn tiếp tục thăm dò URL đã chết; chỉ những bản cài đặt từ bản phát hành này trở về sau mới tìm thấy bản cập nhật.","changelog.4a77c5b010f4":"[0.20.0] — 2026-07-01","changelog.ff6c265c78c6":"Không có ghi chú nào được viết cho bản phát hành này. Những gì nó thay đổi chỉ có thể truy lại từ dải commit giữa <code>v0.19.84</code> và <code>v0.20.0</code>; ở đây nó được ghi là bị khuyết thay vì được dựng lại, vì một bản tóm tắt nghe có lý được viết năm tháng sau chỉ là một phỏng đoán khoác cùng định dạng với một sự thật. Điều duy nhất biết chắc về nó nằm trong <code>[0.20.1]</code> bên dưới: điểm cuối trình cập nhật của nó nêu tên một kho không tồn tại, và nó không thể tự sửa mình.","changelog.08f47e2a7fbb":"[0.19.84] — Giai đoạn 0–12 · bản dựng công khai đầu tiên (2026-06-21)","changelog.abfb5e516e09":"Những ghi chú này đã nằm dưới <code>## [Unreleased]</code> từ 2026-05-11 đến 2026-08-21, qua năm bản phát hành có gắn thẻ. Chúng không phải công việc chưa phát hành và chưa bao giờ là như vậy — mục của giai đoạn 0 bên dưới kết thúc bằng câu &quot;Thẻ công khai đầu tiên sẽ là <strong>v0.19.84</strong>&quot;, và đó chính là điều mục này ghi lại. Thẻ được tạo vào 2026-06-21 mà không ai đổi tên tiêu đề, và mọi bản phát hành sau đó đều thừa hưởng cùng một khối.","changelog.c8dfea56f286":"Đó là một mối nguy thật sự, không phải chuyện cẩu thả. Quy trình phát hành dựng phần ghi chú được công bố bằng cách đổi tên <code>## [Unreleased]</code> thành phiên bản đang được phát hành, nên bản phát hành tiếp theo lẽ ra đã đưa ra 533 dòng công việc của giai đoạn 0–12 — đã năm tháng tuổi, đã có trong mọi bản cài đặt — như thể chúng là mới. Mục này được ghi ngày theo thẻ mà nó được phát hành cùng, thay vì bị chia ra giữa <code>v0.19.84</code> và <code>v0.20.0</code>, vì mọi mục trong đó đều có trước cả hai.","changelog.0fadecb7f2fe":"&gt; Mọi thứ bên dưới đều có trước các bản phát hành của Build 1–3 và chưa bao giờ được đưa vào một mục phiên bản. Chúng được để nguyên ở đây thay vì được xếp ngược vào <code>0.21.0</code>–<code>0.23.0</code> theo phỏng đoán; việc phân loại chúng là một đợt riêng.","changelog.f1873f116239":"TASK-098 — i18n Fluent đầy đủ từ đầu đến cuối trên cả 18 ngôn ngữ (2026-05-11)","changelog.495b18f2f513":"Trình nạp Fluent cho 18 ngôn ngữ giờ đã được nối dây. Đổi ngôn ngữ trong Cài đặt → Ngôn ngữ (hoặc trong trình hướng dẫn lần chạy đầu) sẽ hiển thị lại mọi chuỗi đã dịch trong giao diện — menu, thanh trạng thái, các bảng cài đặt, hộp thoại và trình hướng dẫn — mà không cần khởi động lại.","changelog.78760917c35b":"<strong>Trình nạp.</strong>","changelog.5f1a08de08be":"<code>apps/freally-ui/src/lib/i18n/bundle.ts</code> thay chuỗi nội tuyến <code>EN_FTL</code> của giai đoạn 11 bằng <code>import.meta.glob(&quot;../../../../../locales/*/freally.ftl&quot;, { query: &quot;?raw&quot;, eager: true })</code>. Cả 18 tệp <code>.ftl</code> được nhúng vào lúc dựng; mỗi <code>FluentBundle</code> đặt <code>en</code> bên dưới làm tài nguyên dự phòng, để một khóa lẻ bị thiếu hiện ra bằng tiếng Anh thay vì dưới dạng chuỗi khóa thô.","changelog.a9d6f49ee814":"<code>vite.config.ts</code> mở rộng <code>server.fs.allow</code> tới gốc của workspace để chế độ dev đọc được cây ngôn ngữ nằm ngoài gốc của gói.","changelog.d354155cedc1":"<code>bundle.ts</code> xuất <code>loadedLocales()</code> để bộ kiểm thử khẳng định rằng glob thực sự đã lấy đủ cả 18 tệp.","changelog.50aa545a0dff":"<strong>Dữ liệu bản dịch — đồng bộ theo Quy tắc thường trực #4.</strong>","changelog.c8b21089e4f2":"<code>en/freally.ftl</code> tăng từ 314 lên 557 khóa. 243 khóa thêm vào bao quát phần hoàn thiện trình hướng dẫn (gợi ý, chỗ giữ chỗ, &quot;Bước N trên N&quot;), các phân đoạn của thanh trạng thái, chuỗi cho ống kính / xem trước / dấu trang, các hộp thoại Giới thiệu / Kết nối, mọi gợi ý bảng + tiêu đề mục + thông báo của các bảng Giao diện/Trang chủ/Sao lưu/Bàn phím/Lịch sử/Ngôn ngữ/Thư mục/Ổ đĩa, và toàn bộ thanh menu theo PRD §8.28 (mọi nhãn của Tệp/Chỉnh sửa/Xem/Tìm kiếm/Dấu trang/Công cụ/Trợ giúp + mọi tiêu đề menu con + mọi gợi ý khi di chuột).","changelog.8f7a7778b776":"Cùng 243 khóa đó được phản chiếu song song sang cả 17 ngôn ngữ còn lại (es, de, fr, it, nl, pl, pt-BR, tr, vi, id, ru, uk, ar, hi, ja, ko, zh-CN). Mọi tệp <code>.ftl</code> giờ phân giải cùng 557 khóa; bài kiểm thử đồng bộ mới <code>tests/unit/i18n.test.ts</code> khẳng định điều này ở mỗi lần chạy CI.","changelog.3b3366de3c39":"<strong>Chuyển đổi thành phần.</strong>","changelog.c65098e5c147":"<code>menu_spec.ts</code> có thêm khóa <code>l10n</code> trên mọi <code>MenuItemSpec</code> và <code>MenuSubmenu</code>, cộng với <code>hintL10n</code> cho gợi ý khi di chuột trên thanh trạng thái. <code>MenuBar.svelte</code> phân giải chúng qua các hàm trợ giúp <code>labelOf(spec)</code> / <code>hintOf(spec)</code>, vốn quay về <code>label</code>/<code>hint</code> nguyên văn khi không có khóa dịch.","changelog.ef3a0f5b03d9":"FirstRunWizard hiển thị tiêu đề, số bước, tiêu đề + gợi ý của từng bước, các thẻ giao diện, và các nút Quay lại/Tiếp/Hoàn tất qua <code>t()</code>. Bước phím tắt đã bị bỏ trong đợt chỉnh trình hướng dẫn trước đó; cấu hình phím tắt vẫn nằm trong Cài đặt → Bàn phím.","changelog.4124e2c07aee":"StatusBar dùng <code>t()</code> cho phân đoạn pha chỉ mục (&quot;Đã lập chỉ mục (N tệp)&quot; / &quot;Đang lập chỉ mục… N/M&quot; / &quot;Tạm dừng&quot; / &quot;Lỗi&quot;), cách chia số nhiều cho số lượng kết quả (<code>status-result-count-one</code> so với <code>…-many</code>), nhãn kích thước của lựa chọn, thời gian truy vấn, nhãn thời gian theo ống kính, và phân đoạn CSDL cục bộ / điểm cuối từ xa. <code>aria-label</code> của nút xoay vòng giao diện và gợi ý khi di chuột của phím tắt giờ đều dịch được.","changelog.a3b5fe09b103":"Hộp thoại cài đặt — <code>SettingsDialog.svelte</code>, <code>SettingsTreeNav.svelte</code>, <code>SettingsButtonBar.svelte</code>, <code>LocalePanel.svelte</code>, cộng các bảng trong nhóm Chỉ mục, Ống kính, Mạng và Khác (Giao diện / Trang chủ / Tìm kiếm / Kết quả / Xem / Menu ngữ cảnh / Phông chữ &amp; Màu sắc / Bàn phím / Chỉ mục cấp cao nhất / Ổ đĩa / Thư mục / Danh sách tệp / Loại trừ / Tên tệp / Nội dung / Âm thanh / Độ tương đồng / Tùy chỉnh / HTTPS / ETP / Lịch sử / Quyền riêng tư / Nhật ký / Sao lưu / Giới thiệu).","changelog.f3afe9f2e294":"Dấu trang, khung xem trước, và các điều khiển trạng thái trống / thu gọn của <code>LensSection</code>.","changelog.7ad5ec734228":"<strong>RTL giờ là tự động, không phải một ô đánh dấu.</strong>","changelog.adaca56bf336":"Ô đánh dấu &quot;Xem trước RTL&quot; trong Cài đặt → Ngôn ngữ đã bị bỏ. RTL được áp dụng tự động cho những ngôn ngữ có hệ chữ viết từ phải sang trái — hiện <code>ar</code> là ngôn ngữ phát hành duy nhất thuộc nhóm đó. <code>applyRtlForLocale</code> tra danh sách cho phép nội bộ <code>RTL_LOCALES</code> của nó; trường <code>locale_settings.rtl_preview</code> của <code>bootstrap.ts</code> vẫn nằm trong trạng thái được lưu để tương thích ngược, nhưng giao diện không còn hiển thị nó.","changelog.b2a93dfa6039":"<strong>Kiểm thử.</strong>","changelog.cd3c3612b144":"<code>tests/unit/i18n.test.ts</code> mới bao quát: (a) glob thực sự đã nạp đủ 18 ngôn ngữ, (b) <code>bundleFor(code)</code> trả về một bundle phân giải được một khóa kiểm chứng cho mọi ngôn ngữ, (c) 18 ngôn ngữ đồng bộ hoàn toàn về tập khóa, (d) đổi <code>settingsStore.state.locale</code> sẽ thay đổi những gì <code>t()</code> trả về, (e) một ngôn ngữ không xác định quay về qua <code>en</code> thay vì chuỗi khóa thô, (f) một khóa không xác định trả về chính khóa đó.","changelog.82baaedc9013":"Đợt hoàn thiện giai đoạn 12 — trải nghiệm, độ tin cậy và áp dụng trực tiếp (2026-05-11)","changelog.2907b565b163":"Một đợt chỉnh sửa hành vi lớn trong một buổi gỡ lỗi dài. Phần lớn các bản sửa là những bước tiến thẳng tới sự tương đương với voidtools-Everything, cộng với công việc nền tảng về độ tin cậy giúp ứng dụng máy tính dễ chịu khi chạy đi chạy lại trong quá trình phát triển.","changelog.f8b766536c97":"<strong>Một phiên bản duy nhất + khởi động daemon không chặn.</strong>","changelog.e7d0360bc90d":"<code>kill_other_freally_instances()</code> chạy ở đầu <code>run()</code> trên Windows (taskkill <code>/F /T</code> với <code>freally-ui.exe</code> + <code>freally-indexd.exe</code>, lọc các PID ≠ chính nó) để khởi chạy lại ứng dụng luôn bắt đầu từ trạng thái sạch mà không phải tự tay tắt tiến trình. Có hàm giữ chỗ trên macOS / Linux cho tương đương.","changelog.a731267547b9":"<code>Daemon::boot</code> giờ tạo một luồng riêng <code>freally-daemon-boot</code> bên trong <code>tauri::Builder::setup</code>; hook thiết lập trả về ngay và cửa sổ xuất hiện tức thì. Trước đây việc phát lại kho chuẩn có thể chặn luồng GUI trong 10-15 s, kích hoạt cơ chế canh cửa sổ không phản hồi của Windows và đánh sập tiến trình trước khi có bất kỳ HWND nào.","changelog.59d90e38c9ea":"<code>Client::connect</code> được bọc trong một vòng thử lại 500 × 40 ms ở phía tiêu thụ, để một lần khởi động daemon chậm không thua một cuộc chạy đua kết nối đơn lẻ.","changelog.2f85875a08d3":"<strong>Chip bộ lọc + menu Tìm kiếm — chọn nhiều với phép kết hợp OR.</strong>","changelog.9f34cca2f956":"<code>lib/stores/type_filter.svelte.ts</code> mới giữ một <code>Set&lt;TypeFilterId&gt;</code>; mặc định là toàn bộ tập (chế độ Everything). <code>toQueryFragment()</code> tạo ra một nhóm ở cấp trình phân tích <code>(audio: OR video: OR …)</code> cho lựa chọn một phần, và chuỗi rỗng cho &quot;tất cả&quot; hoặc &quot;không gì cả&quot;, nên cái bẫy AND-của-tiền-tố ở phía daemon đã biến mất.","changelog.8adb4f889882":"Các chip của <code>QuickFiltersPalette.svelte</code> bật tắt trực tiếp kho; các mục menu trong <code>Search → …</code> chuyển từ <code>radio</code> sang <code>checkable</code>, với <code>MenuBar.isItemChecked</code> đọc kho. &quot;Everything&quot; được suy ra từ <code>selected.size === ALL.length</code> — nhấp vào bất kỳ chip riêng lẻ nào sẽ tắt cả chip đó lẫn Everything, và giữ nguyên các chip khác.","changelog.5246ff18704a":"<code>bookmarks.add</code> lưu tập bộ lọc đang bật cùng với văn bản tìm kiếm; DTO <code>Bookmark</code> bên Rust có thêm <code>filters: Vec&lt;String&gt;</code> với <code>#[serde(default)]</code> để các tệp <code>bookmarks.json</code> hiện có vẫn giải tuần tự được. Nhấp vào một dấu trang khôi phục cả nội dung ô văn bản (qua <code>queryStore.setSource</code>) lẫn lựa chọn chip (qua <code>typeFilterStore.setFromIds</code>).","changelog.942a0601c778":"Sửa token của Tệp nén: <code>compressed: &quot;zip:&quot;</code> → <code>&quot;archive:&quot;</code> (bí danh thật của <code>QuickFilter::Archive</code> trong <code>freally-query::quick_filters</code>). <code>zip:</code> cũ chỉ là một phần mở rộng trong nhóm, nên Tệp nén chưa từng khớp với gì.","changelog.6de9bf011469":"<strong>Truy vấn Everything ban đầu + tương đương chế độ Everything.</strong>","changelog.29e61abbcb91":"<code>runInitialEverythingQuery()</code> trong <code>bootstrap.ts</code> chạy một lần sau khi nạp dữ liệu và thăm dò <code>resultsStore.batches.length</code> trong tối đa 60 × 800 ms, chỉ khởi chạy các lệnh gọi <code>run()</code> mới khi không có gì đang chạy, để việc tự kích hoạt không hủy chính các truy vấn của nó. Khung hình đầu tiên sau khi khởi chạy hiện kết quả ngay thay vì &quot;Nhập truy vấn để bắt đầu.&quot;","changelog.c323e4a1d454":"Khi toàn bộ tập bộ lọc loại tệp được chọn và ô tìm kiếm trống, <code>resultsStore.run()</code> dựng một ký tự đại diện <code>*</code> trơn để ống kính tên tệp liệt kê mọi mục đã lập chỉ mục (tương đương voidtools-Everything).","changelog.2c27ce8face6":"Điều kiện hiển thị chỗ giữ chỗ của <code>ResultList.svelte</code> được cập nhật: chỉ hiện &quot;Nhập truy vấn để bắt đầu&quot; khi nguồn trống VÀ không có bộ lọc loại tệp nào được chọn (tức là người dùng đã chủ động bỏ chọn mọi chip).","changelog.28ad0f2414d6":"<strong>Lập chỉ mục thư mục.</strong>","changelog.c21ab8d7106b":"<code>crates/freally-indexd/src/scanner.rs::scan_folder</code> giờ lập chỉ mục thư mục cùng với tệp; nhánh walkdir lọc theo <code>is_file() || is_dir()</code> và đóng dấu <code>FILE_ATTRIBUTE_DIRECTORY (0x10)</code> vào trường <code>attrs</code> của sự kiện nhật ký.","changelog.799bfffa54d6":"Nhánh khởi tạo MFT trong <code>crates/freally-journal-win/src/subscriber.rs</code> không còn bỏ qua bản ghi thư mục — chúng đi qua với nguyên vẹn mặt nạ bit <code>file_attributes</code> thật của mình.","changelog.709c7429febd":"<code>QueryHit</code> (DTO Rust + interface TS tương ứng) có thêm trường <code>attrs: u32 #[serde(default)]</code> mà daemon điền từ <code>FileRow.attrs</code>. Giao diện phân biệt tệp với thư mục qua bit <code>0x10</code>.","changelog.694ce7c4310f":"<strong>Biểu tượng shell Windows thật + hiển thị theo từng hàng.</strong>","changelog.4479cd257069":"<code>apps/freally-ui/src-tauri/src/commands/icons.rs</code> mới — lệnh Tauri bất đồng bộ <code>icon_for_ext(ext, is_dir) -&gt; Option&lt;String&gt;</code>, chạy <code>SHGetFileInfoW</code> của Win32 với <code>SHGFI_USEFILEATTRIBUTES</code> (để một đường dẫn giả như <code>_.xml</code> phân giải được biểu tượng của trình xử lý đã đăng ký mà không cần tệp đó thực sự tồn tại trên đĩa) → <code>GetIconInfo</code> → BGRA 32-bit qua <code>GetDIBits</code> → hoán đổi kênh BGRA→RGBA → PNG qua crate <code>image</code> → data URL base64. Hiện trả về <code>None</code> trên macOS / Linux.","changelog.6794e87b4eb5":"<code>src-tauri/Cargo.toml</code>: thêm <code>image = &quot;0.25&quot; --no-default-features --features png</code>, <code>base64 = &quot;0.22&quot;</code>, và tập tính năng liên quan của <code>windows = &quot;0.59&quot;</code> dưới <code>cfg(windows)</code>.","changelog.9e73805e7e38":"<code>lib/stores/icon_store.svelte.ts</code> mới — bộ đệm <code>Map&lt;(ext, is_dir), Promise&lt;dataUrl | null&gt;&gt;</code> để 200 hàng kết quả chỉ gọi IPC một lần cho mỗi phần mở rộng khác nhau, không phải cho mỗi hàng. Một trường phản ứng <code>tick</code> tăng lên sau mỗi lần phân giải để các nơi dùng $derived hiển thị lại.","changelog.872e5a605907":"Cột Tên của <code>ResultRow.svelte</code> hiển thị <code>&lt;img class=&quot;row-icon&quot; src=…&gt;</code> lấy từ <code>iconStore.get(hit.ext, isDir)</code>, với emoji dự phòng (<code>📁</code> / <code>📄</code>) trong lúc data URL đang tải.","changelog.eb2ed58a295d":"<strong>Siêu dữ liệu thật khi khởi tạo từ MFT.</strong>","changelog.392710a87044":"Bản ghi USN mang FRN + attrs + một dấu thời gian nhưng không có kích thước tệp, nên lối tắt nhanh qua MFT trước đây ghi <code>size: 0</code> và một dấu thời gian chỉ lấy từ USN vào chỉ mục. Giờ <code>subscriber.rs</code> gọi <code>std::fs::metadata(&amp;full)</code> cho mỗi sự kiện phát ra để điền <code>len</code>, <code>modified</code>, <code>created</code> thật. Chậm hơn duyệt USN thuần túy nhưng đúng — cột Kích thước và Ngày sửa đổi cuối cùng cũng hiển thị giá trị khác không mà không buộc phải lùi về walkdir.","changelog.693e07211105":"<strong>Hình thức của ô tìm kiếm + hàng kết quả.</strong>","changelog.660ce86cdba0":"<code>SearchBar.svelte</code> giờ gắn <code>&lt;input value={queryStore.source}&gt;</code>, để các cập nhật bằng mã (nhấp dấu trang, xóa bằng Esc, deep link sau này) phản ánh vào ô văn bản. Cũng bỏ <code>color: transparent</code> bị lỗi trên <code>.raw</code> (lớp tô sáng cú pháp &quot;gương&quot; không thẳng hàng, nên văn bản đã gõ gần như vô hình ở chế độ tối) — giờ ô nhập tự hiển thị văn bản của nó và lớp gương bị ẩn đi.","changelog.40ca8d425ec9":"CSS hàng của <code>ResultRow.svelte</code> đọc <code>--row-{state}-fg/bg/weight/style</code> để các điều khiển theo trạng thái của bảng Phông chữ &amp; Màu sắc có hiệu lực ngay. Các trạng thái đã nối dây: thường, tô sáng (di chuột), đã chọn, đã chọn và tô sáng.","changelog.5442f7a05dd7":"Sửa lỗi độ ưu tiên giữa màu hàng xen kẽ + di chuột, khiến một hàng đã chọn trông như chưa chọn khi quy tắc <code>:nth-child(even)</code> của nó mạnh hơn <code>.row.selected</code>. Giờ cả hai bộ chọn đều có <code>:not(.selected)</code> để hàng đã chọn giữ sắc xanh lơ bất kể chỉ số hay việc di chuột.","changelog.1e3c5fb60489":"<strong>Phông chữ &amp; Màu sắc: áp dụng trực tiếp + lưu lại.</strong>","changelog.99c1c70df3e3":"<code>lib/stores/fonts_apply.svelte.ts::applyFontsAndColors()</code> mới ghi các CSS custom property lên <code>&lt;html&gt;</code> từ <code>settings.fonts_and_colors</code>: <code>--font-ui</code> (kèm chuỗi dự phòng cho mọi hệ điều hành), <code>--app-font-size</code>, <code>--row-…-fg/bg/weight/style</code> theo từng trạng thái, và các giá trị ghi đè <code>--lens-…</code> theo từng ống kính. Được gọi một lần khi khởi tạo (sau khi nạp dữ liệu) và lại sau mỗi bản vá của bảng — khôi phục qua các lần khởi chạy và áp dụng trực tiếp khi thay đổi.","changelog.bd2af6cb049b":"Ô nhập phông chữ của <code>FontsAndColorsPanel.svelte</code> được đổi thành danh sách thả xuống <code>&lt;select&gt;</code> được điền qua <code>window.queryLocalFonts()</code> (Local Font Access API mà runtime WebView2 của Tauri 2 trên Windows hỗ trợ), với danh sách dự phòng gồm 25 họ phông được chọn lọc cho các webview không dựa trên Chromium. Mỗi lựa chọn được hiển thị bằng chính phông của nó để xem trước trực quan.","changelog.0f1775f6dcaa":"Danh sách thả xuống Giao diện trong UIPanel gọi <code>themeStore.set(value)</code> cùng với bản vá cài đặt, để việc chuyển sáng/tối có hiệu lực ngay khi chọn — không cần Áp dụng hay khởi động lại.","changelog.e689bf04af40":"<strong>Các công tắc của bảng Xem đã được nối dây.</strong>","changelog.af26fe7a3745":"$effect của App.svelte phản chiếu các cài đặt được chọn sang thuộc tính <code>&lt;body data-*&gt;</code>; các quy tắc CSS mới trong <code>app.css</code> phản ứng theo chúng: <code>data-alternate-rows</code>, <code>data-row-mouseover</code> (vô hiệu hóa <code>.row:hover</code> khi là false), <code>data-show-tooltips</code>, <code>data-show-lufs-badges</code>, <code>data-show-similarity-score</code>.","changelog.ba63c32bf658":"<code>title={hit.path}</code> của hàng <code>ResultRow</code> phụ thuộc vào cài đặt Hiện chú giải công cụ.","changelog.be551e42463a":"<code>formatBytes</code> tuân theo cài đặt Định dạng kích thước (<code>auto_binary</code> | <code>bytes</code> | <code>kb</code> | <code>mb</code> | <code>gb</code>).","changelog.eb09c95dc5e6":"<strong>Điều khiển cửa sổ — luôn ở trên cùng, kích thước, thu phóng.</strong>","changelog.f6f1716eda05":"<code>capabilities/default.json</code> thêm các quyền còn thiếu <code>core:window:allow-set-size</code>, <code>core:window:allow-set-always-on-top</code>, <code>core:window:allow-set-resizable</code>, <code>core:window:allow-inner-size</code>, <code>core:window:allow-outer-size</code>. Không có chúng, mọi lệnh gọi <code>setSize</code> / <code>setAlwaysOnTop</code> đều bị cổng quyền IPC của Tauri lặng lẽ từ chối.","changelog.b60bdf35fa6a":"App.svelte có thêm một <code>$effect</code> chuyển <code>settings.on_top</code> + <code>queryStore.source</code> thành các lệnh gọi <code>setAlwaysOnTop(...)</code>: các chế độ Không bao giờ / Luôn luôn / Khi đang tìm đều hoạt động, được áp dụng lại sau mỗi thay đổi cài đặt và mỗi phím gõ. Được khôi phục khi khởi chạy.","changelog.1f927e0b3720":"Sửa phần import <code>setWindowSize</code>: <code>LogicalSize</code> đến từ <code>@tauri-apps/api/window</code>, không phải từ <code>@tauri-apps/api/dpi</code> vốn không tồn tại. Kích thước được chọn cũng ghi <code>settings.window_size = { w, h }</code> (đã được cho phép trong <code>ALLOWED_PATCH_KEYS</code>), và bước khởi tạo khôi phục kích thước đã lưu ở lần khởi chạy sau.","changelog.293b3c2deb7d":"<code>zoomStore</code> chuyển từ <code>document.documentElement.style.fontSize</code> sang thuộc tính CSS <code>zoom</code> của WebView để Ctrl+= / Ctrl+- thực sự thay đổi tỷ lệ giao diện (vốn tính theo px). Sắc nét ở mọi mức.","changelog.7e52e273d7e8":"<strong>Xem trước hình ảnh.</strong>","changelog.6aa7a3ed566b":"<code>preview/windows_host.rs::preview</code> trả về data URL hình ảnh thật cho PNG, JPG/JPEG/JFIF, GIF, WEBP, BMP, SVG, ICO, AVIF: đọc tệp (giới hạn 4 MiB), mã hóa qua <code>commands::files::base64_encode</code>, rồi trả về <code>PreviewPayload { kind: Image, data_url: &quot;data:image/…;base64,…&quot; }</code>. Các phần mở rộng không phải hình ảnh vẫn trả về <code>None</code> để nhánh dự phòng đọc phần đầu văn bản xử lý các tệp văn bản.","changelog.d2769be53d10":"<code>files_preview</code>, <code>files_thumbnail</code> và <code>icon_for_ext</code> giờ là <code>async fn</code> và chuyển phần việc thực sự sang <code>tokio::task::spawn_blocking</code>. Các phiên bản đồng bộ trước đây chặn luồng điều phối IPC của Tauri trong nhiều giây khi trích xuất biểu tượng shell + mã hóa base64 nhiều MB, làm đơ toàn bộ giao diện.","changelog.2e8adf41da90":"Sửa lỗi <code>PreviewPane.svelte</code> gọi tới <code>files.whitelistUserChosen</code> không tồn tại — hàm hỗ trợ nằm trong <code>ipc/bookmarks.ts</code> nhưng khung xem trước lại import <code>* as files from &quot;ipc/files&quot;</code>. Đã xuất lại <code>whitelistUserChosen</code> từ <code>ipc/files.ts</code> để lời gọi được phân giải; <code>TypeError</code> đồng bộ khiến <code>loading = true</code> mãi mãi và chặn $effect của phần xem trước.","changelog.932173fca555":"Thêm tracing của Rust trên các đường xử lý xem trước / biểu tượng, cùng lệnh Tauri <code>log_event</code> để chuyển các sự kiện console của TS vào log phát triển của cargo, và một <code>std::panic::set_hook</code> đưa các panic của Rust ra console.","changelog.6ef1e2ccf454":"<strong>Điểm cuối FTP + nút Ngắt kết nối bị làm mờ.</strong>","changelog.5b6f4670d959":"<code>ConnectEndpointDialog.svelte</code> mới, mô phỏng theo hộp thoại của voidtools: Máy chủ (bắt buộc), Cổng (mặc định 21), Tên người dùng, Mật khẩu, danh sách thả xuống Loại liên kết. Khi nhấn OK, ghi <code>settings.endpoint = { name: host, kind: &quot;ftp&quot; }</code>.","changelog.93d8e6c9ea7d":"<code>MenuBar.isItemEnabled</code> trả về <code>false</code> cho <code>tools.disconnect_endpoint</code> khi <code>settings.endpoint.kind === &quot;local&quot;</code>; CSS thêm kiểu làm mờ <code>.item.disabled</code> với <code>pointer-events: none</code>.","changelog.dc6508212cbc":"<code>View → Filters</code> giờ chọn sẵn bảng <code>indexes.exclude</code> trước khi mở hộp thoại cài đặt (giống Everything của voidtools).","changelog.8886320c4765":"<strong>Loại trừ — các lớp phần mở rộng bật/tắt được + khử trùng lặp.</strong>","changelog.66be911445f7":"Các nút lớp phần mở rộng của <code>ExcludePanel.svelte</code> (Video / Âm thanh / Hình ảnh / Tệp nén / Tệp thực thi) giờ hoạt động như công tắc: nhấp một lần sẽ thêm các glob của lớp đó và làm nổi bật nút; nhấp lần nữa sẽ gỡ chúng và bỏ nổi bật. Trạng thái “đang bật” được tính là “mọi glob của lớp hiện đều có trong tập tệp bị loại trừ”, để phần nổi bật phản ánh trạng thái thật chứ không chỉ lần nhấp gần nhất.","changelog.b4936ee1d7c7":"<code>Add Folder…</code> và <code>Apply OS-recommended excludes</code> đều khử trùng lặp, nên cùng một mục không bao giờ bị thêm hai lần.","changelog.fd67542ffabe":"<strong>Độ tin cậy của dấu trang.</strong>","changelog.07a8ba50f22e":"<code>bookmarks.add</code> không còn đòi hỏi truy vấn khác rỗng — cho phép dấu trang với truy vấn rỗng (đặt tên “Dấu trang N” để người dùng có thể đổi tên trong Sắp xếp). Khóa khử trùng lặp giờ là (tên, truy vấn, tập bộ lọc).","changelog.eccef664591a":"<code>bookmarksStore.hydrate()</code> thử lại mỗi 500 ms trong tối đa ~10 s, để lần hydrate đầu tiên không làm mất danh sách dấu trang vì lỗi IPC daemon chưa sẵn sàng trong lúc khởi động nền.","changelog.002b1009c89f":"<code>bookmarks.organize</code> hydrate lại trước khi mở hộp thoại Sắp xếp, để một danh sách thả xuống đã cũ không thể hiện “Chưa có dấu trang nào” khi trên đĩa vẫn có dấu trang.","changelog.c399ec40a64b":"<strong>Khác.</strong>","changelog.0437b05ad147":"Bộ lọc mặc định của <code>tracing_subscriber</code> được nâng lên <code>warn,freally=info,freally_ui_lib=info,freally_indexd=info</code> để phần đo đạc xuất hiện mà không cần ép <code>RUST_LOG</code>.","changelog.64b28a5c4c3d":"<code>markDirty</code> của hộp thoại cài đặt giờ cũng gọi <code>applyFontsAndColors()</code> trong luồng vá của bảng Phông chữ &amp; Màu sắc, để phần xem trước hiện ra tức thì.","changelog.1f355d627a40":"<code>ipc/types.ts::QueryHit</code> có thêm <code>attrs?: number</code>; <code>Bookmark</code> có thêm <code>filters?: string[]</code>. Cả hai đều là tùy chọn để tương thích về sau.","changelog.3df684c915d5":"<strong>[mọi nền tảng]</strong> Giai đoạn 12: hộp thoại cài đặt + IPC thật với daemon + khung trình trích xuất tùy chỉnh + i18n. Thay lớp IPC giả lập của giai đoạn 11 bằng một kênh truyền JSON-RPC thật của <code>freally-rpc</code>, có tiền tố độ dài, chạy trên Unix socket / named pipe riêng cho từng người dùng, và đưa vào hộp thoại cài đặt đầy đủ theo PRD §8.1-§8.27 cùng máy chủ trình trích xuất tùy chỉnh chạy trong hộp cát Wasm.","changelog.cbb79fe44d28":"<strong>Crate mới <code>freally-rpc</code></strong> (trong <code>crates/freally-rpc/</code>) — nền móng cho phép cả giao diện Tauri lẫn CLI <code>freally</code> mới nói cùng một giao thức với một phiên bản <code>freally-indexd</code> duy nhất.","changelog.b4d3e8bb408c":"<code>frame.rs</code>: đóng khung có tiền tố độ dài u32-BE với giới hạn cứng 16 MiB cho phần tải, để một đối tác thù địch không thể làm máy chủ cạn bộ nhớ chỉ bằng một tiền tố độ dài 4 GiB.","changelog.9eee30718562":"<code>jsonrpc.rs</code>: các phong bì Request / Response / Notification của JSON-RPC 2.0; enum không gắn thẻ <code>ResponseEnvelope</code> phân định một khung là phản hồi hay là thông báo do máy chủ đẩy xuống.","changelog.3cae329c5ea1":"<code>service.rs</code>: trait <code>Service</code> mà <code>freally-indexd</code> hiện thực; <code>NotificationSink</code> cho phép một trình xử lý phương thức đẩy các thông báo bất đồng bộ xuống cùng kết nối.","changelog.a60b3df0f5d6":"<code>server.rs</code>: vòng lặp chấp nhận theo từng kết nối với hàng đợi gửi đi có giới hạn (<code>PER_CONN_OUT_QUEUE = 256</code>); tạo một tác vụ ghi cho mỗi kết nối và một tác vụ gom thông báo chuyển các <code>Notification</code> vào hàng đợi ghi. <code>handle_connection_for_tests</code> phơi bày cùng thân vòng lặp đó trên một <code>tokio::io::duplex</code> cho các kiểm thử tích hợp chạy dưới một giây.","changelog.829538dc4efb":"<code>client.rs</code>: <code>ClientHandle::call()</code> có kiểu, với một kênh trả lời oneshot cho mỗi lời gọi; <code>notifications()</code> trả về một đăng ký broadcast của tokio. Khi gặp EOF, tác vụ đọc giải phóng các bên gọi đang chờ bằng một lỗi gọn gàng dạng <code>transport closed</code>.","changelog.91eab238f9d7":"<code>transport/unix.rs</code>: <code>UnixListener::accept_authenticated()</code> đọc thông tin xác thực của đối tác qua <code>tokio::net::UnixStream::peer_cred()</code> và từ chối mọi đối tác có UID không khớp với tiến trình hiện tại — kết hợp với chế độ tệp 0600 được đặt trong <code>listen()</code>, điều này nghĩa là một người dùng khác trên cùng máy không thể kết nối dù biết đường dẫn. Để chắc chắn, thư mục cha cũng được chmod 0700.","changelog.fcfcdf081a40":"<code>transport/windows.rs</code>: <code>ServerOptions::create_with_security_attributes_raw</code> với một SECURITY_DESCRIPTOR sinh từ chuỗi SDDL dạng <code>D:(A;;GA;;;&lt;userSid&gt;)(A;;GA;;;SY)</code> — chỉ người dùng hiện tại (phân giải qua <code>OpenProcessToken</code> + <code>GetTokenInformation(TokenUser)</code> + <code>ConvertSidToStringSidW</code>) và SYSTEM có ACE cho phép truy cập. Không có <code>Everyone</code>, không có <code>Authenticated Users</code>. <code>reject_remote_clients(true)</code> chặn truy cập pipe qua mạng. <code>LocalFree</code> được bọc trong một guard RAII <code>SdDrop</code> để bộ mô tả bảo mật được giải phóng ngay cả trên các nhánh lỗi trả về sớm.","changelog.336f8a676048":"<code>path.rs</code>: đường dẫn socket / pipe mặc định theo quy ước của từng hệ điều hành. macOS: <code>~/Library/Application Support/freally/indexd.sock</code>. Linux: <code>$XDG_RUNTIME_DIR/freally/indexd.sock</code>, dự phòng là <code>~/.local/share/freally/indexd.sock</code>. Windows: <code>\\\\.\\pipe\\freally-indexd-&lt;userSid&gt;</code> (gắn SID để hai người dùng trên cùng một máy Windows có pipe riêng).","changelog.81b6aadfed10":"<code>dto.rs</code>: các DTO của serde phản chiếu <code>apps/freally-ui/src/lib/ipc/types.ts</code> đến từng byte — cùng các biến thể enum <code>serde(rename_all = &quot;lowercase&quot;)</code>, cùng <code>serde(rename = &quot;type&quot;)</code> cho khóa JSON <code>kind</code>, cùng hình dạng trường. Đợt kiểm tra tương đương của giai đoạn 12 khẳng định đầu ra JSON ổn định đến từng byte so với các fixture đã commit.","changelog.022aca1457de":"<strong>Crate mới <code>freally-extractor-host</code></strong> (trong <code>crates/freally-extractor-host/</code>) — khung trình trích xuất tùy chỉnh chạy trong hộp cát Wasm. Mặc định không được tin cậy, theo mô hình tin cậy của giai đoạn 12.","changelog.9b6d93374feb":"<code>manifest.rs</code>: lược đồ TOML với <code>id</code>, <code>display_name</code>, <code>version</code>, <code>formats: Vec&lt;String&gt;</code>, <code>magic: Vec&lt;String&gt;</code> tùy chọn (đặc tả chỉ gồm byte hex như <code>&quot;0x23 0x20&quot;</code>), <code>sidecar</code> (đường dẫn tới tệp nhị phân <code>*.wasm</code>, được kiểm tra là tồn tại khi nạp), <code>time_budget_ms</code> (mặc định 1000), <code>memory_budget_mb</code> (mặc định 64). Đặc tả magic sai bị từ chối khi nạp.","changelog.bca0da3b05e5":"<code>registry.rs</code>: trình quét <code>&lt;index_root&gt;/extractors/</code> nạp <code>manifest.toml</code> của mọi thư mục con. <code>registry.toml</code> ghi lại trạng thái tin cậy của người dùng cho từng trình trích xuất, mã băm blake3 để phát hiện can thiệp, và một bộ đếm sự cố tự động vô hiệu hóa trình trích xuất nào sập từ 3 lần liên tiếp trở lên cho đến khi người dùng tin cậy lại nó. Việc lưu trữ dùng cách ghi tệp tạm rồi đổi tên, qua <code>toml::to_string_pretty</code>. <code>set_trusted</code> xóa bộ đếm sự cố khi tin cậy lại.","changelog.b8bcebf716a9":"<code>sandbox.rs</code>: máy chủ <code>wasmtime</code> với các bảo đảm chặt chẽ — <code>Config::consume_fuel(true)</code> áp hạn mức CPU cho mỗi lời gọi (<code>fuel = time_budget_ms × 1_000_000</code>); một phép kiểm tra <code>Memory::data_size</code> sau lời gọi áp hạn mức bộ nhớ cho mỗi lời gọi. Chỉ hai hàm của máy chủ hiển thị với khách: <code>host_log(ptr: i32, len: i32)</code> (log gỡ lỗi, cắt ở 4 KiB) và <code>host_now_ms() -&gt; i64</code> (do máy chủ tiêm vào, khớp với <code>now_ms</code> của yêu cầu để khách không thể tự quan sát thời gian thực). Không có <code>wasi:sockets</code>, không có <code>wasi:filesystem-write</code>, không có <code>wasi:clocks</code>. Khách xuất <code>alloc(size) -&gt; i32</code> và <code>extract(ptr, len) -&gt; i64</code> (32 bit cao = con trỏ kết quả, 32 bit thấp = độ dài kết quả). Giới hạn 16 MiB cho độ dài kết quả, để một sidecar thù địch không thể trả về một blob 4 GiB.","changelog.c9d6d857a602":"<strong>Tái cấu trúc <code>freally-indexd</code> thành thư viện + tệp nhị phân.</strong> Tệp nhị phân chỉ làm dịch vụ của giai đoạn 1-3 trở thành một thư viện + một lớp vỏ mỏng. Thư viện phơi bày <code>DaemonState</code> (vùng chứa trạng thái dùng chung, giữ <code>Arc&lt;Index&gt;</code>, <code>Arc&lt;AudioCache&gt;</code>, <code>Pipeline</code>, <code>Registry</code>, cùng các cấu hình đã lưu <code>volumes / folders / excludes / network / history</code> trong <code>&lt;index_root&gt;/config/</code> dưới dạng tệp TOML) và <code>IndexdService</code> (hiện thực <code>Service</code> điều phối mọi phương thức liệt kê trong PRD §8.30). Các mô-đun mới:","changelog.2d2defa4d194":"<code>service.rs</code>: điều phối có kiểu cho <code>query.run</code> / <code>query.cancel</code> / <code>query.lens_timings</code> / <code>index.state</code> / <code>index.verify</code> / <code>index.compact</code> / <code>index.rebuild</code> / <code>extractors.list</code> / <code>extractors.set_mode</code> / <code>volumes.list</code> / <code>volumes.update</code> / <code>volumes.recreate_journal</code> / <code>volumes.reset_stream</code> / <code>volumes.upgrade_fanotify</code> / <code>volumes.remove</code> / <code>folders.list</code> / <code>folders.add</code> / <code>folders.remove</code> / <code>folders.update</code> / <code>folders.rescan</code> / <code>folders.rescan_all</code> / <code>excludes.get</code> / <code>excludes.set</code> / <code>network.status</code> / <code>network.start_https</code> / <code>network.stop_https</code> / <code>network.regen_token</code> / <code>network.start_api</code> / <code>network.stop_api</code> / <code>custom_extractors.list</code> / <code>custom_extractors.set_trusted</code> / <code>custom_extractors.refresh_hashes</code> / <code>history.get</code> / <code>history.set</code> / <code>history.clear</code> / <code>preview.text_head</code> / <code>preview.thumbnail</code> / <code>settings.apply</code> / <code>daemon.shutdown</code>. <code>query.run</code> truyền ngược các thông báo <code>query:batch</code> / <code>query:done</code> về máy khách (phía Tauri phát lại chúng thành sự kiện Tauri mà các store của Svelte tiêu thụ).","changelog.d58ec7a0cdfb":"<code>state.rs</code>: <code>DaemonState::open(opts)</code> mở chỉ mục, bộ nhớ đệm âm thanh, sổ đăng ký trình trích xuất tùy chỉnh, và đọc các tệp TOML cấu hình đã lưu. <code>DaemonState::persist()</code> ghi lại tất cả một cách nguyên tử. Các kiểu <code>VolumesConfig</code>, <code>VolumeOverride</code>, <code>NetworkState</code>, <code>HistoryConfig</code> tự lo việc lưu trữ của từng phần.","changelog.089d7c21d524":"<code>volumes.rs</code>: phát hiện ổ đĩa trên mọi hệ điều hành — Windows duyệt <code>GetLogicalDrives</code> + <code>GetVolumeInformationW</code> + <code>GetDiskFreeSpaceExW</code> và tạo các hàng NTFS / ReFS / exFAT / FAT32; macOS quét <code>/Volumes</code> + <code>statvfs</code>; Linux đọc <code>/proc/mounts</code> (bỏ qua các hệ thống tệp giả) + <code>statvfs</code>. Mỗi hàng mang một <code>id</code> ổn định (ví dụ <code>win-C</code>, <code>lin-_home</code>, <code>mac-Macintosh_HD</code>) để các thiết lập riêng cho từng ổ đĩa được giữ nguyên qua vòng đi-về.","changelog.60cb08f577a8":"<code>settings.rs</code>: phần tải có kiểu <code>SettingsApply</code> cho IPC <code>settings.apply</code>; daemon thay đổi trạng thái liên quan rồi lưu lại. <code>random_token_fingerprint()</code> tạo dấu vân tay hiển thị ngắn, không bí mật, xuất hiện trong bảng Mạng.","changelog.17b91de7bef9":"<code>history.rs</code>: phần tải có kiểu <code>HistoryUpdate</code> + hook <code>take_clear</code> dành cho giai đoạn 13 sau này, để xóa lịch sử ở phía daemon.","changelog.b566f0999042":"<strong><code>apps/freally-ui/src-tauri</code> trở thành máy khách RPC.</strong>","changelog.b3d45fd8ffa1":"Đã xóa <code>commands/canned.rs</code> (bộ dữ liệu giả lập của giai đoạn 11). Kiểm thử khói giai đoạn 12 <code>tests/smoke/phase_12_indexd_client.rs::no_canned_rs_in_tree</code> ngăn nó quay lại.","changelog.a467ed4a6368":"<code>daemon.rs</code> mới: khởi động một <code>freally-indexd</code> ngay trong tiến trình tại đường dẫn socket mặc định của từng hệ điều hành (biến môi trường <code>FREALLY_RPC_SOCKET</code> để ghi đè khi kiểm thử), mở một máy khách <code>freally-rpc</code>, và tạo một tác vụ phát lại biến mọi thông báo do máy chủ đẩy xuống thành sự kiện Tauri qua <code>app.emit(method, payload)</code>. <code>Daemon::call/call_void</code> sao chép máy khách và chạy future trên runtime tokio của daemon, tránh được xung đột move/borrow mà <code>Arc&lt;Daemon&gt;::block_on(async move {…})</code> sẽ gây ra.","changelog.2b8987c2135e":"<code>commands/query.rs</code>, <code>commands/index_state.rs</code>, <code>commands/extractors.rs</code>, cùng các tệp mới <code>commands/volumes.rs / folders.rs / excludes.rs / network.rs / custom_extractors.rs / history.rs</code> — thân của mọi lệnh Tauri giờ đều đi qua daemon. <code>query_parse</code> là ngoại lệ duy nhất chạy trong tiến trình — việc tách token theo nhịp gõ phím không gánh nổi một vòng đi-về tới daemon.","changelog.6a7142ad49d6":"<code>commands/files.rs</code> giữ cổng kiểm tra đường dẫn đã biết <code>verify_path</code> ở phía giao diện, nhưng <code>files_thumbnail</code> / <code>files_preview</code> giờ ủy thác cho mô-đun <code>preview</code> mới, vốn điều phối tới các trình xem trước gốc của hệ điều hành.","changelog.b19dfedad0ec":"<code>commands/settings.rs</code> giữ cơ chế lưu cục bộ dựa trên JSON và có thêm một HashMap <code>#[serde(flatten)] extras</code> thu nhận hơn 70 trường cấp cao nhất của giai đoạn 12 mà không làm phình bề mặt các giá trị vô hướng có kiểu; <code>ALLOWED_PATCH_KEYS</code> được mở rộng để bao phủ mọi khóa mới, theo hợp đồng danh sách cho phép của đợt rà soát bảo mật; <code>phase_12_default_extras()</code> điền các mặc định của giai đoạn 12 để <code>settings.json</code> của một bản cài mới có đủ mọi trường. Hợp đồng TS trong <code>lib/ipc/types.ts</code> không đổi.","changelog.1469ccfaba03":"<strong>Trình xem trước gốc của hệ điều hành</strong> (<code>apps/freally-ui/src-tauri/src/preview/</code>). Cấu trúc mô-đun theo nền tảng đã có; phần tích hợp đầy đủ của từng trình xem sẽ được bật dần như một cải tiến về trải nghiệm, không thay đổi hợp đồng data-URL.","changelog.b4df5b094937":"<code>preview/macos.rs</code> — cầu nối QuickLook (<code>QLPreviewPanel</code> cho xem trước đầy đủ, <code>QLThumbnailGenerator</code> cho hình thu nhỏ). Giai đoạn 12 phát hành bề mặt mô-đun và phần dò lúc chạy; chuỗi lời gọi <code>objc2</code> đầy đủ sẽ đến trong một đợt hoàn thiện.","changelog.7c608576f7b1":"<code>preview/windows_host.rs</code> — các trình xử lý xem trước của Shell (<code>IPreviewHandler</code> + <code>IThumbnailProvider</code> qua windows-rs). Cùng cách tiếp cận — bề mặt đã có, cầu nối COM được phát hành dần.","changelog.2350b7e13cc7":"<code>preview/linux.rs</code> — GNOME Sushi qua DBus khi có, KDE KIO qua tiến trình con khi có. Việc phát hiện là một lần dò <code>gdbus introspect</code> / <code>kioclient5 --version</code> được lưu đệm bằng <code>OnceLock</code>, nên chi phí cho mỗi lần xem trước bằng không sau lời gọi đầu tiên.","changelog.94e452c9cf02":"<code>preview/fallback.rs</code> — phương án dự phòng cho các hệ Unix ít phổ biến. Luôn trả về None để bên gọi rơi xuống đường chung: phần đầu văn bản + biểu tượng theo kiểu tệp.","changelog.3c9eec3f6c4b":"<code>preview/mod.rs</code> — điều phối tới trình xem + <code>text_head_fallback</code> (đọc tối đa 4 KiB, xếp vào loại văn bản khi và chỉ khi không có byte NUL và tỷ lệ ký tự thay thế ≤ 1%).","changelog.67698e29fe12":"<strong>Hộp thoại cài đặt</strong> (<code>apps/freally-ui/src/components/settings/</code>) — mọi điều khiển theo PRD §8.2-§8.27 đều được nối, không có stub.","changelog.a3361a51edd5":"<code>SettingsDialog.svelte</code>: hộp thoại modal đổi được kích thước (tối thiểu 800×620, mặc định 960×720), bố cục gồm cây điều hướng bên trái + khung chi tiết bên phải + thanh nút phía dưới. Lưu nút được chọn gần nhất + vị trí cuộn của từng khung qua localStorage, để khi mở lại hộp thoại sẽ quay về đúng bảng người dùng đang xem.","changelog.24b28d6fc11f":"<code>SettingsTreeNav.svelte</code>: cây đầy đủ theo PRD §8.1.1 (Chung / Lịch sử / Chỉ mục / Ống kính / Mạng / Quyền riêng tư &amp; Cập nhật / Nhật ký &amp; Gỡ lỗi / Sao lưu, Xuất, Đặt lại / Ngôn ngữ / Giới thiệu). Ô tìm trong tùy chọn lọc các nút theo nhãn và theo tập từ khóa của từng nút. Các bảng có thay đổi mang một dấu <code>•</code> màu tím để người dùng thấy bảng nào còn thay đổi chưa lưu.","changelog.4f8f836e7ec7":"<code>SettingsButtonBar.svelte</code>: Khôi phục mặc định (bên trái, theo từng bảng), OK / Hủy / Áp dụng (bên phải). Áp dụng chỉ bật khi <code>settingsDialog.dirty</code>; OK áp dụng rồi đóng; Hủy hoàn nguyên qua <code>SettingsDialogModel.cancel()</code> (<code>snapshot()</code> của mọi store được chụp khi mở hộp thoại, <code>rollback()</code> khôi phục lại); Khôi phục mặc định đặt lại bảng đang mở qua <code>SettingsDialogModel.resetPanel(panelId)</code>.","changelog.57b1a742578b":"26 thành phần bảng, mỗi thành phần ứng với một mục của PRD §8.2-§8.27. Điểm nổi bật:","changelog.66c58219af20":"<strong>Chung → Giao diện</strong>: bộ chọn giao diện sáng/tối (đổi ngay), các công tắc khay hệ thống, các biến thể nhấp một lần, mật độ hàng, hiệu ứng chuyển mờ dần.","changelog.cfe484eb7c32":"<strong>Chung → Trang chủ</strong>: bộ ba Dùng giá trị gần nhất | Bật | Tắt cho mọi mặc định về khớp; các danh sách thả xuống bộ lọc / sắp xếp / chế độ xem / nguồn chỉ mục; hiển thị ống kính mặc định + giới hạn kết quả theo từng ống kính.","changelog.434f9ca58ddb":"<strong>Chung → Tìm kiếm</strong>: mọi công tắc hành vi của DSL theo kiểu Everything của voidtools, cùng các phần bổ sung của Freally (chế độ strict-Everything, tự phát hiện regex, gợi ý hoàn thành công cụ sửa đổi, cây phân tích khi di chuột).","changelog.1d3e0b8951a4":"<strong>Chung → Kết quả</strong>: mọi danh sách thả xuống về hành vi + mức ưu tiên tải + nhóm theo ống kính.","changelog.66559820d7a5":"<strong>Chung → Xem</strong>: mọi công tắc hiển thị (E) + huy hiệu âm thanh/tương đồng của Freally + vị trí khung xem trước.","changelog.abfacc1cecb2":"<strong>Chung → Menu ngữ cảnh</strong>: Hiện / Chỉ hiện khi giữ Shift / Ẩn cho từng lệnh + chuỗi macro cho cả 10 mục.","changelog.bcfbad5112f2":"<strong>Chung → Phông chữ &amp; Màu sắc</strong>: phông chữ + cỡ chữ + màu chữ/màu nền theo trạng thái (với <code>&lt;input type=&quot;color&quot;&gt;</code>) + đậm + nghiêng cho cả 8 trạng thái mục + màu nhấn theo ống kính + công tắc kế thừa giao diện.","changelog.e1ece0afb46b":"<strong>Chung → Bàn phím</strong>: phím tắt toàn cục + phím tắt theo cửa sổ + sổ đăng ký tổ hợp phím (các hàng Thêm/Xóa cho từng cặp lệnh + phím).","changelog.3ae2a3be31d0":"<strong>Lịch sử</strong>: công tắc lịch sử tìm kiếm/lịch sử chạy + số ngày lưu giữ + nút Xóa ngay + chế độ riêng tư + công tắc lịch sử theo từng ống kính.","changelog.04aa58c3b95c":"<strong>Chỉ mục (cấp cao nhất)</strong>: mọi công tắc trường chỉ mục toàn cục của Everything + các nút Buộc dựng lại / Nén gọn / Xác minh (thao tác thật của daemon, có thông báo phản hồi).","changelog.9c0402a55809":"<strong>Chỉ mục → Ổ đĩa</strong>: phát hiện ổ đĩa đa nền tảng với huy hiệu hệ thống tệp (NTFS / ReFS / exFAT / FAT32 / APFS / HFS+ / ext4 / Btrfs / ZFS / XFS / F2FS) + chấm trạng thái; cho từng ổ đĩa: Đưa vào chỉ mục / Chỉ đưa vào / Bật đăng ký nhật ký (nhãn thay đổi theo hệ điều hành — USN / FSEvents / inotify) / Bộ đệm / Delta cấp phát (chỉ NTFS) / Tải thay đổi gần đây / Theo dõi thay đổi; các nút riêng theo hệ điều hành (Tạo lại nhật ký trên NTFS, Đặt lại luồng trên APFS, Nâng cấp lên fanotify trên Linux); nút Xóa.","changelog.a85227577e86":"<strong>Chỉ mục → Thư mục</strong>: Thêm qua bộ chọn thư mục của hệ điều hành + công tắc theo dõi cho từng thư mục + bộ đệm + lịch quét lại (Vào giờ cố định / Mỗi N giờ / Không bao giờ) + các nút Quét lại ngay / Quét lại tất cả ngay.","changelog.7a5ae0347c10":"<strong>Chỉ mục → Danh sách tệp</strong>: Thêm danh sách tệp qua bộ chọn + danh sách thả xuống định dạng (văn bản / JSON / .srcb) + công tắc tự động xuất các tìm kiếm đã lưu + nút Trình chỉnh sửa danh sách tệp.","changelog.e20f4ec8774d":"<strong>Chỉ mục → Loại trừ</strong>: danh sách thư mục + glob + Áp dụng loại trừ do hệ điều hành đề xuất (các loại trừ theo quy ước của Win / Mac / Linux) + các chip Loại trừ theo lớp phần mở rộng (video / âm thanh / hình ảnh / tệp nén / tệp thực thi).","changelog.8fd5ecb1f212":"<strong>Ống kính → Tên tệp</strong>: mức độ ráo riết của bộ lọc sơ bộ trigram + hạn mức bộ nhớ mảng hậu tố + giới hạn mở rộng ký tự đại diện + thời gian chờ regex.","changelog.38b4c6105b69":"<strong>Ống kính → Nội dung</strong>: bật/tắt + chế độ theo định dạng cho 11 định dạng + các hạn mức + độ dài đoạn trích + ngôn ngữ từ dừng (18 ngôn ngữ phát hành) + trích xuất lại khi đổi cài đặt + xác minh checksum của blob.","changelog.299de69339e8":"<strong>Ống kính → Âm thanh</strong>: bật/tắt + chế độ theo định dạng cho 10 định dạng + chuẩn tham chiếu LUFS + cách tính đỉnh + ngưỡng im lặng + trích xuất lại khi tệp bị sửa.","changelog.9b9db5aea8be":"<strong>Ống kính → Độ tương đồng</strong>: bật/tắt + kích thước chữ ký (64/128/256) + số dải (8/16/32) + ngưỡng truy hồi + giới hạn kết quả.","changelog.98316029b6fa":"<strong>Ống kính → Tùy chỉnh</strong>: sổ đăng ký trình trích xuất cộng đồng với công tắc tin cậy + hiển thị mã băm blake3 + khung xem quyền của hộp cát + Làm mới mã băm.","changelog.b244fd575e99":"<strong>Mạng → Máy chủ HTTPS</strong>: khởi động/dừng + bind/cổng/ép HTTPS/xác thực kiểu cũ + tạo lại token (xoay dấu vân tay ngay lập tức).","changelog.2b5f33d631fe":"<strong>Mạng → ETP/FTP API</strong>: khởi động/dừng + cổng + công tắc hỗ trợ FTP/ETP thuần kiểu cũ.","changelog.acd0f3e9e295":"<strong>Quyền riêng tư &amp; Cập nhật</strong>: tần suất tự động cập nhật + công tắc kênh bản phát hành sớm + chính sách cuộc gọi mạng cố định trong mã, chỉ đọc.","changelog.a7f925aabcc4":"<strong>Nhật ký &amp; Gỡ lỗi</strong>: mức nhật ký (đổi bộ lọc tracing ngay lập tức) + thời gian lưu giữ + mở thư mục nhật ký (qua <code>tauri-plugin-opener</code>) + xuất gói chẩn đoán.","changelog.71e2554230fe":"<strong>Sao lưu, Xuất, Đặt lại</strong>: Xuất / Nhập cài đặt (đi-về bằng TOML qua <code>tauri-plugin-fs</code>) + Xuất / Nhập gói dấu trang (.srcb) + Đặt lại tất cả (có xác nhận).","changelog.af4a3d364535":"<strong>Ngôn ngữ</strong>: danh sách thả xuống 18 ngôn ngữ phát hành — <strong>tiếng Anh được ghim đầu tiên</strong>, sau đó xếp theo thứ tự chữ cái của tên bản địa (nhóm Latinh → Kirin → RTL → các hệ chữ khác); mỗi nhãn là tên tự gọi của chính ngôn ngữ đó, để người dùng vẫn chọn được ngôn ngữ của mình ngay cả khi giao diện đang ở một hệ chữ họ không đọc được; chuyển RTL ngay lập tức qua <code>applyRtlForLocale()</code> (đặt <code>dir=&quot;rtl&quot;</code> và <code>lang</code> trên <code>document.documentElement</code> khi ngôn ngữ là tiếng Ả Rập hoặc khi đang bật Xem trước RTL); định dạng ngày / số (hệ điều hành / ISO / RFC / tùy chỉnh).","changelog.34eea5e6fc14":"<strong>Giới thiệu</strong>: phiên bản + commit + phát hiện hệ điều hành + giấy phép + ghi công voidtools + thông báo mã nguồn mở.","changelog.5db29baba331":"SettingsDialogModel (<code>lib/stores/settings_dialog.svelte.ts</code>) — máy trạng thái của các thay đổi chưa lưu. Theo dõi dấu thay đổi của từng bảng; khi mở hộp thoại, chụp snapshot mọi store; <code>apply()</code> chạy <code>flush()</code> của mọi store trong một lượt; <code>rollback()</code> khôi phục các snapshot; <code>resetPanel(id)</code> chỉ hoàn nguyên các khóa thuộc về bảng đó. <code>PANEL_KEYS</code> ánh xạ mỗi PanelId tới các khóa SettingsState mà nó sở hữu, để đặt lại một cách chính xác.","changelog.7d9367a4db32":"6 store mới đi qua daemon trong <code>lib/stores/</code>: <code>volumes / folders / excludes / network / custom_extractors / history</code>. Mỗi store có <code>hydrate()</code> (gọi khi hộp thoại mở), <code>snapshot()</code> / <code>rollback()</code>, <code>flush()</code>, <code>reset()</code>.","changelog.f76dd7e6a086":"<strong>Tệp nhị phân CLI <code>freally</code></strong> (<code>crates/freally-cli</code>) trở thành máy khách thứ hai của cùng kênh truyền <code>freally-rpc</code> — cùng đường dẫn socket, cùng cách xác thực. Các lệnh con: <code>search &quot;&lt;query&gt;&quot;</code> (với các cờ <code>--strict-everything</code> và <code>--parse-only</code>); <code>index status / verify / compact / rebuild / pause / resume / add-root &lt;path&gt; / rm-root &lt;path&gt;</code>; <code>bookmark save / list / delete</code> (trạng thái phía giao diện — hiện thông báo rõ ràng “do ứng dụng đang chạy quản lý” cho đến khi giai đoạn 13 chuyển dấu trang sang kênh truyền của daemon); <code>theme system | light | dark</code>. Lệnh con <code>search</code> đăng ký nhận thông báo trước để không bỏ lỡ các sự kiện <code>query:batch</code> đến sớm, in các kết quả khớp được nhóm theo ống kính ngay khi chúng đến, và in thời gian cuối cùng của từng ống kính khi nhận <code>query:done</code>.","changelog.af56538d34af":"<strong>i18n.</strong> Cả 18 tệp <code>.ftl</code> được mở rộng với các khóa hộp thoại cài đặt của giai đoạn 12 (~250 khóa mỗi ngôn ngữ, ~14 KiB mỗi tệp). Ngôn ngữ: en / ar / de / es / fr / hi / id / it / ja / ko / nl / pl / pt-BR / ru / tr / uk / vi / zh-CN. Mọi ngôn ngữ đều được dịch đầy đủ sang chính ngôn ngữ đó (không phát hành bản nháp dịch máy). Bố cục tiếng Ả Rập RTL được kiểm thử qua việc chuyển ngay lập tức bằng <code>applyRtlForLocale()</code> trong <code>lib/bootstrap.ts</code> và công tắc <strong>Ngôn ngữ → Xem trước RTL</strong>. Ô chọn kết hợp, với mỗi nhãn là tên tự gọi bản địa, giúp người dùng bị kẹt trong một hệ chữ họ không đọc được vẫn chọn được ngôn ngữ của mình.","changelog.3cd9ef6d9858":"<strong>Kiểm thử khói</strong> (<code>tests/smoke/phase_12_*</code> cùng các bản xuất lại theo từng crate trong <code>crates/freally-rpc/tests</code>, <code>crates/freally-indexd/tests</code>, <code>crates/freally-extractor-host/tests</code>):","changelog.233c2ff71ae3":"<code>phase_12_rpc_transport.rs</code> — đi-về qua một UDS thật (Unix) / named pipe (Windows); khẳng định chế độ tệp 0600 trên tệp socket; hành vi khi gặp EOF sạch; từ chối khung quá cỡ.","changelog.037808959a87":"<code>phase_12_indexd_client.rs</code> — <code>query.run</code> truyền các lô và phát <code>query:done</code>; <code>index.state</code> trả về một khung nhìn có kiểu; đi-về <code>extractors.list</code> + <code>extractors.set_mode</code>; đi-về <code>excludes.get</code> / <code>excludes.set</code>; cổng hồi quy <code>no_canned_rs_in_tree</code> làm hỏng bản dựng nếu <code>canned.rs</code> xuất hiện trở lại.","changelog.c5cfbc1b43d4":"<code>phase_12_settings.rs</code> — đi-về JSON dựa trên fixture cho hình dạng <code>SettingsState</code> của giai đoạn 12; flatten của <code>extras</code> giữ lại các khóa không xác định.","changelog.3f571f0f5d1b":"<code>phase_12_custom_extractor.rs</code> — mặc định của manifest; đi-về trạng thái tin cậy; bộ đếm sự cố vô hiệu hóa ở lần thứ ba; bỏ qua manifest sai; khởi tạo engine của máy chủ.","changelog.3dbbc40cea55":"<code>phase_12_theme_switch.rs</code> — đi-về JSON của lựa chọn giao diện qua <code>settings.apply</code>.","changelog.972927dbd83f":"<code>phase_12_preview_hosts.rs</code> — phân loại của phương án dự phòng chung dùng phần đầu văn bản + bảng màu SVG của biểu tượng theo kiểu tệp.","changelog.a578a3241000":"<code>phase_12_volumes.{ps1,sh}</code> — các script shell theo từng hệ điều hành chạy <code>cargo test -p freally-indexd --test phase_12_indexd_client</code> (các bất biến phát hiện ổ đĩa nằm trong kiểm thử đơn vị của crate indexd; các kiểm thử khói bằng shell là cổng kiểm tra trên mọi hệ điều hành).","changelog.c7b0c19f8b54":"<strong>Sai khác so với Build Guide</strong> (một): prompt yêu cầu các trình xem trước gốc của hệ điều hành (QuickLook / Shell / Sushi+KIO) phải được <em>nối đầy đủ</em> trong giai đoạn 12. Cấu trúc mô-đun đa nền tảng + phương án dự phòng chung được phát hành trong giai đoạn này; các tích hợp COM/objc2/DBus theo từng hệ điều hành sẽ đến dưới dạng cải tiến tiện dụng, không thay đổi hợp đồng data-URL hay bề mặt lệnh Tauri. Bề mặt mô-đun <code>preview</code> đã sẵn sàng nên việc thay thế chỉ mang tính cục bộ.","changelog.409ff5baabf9":"<strong>[mọi nền tảng]</strong> Giai đoạn 11: giao diện tìm kiếm — khoảnh khắc kỳ diệu (<code>apps/freally-ui</code>). Ứng dụng máy tính Tauri 2 + Svelte 5 + TypeScript + Tailwind CSS chạy trên một backend IPC <em>giả lập</em> trong <code>src-tauri/src/commands/</code>. Lệnh duy nhất nói chuyện với một backend thật là <code>query_parse</code>, đi thẳng tới <code>freally-query::parse_to_report</code>, để việc tách token trực tiếp trong thanh tìm kiếm khớp chính xác với bộ phân tích dùng trong sản phẩm. Giai đoạn 12 (TASK-086a/b/c) thay lớp giả lập bằng kênh truyền RPC thật của <code>freally-indexd</code> mà không đổi hợp đồng kiểu TS trong <code>lib/ipc/types.ts</code>.","changelog.8c8596283703":"<strong>Bề mặt giao diện (PRD §8.28 + §8.29 + §9):</strong> SearchBar tách token trực tiếp qua IPC <code>query.parse</code> + vẽ các đoạn trên một lớp gương, tô màu theo loại token + nhãn lỗi phân tích nội tuyến neo vào đoạn lỗi đầu tiên (Esc để xóa); kết quả nhóm theo ống kính (Tên tệp / Nội dung / Âm thanh / Độ tương đồng) với các phần thu gọn được, huy hiệu thời gian theo từng ống kính, công tắc hiển thị ống kính qua <code>View → Lenses</code>; kết quả nhiều cột (tên | đường dẫn | kích thước | ngày sửa | loại | phần mở rộng) với thao tác kéo đổi kích thước trên tay nắm cột bằng pointer capture, nhấp để đổi chiều sắp xếp (luân phiên tăng / giảm), hồ sơ cột đã lưu qua <code>settings.column_profiles[active]</code>, công tắc mật độ hàng gọn (32 px) / thoải mái (44 px); tương tác với hàng (Enter để mở / Ctrl+Enter để hiện trong thư mục / Shift+Enter để sao chép đường dẫn / Ctrl+C để sao chép tên / Del để xác nhận rồi xóa; Ctrl+nhấp để bật/tắt chọn); khung xem trước gắn với <code>file_id</code> được chọn đầu tiên (vẽ phần đầu văn bản từ IPC <code>files_preview</code>, hỗ trợ data URL hình ảnh, hiện “Không hỗ trợ” cho tệp nhị phân — các trình xem trước gốc của hệ điều hành được nối trong giai đoạn 12); cột hình thu nhỏ (<code>ThumbnailCell</code> gọi IPC <code>files_thumbnail</code>, với các ô vuông SVG tô màu giả lập theo phần mở rộng); BookmarksDropdown trên thanh menu lấy dữ liệu từ <code>bookmarks_list</code> (lưu trữ thật dựa trên JSON trong thư mục dữ liệu ứng dụng của hệ điều hành) + OrganizeBookmarksDialog với đổi tên + xóa (Ctrl+D để thêm, Ctrl+Shift+B để mở Sắp xếp); QuickFiltersPalette với 7 chip (âm thanh / video / hình ảnh / tài liệu / tệp thực thi / tệp nén / thư mục) bật/tắt token tương ứng; phím tắt toàn cục qua <code>tauri-plugin-global-shortcut</code> (mặc định Alt+Space trên macOS, Super+Space trên Win/Linux) — khi nhấn sẽ đưa cửa sổ lên trước + đặt tiêu điểm vào ô tìm kiếm; giao thức URL <code>freally://search?q=…</code> qua <code>tauri-plugin-deep-link</code>; trình hướng dẫn lần chạy đầu (4 bước: thư mục gốc / phím tắt / ngôn ngữ / giao diện) phụ thuộc vào <code>settings.first_run_complete</code>; hệ thống giao diện (PRD §9) với ba trạng thái <code>system</code> / <code>light</code> / <code>dark</code> qua thuộc tính <code>&lt;html data-theme&gt;</code>, các token điều khiển mọi màu qua thuộc tính tùy chỉnh CSS (<code>tokens.{dark,light,shared}.css</code>), hiệu ứng chuyển mờ 100 ms tôn trọng <code>prefers-reduced-motion</code>, bộ lắng nghe <code>prefers-color-scheme</code> đổi ngay khi ở chế độ <code>system</code>, cấu hình Tailwind ánh xạ các tiện ích tới <code>var(--…)</code>.","changelog.ab4ea4f7502a":"<strong>Thanh menu chính (PRD §8.28)</strong> — các menu đầy đủ tương đương Everything trên Tệp / Chỉnh sửa / Xem / Tìm kiếm / Dấu trang / Công cụ / Trợ giúp, với mọi menu con + mục con + phím tăng tốc + các phần bổ sung của Freally (menu con Xem → Giao diện, menu con Xem → Ống kính, Công cụ → Bảo trì chỉ mục ▶ Xác minh / Nén gọn / Buộc dựng lại, Công cụ → Trình quản lý trình trích xuất tùy chỉnh, Trợ giúp → Tham chiếu công cụ sửa đổi âm thanh / tương đồng, Trợ giúp → Tài trợ / Quyên góp). Vị trí theo hệ điều hành: macOS dùng <code>tauri::menu::MenuBuilder</code> cho thanh menu toàn cục (với menu ứng dụng <code>Freally →</code> mà macOS yêu cầu, chứa Giới thiệu / Tùy chọn / Thoát); Win/Linux vẽ một <code>MenuBar.svelte</code> bên trong cửa sổ, dùng cùng đặc tả khai báo qua cùng tập CommandId. Các sự kiện nhấp từ menu gốc của macOS phát <code>menu-command</code>; <code>bootstrap.ts</code> của giao diện lắng nghe và điều phối qua sổ đăng ký lệnh trong tiến trình — một nguồn sự thật duy nhất cho cả hai đường vẽ. Các sự kiện di chuột phát <code>MenuHoverEvent</code> → phần gợi ý trên thanh trạng thái. Các gợi ý khi di chuột khớp chính xác với chuỗi của Everything (“Chứa các lệnh để làm việc với Freally.”, “Chứa các lệnh để sắp xếp danh sách kết quả.”, v.v.) cùng các phần bổ sung của Freally (“Chuyển giữa giao diện hệ thống, sáng hoặc tối.”, “Bật/tắt hiển thị của từng ống kính trong danh sách kết quả.”, “Quản lý các trình trích xuất tùy chỉnh chạy trong hộp cát Wasm.”, “Công cụ bảo trì chỉ mục.”).","changelog.d29275561d2e":"<strong>Thanh trạng thái (PRD §8.29)</strong> — bật/tắt qua <code>View → Status Bar</code>. Bảy phần mặc định từ trái → phải: chấm lập chỉ mục (Đã lập chỉ mục / Đang lập chỉ mục N/M / Tạm dừng / Lỗi) hiện phím tắt khi di chuột, số kết quả + số mục đã chọn, kích thước vùng chọn (phụ thuộc <code>show_size_in_status_bar</code>), thời gian của truy vấn hiện tại, độ trễ theo từng ống kính (phụ thuộc <code>show_timing_badges</code>), chỉ báo điểm cuối (CSDL cục bộ / API: \\&lt;name\\&gt;), vùng gợi ý khi di chuột đăng ký vào store di chuột của menu với văn bản khi rảnh <code>Ready · {indexed} indexed</code>. Phần bổ sung riêng của Freally: chấm giao diện ở ngoài cùng bên phải (biểu tượng mặt trời / mặt trăng, nhấp một lần để luân phiên 3 trạng thái); việc chấm lập chỉ mục hiện phím tắt khi di chuột là một trong hai phần bổ sung (+) của PRD §8.29.","changelog.5bcf148b5b86":"<strong>Sổ đăng ký lệnh + phím tắt:</strong> <code>lib/commands/ids.ts</code> chứa một union chuỗi <code>CommandId</code> vét cạn tại thời điểm biên dịch, bao phủ ~95 mục menu; <code>isCommandId</code> là phép kiểm tra tập đóng mà <code>bootstrap.ts</code> dùng để xác thực phần tải của sự kiện <code>menu-command</code> từ menu gốc của macOS (từ chối phần tải sai dạng). <code>lib/commands/registry.ts</code> điều phối qua một <code>Map&lt;CommandId, CommandHandler&gt;</code> — mọi CommandId đều có trình xử lý được đăng ký khi khởi động; đường khởi động phát <code>console.warn</code> nếu thiếu cái nào. <code>lib/commands/menu_spec.ts</code> (TS) + <code>src-tauri/src/menu_spec.rs</code> (Rust) — các cây menu khai báo mà cả hai trình vẽ dùng, được giữ đồng bộ bằng kiểm thử tương đương <code>tests/menubar_parity.rs::rust_spec_covers_every_command_id</code> + <code>does_not_introduce_unknown_command_ids</code> (một bước sinh mã lúc dựng sẽ chỉ thêm phạm vi mà lợi ích lại âm; kiểm thử tương đương là cổng hồi quy). <code>lib/commands/shortcuts.ts</code> nhận biết hệ điều hành — <code>mod</code> được phân giải thành ⌘ trên macOS, Ctrl trên Win/Linux lúc chạy qua <code>isMac()</code>. Các trình xử lý thật được nối trong giai đoạn này: thu phóng (font-size gốc), kích thước cửa sổ (<code>WebviewWindow::setSize</code> của Tauri), sắp xếp (trường <code>sortStore</code> + trạng thái thứ tự), luôn ở trên cùng (<code>set_always_on_top</code>), hình thu nhỏ/chi tiết (row_density), giao diện (đi-về giao diện + cài đặt), hiển thị ống kính, làm mới (chạy lại truy vấn), công tắc xem trước/status_bar, file.close / file.exit (đóng cửa sổ), tools.options (hộp thoại cài đặt tạm thời), tools.verify/compact/rebuild_index (IPC thật), help.\\* (mở URL qua plugin opener), help.about (hộp thoại Giới thiệu), bookmarks.add/organize (store + hộp thoại), các ID lệnh của bộ lọc nhanh (chèn token vào đầu + chạy lại), edit.cut/copy/paste/select_all/invert_selection, edit.advanced.copy_full_name/path/filename/as_json/with_metadata/as_bundle_ref. Các trình xử lý tạm thời còn lại (file.new_window / file.open_file_list / file.export_results / view.go_to / search.advanced / search.add_to_filters / search.organize_filters / các công tắc khớp của tìm kiếm / tools.file_list_editor / edit.copy_to_folder/move_to_folder) được gắn nhãn rõ <code>Phase 12</code> trong mã — chúng chờ IPC thật của daemon hoặc hộp thoại cài đặt đầy đủ, cả hai đều thuộc phạm vi giai đoạn 12.","changelog.a2506592845e":"<strong>Backend IPC giả lập bằng Rust</strong> (<code>apps/freally-ui/src-tauri/src/commands/</code>): <code>query.rs</code> định tuyến <code>query_parse</code> qua <code>freally-query::parse_to_report</code> thật (bề mặt giai đoạn 10, thật); <code>query_run</code> / <code>query_cancel</code> / <code>query_lens_timings</code> / <code>query_fetch_batches</code> tạo ra các lô dựng sẵn, mang tính tất định, trên bốn ống kính, với LensTimings tổng hợp nhưng đúng hình dạng (8 ms tên tệp / 22 ms nội dung / 5 ms âm thanh / 11 ms tương đồng / 14 ms tổng). <code>canned.rs</code> tổng hợp 12 / 8 / 4 / 6 kết quả khớp trên bốn ống kính cho mỗi truy vấn (tất định để kiểm thử khói có thể cố định theo đầu ra; hằng số tổng số đã lập chỉ mục là 5 234 123 tệp dùng cho văn bản khi rảnh của chấm lập chỉ mục). <code>index_state.rs</code> chuyển từ <code>Indexing N/total</code> sang <code>Indexed (total)</code> trong khoảng khởi động 4 giây. <code>bookmarks.rs</code> có lưu trữ thật dựa trên JSON trong <code>app.path().app_data_dir()</code> (thư mục gốc đã được Tauri kiểm duyệt). <code>extractors.rs</code> mang một sổ đăng ký dựng sẵn gồm bảy trình trích xuất của giai đoạn 7–9 với <code>ExtractorMode</code> riêng cho từng cái (háo hức / lười / đã tắt). <code>settings.rs</code> dựa trên JSON, với vòng đi-về <code>settings_set(patch)</code> hợp nhất sâu qua <code>serde_json::to_value</code> + giải tuần tự lại có kiểu; <code>settings_reset</code> khôi phục mặc định; lược đồ bao gồm giao diện / ngôn ngữ / công tắc thanh trạng thái / công tắc huy hiệu thời gian / xem trước / mật độ hàng / hồ sơ cột / hiển thị ống kính / phím tắt / điểm cuối / cờ lần chạy đầu / chế độ riêng tư. <code>files.rs</code> dùng <code>tauri-plugin-opener</code> cho các trình xử lý mở/hiện thật của hệ điều hành, <code>tauri-plugin-clipboard-manager</code> cho copy_path / copy_name, <code>std::fs::remove_file</code> để xóa (sau khi giao diện xác nhận), data-URL SVG tô màu cho hình thu nhỏ (giả lập), phần đầu văn bản hoặc <code>Unsupported</code> cho xem trước (giả lập).","changelog.7d2b902ad7ff":"<strong>Tích hợp gốc:</strong> <code>native_menu.rs</code> dựng đệ quy một <code>tauri::menu::Menu</code> từ <code>menu_spec.rs</code> và trên macOS đặt nó làm menu ứng dụng qua <code>app.set_menu(...)</code> (menu ứng dụng <code>Freally →</code> mà macOS yêu cầu chứa Giới thiệu / Tùy chọn / Thoát với các phím tăng tốc đúng theo HIG). <code>hotkey.rs</code> đăng ký tổ hợp mặc định (Alt+Space trên macOS, Super+Space trên Win/Linux) qua <code>tauri-plugin-global-shortcut</code>; khi được nhấn, nó hiện + đặt tiêu điểm vào cửa sổ chính và phát <code>hotkey:fired</code> để giao diện đặt tiêu điểm vào ô tìm kiếm; xung đột được ghi thành log <code>warn</code> (người dùng có thể đổi tổ hợp trong cài đặt của giai đoạn 12). <code>url_protocol.rs</code> đăng ký lược đồ <code>freally://</code> qua <code>tauri-plugin-deep-link</code> và phát <code>url:opened</code> cho các URL đến; bộ lắng nghe của giao diện phân tích chúng bằng <code>new URL(...)</code> và chỉ xử lý dạng <code>?q=</code>.","changelog.dfae438bb9e9":"<strong>i18n</strong> (Quy tắc thường trực #4): gói tiếng Anh nội tuyến (giai đoạn 12 nối bộ nạp Fluent đầy đủ với <code>locales/&lt;code&gt;/freally.ftl</code> cho cả 18 ngôn ngữ). Cả 18 tệp <code>.ftl</code> được mở rộng với các khóa của giai đoạn 11 (các nhóm trạng thái / menu / giao diện / ống kính / lỗi phân tích / hành động / bộ lọc nhanh / trình hướng dẫn) — là bản nháp dịch máy đang chờ người duyệt trước v0.19.84. <code>xtask i18n-lint</code> vẫn xanh với số khóa mới × 17 ngôn ngữ không phải ngôn ngữ nguồn.","changelog.d61b34326782":"<strong>Kiểm thử + xác thực:</strong> <code>tests/smoke/phase_11_ui_e2e.rs</code> (7 ca — được xuất lại trong <code>crates/freally-query/tests/phase_11_ui_e2e.rs</code>) bao phủ các bất biến của luồng token từ <code>parse_to_report</code> mà <code>highlight.ts</code> của thanh tìm kiếm phụ thuộc vào, việc hiển thị lỗi của chế độ strict-everything cho nhãn lỗi phân tích, độ ổn định khi đi-về JSON của <code>LensId</code> + <code>IndexPhase</code> trong IPC cho lần thay thế ở giai đoạn 12, và <strong>cổng hiệu năng của khoảnh khắc kỳ diệu</strong> (TASK-085): <code>parse_to_report</code> trung bình mất dưới 4 ms / lần lặp một cách thoải mái với truy vấn 1 ký tự và với một truy vấn thực tế 32 ký tự — đường găng của mỗi phím gõ nằm gọn trong hạn mức 16 ms mà Build Guide nêu. <code>apps/freally-ui/src-tauri/tests/menubar_parity.rs</code> (4 ca) — mọi CommandId của PRD §8.28 đều có trong đặc tả Rust; không thừa cái nào; 7 gốc cấp cao nhất theo đúng thứ tự; không có id trùng. <code>apps/freally-ui/src-tauri/tests/menubar_wiring.rs</code> (3 ca) — mọi id mục menu đều đúng dạng (dạng <code>namespace.action</code>); mọi chuỗi phím tăng tốc đều phân tích được; Giới thiệu / Tùy chọn / Thoát của menu ứng dụng macOS trỏ tới CommandId thật. <code>apps/freally-ui/src-tauri/tests/statusbar_parity.rs</code> (2 ca) — cố định 7 phần mặc định + 2 phần bổ sung (+) của Freally. <code>apps/freally-ui/tests/unit/*.test.ts</code> (khung vitest, ~25 ca) — các bộ định dạng, tập đóng của id lệnh + đồng bộ với <code>MENU_BAR</code>, cách tạo đoạn của <code>highlight()</code> trong bộ tách token + lớp phủ lỗi + <code>firstError</code>, tính duy nhất của <code>BINDINGS</code> + <code>shortcutMatches</code> + <code>formatShortcut</code>, công tắc <code>sortStore</code> / nhảy sang trường khác / tương đồng theo điểm số, vòng luân phiên của store giao diện + thay đổi thuộc tính DOM. <code>tests/smoke/phase_11_ui_e2e.{sh,ps1}</code> chạy <code>cargo test</code> cho kiểm thử định tuyến + <code>cargo check</code> cho crate src-tauri + (khi có <code>pnpm</code>) <code>pnpm install + check + build</code>. <strong>Cổng xác thực</strong>: <code>cargo fmt --all -- --check</code>, <code>cargo clippy --workspace --all-targets -- -D warnings</code>, <code>cargo test --workspace</code> đều xanh; <code>apps/freally-ui/src-tauri</code> qua cargo check + clippy sạch, không có cảnh báo nào; 9 kiểm thử src-tauri + 7 kiểm thử khói đều đạt. <code>/review</code> + <code>/security-review</code> sạch (Quy tắc thường trực #9).","changelog.03bf40d97b72":"Khung <strong>Storybook</strong> + 3 story khởi đầu (LensTimingBadge, QuickFiltersPalette, SearchBar) trong <code>apps/freally-ui/src/stories/</code>, với <code>.storybook/main.ts</code> + <code>preview.ts</code> mang bộ chuyển giao diện tối / sáng trên thanh công cụ, theo yêu cầu kiểm thử hồi quy hình ảnh của PRD §9.","changelog.5df93276a274":"<strong>Bàn giao giai đoạn 11 → giai đoạn 12</strong> (hoãn sang TASK-086a/b/c, ghi trong Build-Prompts-Guide + ROADMAP): thay <code>commands/canned.rs</code> + <code>IndexStateMock</code> giả lập bằng một kênh truyền JSON-RPC thật của <code>freally-rpc</code>, có tiền tố độ dài, chạy trên Unix socket / named pipe riêng cho từng người dùng (chế độ tệp 0600 + kiểm tra uid khi chấp nhận trên Unix; DACL của pipe chỉ giới hạn cho SID của người dùng hiện tại trên Windows); định tuyến <code>query_run</code> qua <code>freally-query::execute_with_audio</code> thật trên một <code>freally-index</code> đang chạy, truyền các lô qua <code>Window::emit(&quot;query:batch&quot;, ...)</code> để cổng 16 ms của giao diện vẫn trung thực với 5M tệp; các trình xem trước gốc của hệ điều hành (QuickLook qua <code>objc2</code> trên macOS / trình xử lý xem trước của Shell qua <code>windows-rs</code> trên Windows / xem trước GNOME Sushi qua DBus + KDE KIO trên Linux) thay cho <code>files_preview</code> / <code>files_thumbnail</code> giả lập. Hợp đồng TS trong <code>lib/ipc/types.ts</code> giữ ổn định qua lần thay thế.","changelog.1cfd9c0b8865":"<strong>Sai khác so với Build Guide</strong> (ba điểm, đều được ghi chú trong mã + mục này): (1) <strong>Plugin shell của Tauri</strong> — Build Guide ngụ ý dùng <code>tauri-plugin-shell::open()</code> cho <code>files_open</code> / <code>files_reveal</code>; API đó đã bị khai tử để nhường chỗ cho <code>tauri-plugin-opener::open_path</code>. Chúng tôi dùng plugin mới để tránh cảnh báo khai tử ở mọi bản dựng. (2) <strong>Menu gốc trên Win/Linux</strong> — Build Guide ghi “trong cửa sổ trên Win/Linux, thanh menu toàn cục trên macOS”; giai đoạn 11 phát hành menu trong cửa sổ trên Win/Linux + menu gốc của macOS. Việc tích hợp DBus AppMenu trên Linux (ở nơi có) được hoãn sang giai đoạn 12. (3) <strong>Trình xem trước gốc của hệ điều hành</strong> — giai đoạn 11 phát hành với nhà cung cấp nội dung giả lập cho khung xem trước (phần đầu văn bản + hình thu nhỏ SVG tô màu); các tích hợp QuickLook / Shell / Sushi / KIO chuyển sang giai đoạn 12 (TASK-086c), nơi chúng dùng chung phạm vi IPC thật với daemon. TASK-075 / TASK-076 trong prompt của giai đoạn 11 có ghi chú ROADMAP nội tuyến về việc hoãn này.","changelog.2e4654ecd39f":"<strong>[mọi nền tảng]</strong> Giai đoạn 10: ngôn ngữ truy vấn + gia cố bộ phân tích (<code>freally-query</code>) — bộ phân tích viết tay của giai đoạn 5 giữ nguyên bề mặt 1:1 với Everything của voidtools (hợp đồng của Quy tắc thường trực #8) và có thêm bốn phần mới: (1) <strong><code>ParseOpts { strict_everything: bool }</code></strong> + <code>pub fn parse_with(s, opts) -&gt; Result&lt;Query, ParseError&gt;</code> (<code>parse(s)</code> của giai đoạn 5 giờ là <code>parse_with(s, ParseOpts::default())</code>). Chế độ strict-everything từ chối mọi công cụ sửa đổi chỉ có ở Freally — <code>similar:</code>, sáu công cụ sửa đổi âm thanh (<code>lufs:</code> / <code>codec:</code> / <code>length:</code> / <code>rate:</code> / <code>silence:</code> / <code>dr:</code>) cùng các bí danh <code>duration:</code> / <code>samplerate:</code>, và các tiền tố ống kính <code>audio:(...)</code> / <code>content:(...)</code> / <code>similar:(...)</code> — và trả về lỗi có kiểu mới <code>ParseError::StrictEverythingViolation { pos, token, reason }</code>, để thanh tìm kiếm của giai đoạn 11 có thể đánh dấu những công cụ sửa đổi nào sẽ không dùng được với người dùng thuần voidtools. Bề mặt kiểu voidtools (size, date, ext, attrib, path/parent/child + các bí danh name/folder, bộ lọc nhanh, regex, ký tự đại diện, toán tử logic, dấu ngoặc, và các từ dành sẵn theo thói quen <code>wfn:</code> / <code>case:</code> / <code>count:</code> / <code>dupe:</code> / <code>nodiacritics:</code> / <code>type:</code> / <code>lang:</code>) vẫn được phân tích trong chế độ nghiêm ngặt. (2) <strong>Cú pháp tiền tố ống kính</strong> <code>&lt;key&gt;:(...)</code> cho <code>name:</code> / <code>audio:</code> / <code>content:</code> / <code>similar:</code>. Biến thể AST mới <code>QueryNode::Lens { kind: LensKind, inner: Box&lt;QueryNode&gt; }</code> (với <code>pub enum LensKind { Name, Audio, Content, Similar }</code>) bọc một truy vấn con bên trong, để giao diện kết quả nhóm theo ống kính của giai đoạn 11 có thể vẽ các phần theo từng ống kính. Bộ phân tích chỉ đi theo đường tiền tố ống kính khi token đúng là <code>&lt;key&gt;:</code> <em>và</em> token kế tiếp là <code>(</code> — <code>audio:</code> đứng riêng vẫn là bộ lọc nhanh; <code>similar:foo</code> vẫn là công cụ sửa đổi <code>Similar</code> sẵn có; <code>name:foo</code> vẫn là bí danh của <code>child:</code>. Phạm vi ống kính rỗng (<code>audio:()</code>) thu gọn thành <code>True</code>. Hiện nay bộ thực thi coi các phạm vi ống kính <code>Name</code> / <code>Audio</code> / <code>Similar</code> là lớp bọc trong suốt (các công cụ sửa đổi bên trong vẫn quyết định việc định tuyến); phạm vi ống kính <code>Content</code> trả về <code>QueryError::UnsupportedModifier(&quot;content&quot;)</code> cho đến khi giai đoạn 11+ nối các trình trích xuất nội dung của giai đoạn 8 vào bộ thực thi. (3) <strong>Lượt tối ưu hóa</strong> trong <code>crates/freally-query/src/optimizer.rs</code> mới: <code>pub fn optimize(q: &amp;Query) -&gt; Query</code> sắp xếp lại các con của <code>And</code> theo <code>selectivity_rank</code> (rẻ nhất trước → cơ chế ngắt mạch tận dụng chúng), đệ quy vào <code>Or</code> / <code>Not</code> / <code>Lens</code> (thứ tự của Or được giữ nguyên — thứ tự quan trọng để kết quả có thứ tự ổn định); hàm xếp hạng được hiệu chỉnh theo chi phí từng vị từ của bộ thực thi giai đoạn 5/6/9 (literal/quick-filter/child = 10-12, ext = 13, size/date/attrib = 20-24, path/parent = 30, ký tự đại diện = 40, regex = 50, âm thanh = 80, similar = 85, dành sẵn = 90). Các hàm hỗ trợ định tuyến ống kính <code>is_audio_only_route(node)</code> và <code>is_similarity_route(node)</code> cho phép bộ thực thi bỏ qua bộ lọc sơ bộ trigram tên tệp với truy vấn chỉ có âm thanh (mọi hàng còn sống đều là ứng viên, nên <code>for_each_live</code> chạy mà không gọi <code>evaluator.matches</code> cho từng hàng). Bộ tối ưu được nối vào <code>execute_with_audio</code> (đầu pipeline) và <code>PlanCache::get_or_plan</code> (dạng được lưu đệm chính là dạng đã tối ưu), để mọi lần chạy thực tế đều được hưởng lợi mà không thay đổi hình dạng AST người dùng thấy từ <code>parse()</code>. (4) <strong><code>pub fn parse_to_report(s: &amp;str, opts: ParseOpts) -&gt; ParseReport</code></strong> — điểm vào IPC <code>query.parse</code> trong <code>crates/freally-query/src/report.rs</code> mới. <code>ParseReport { source, strict_everything, ast: Option&lt;AstNode&gt;, tokens: Vec&lt;TokenInfo&gt;, errors: Vec&lt;ErrorInfo&gt; }</code> hoàn toàn tuần tự hóa được bằng serde, sẵn sàng cho một lệnh Tauri hoặc một POST <code>/v1/query.parse</code> của <code>freally-http</code> sau này. <code>TokenInfo { kind, span: TokenSpan { start, end }, text }</code> mang khoảng vị trí của từng token + một kiểu ngữ nghĩa <code>TokenKind</code> (<code>Literal</code> / <code>Quoted</code> / <code>Wildcard</code> / <code>Regex</code> / <code>Modifier{name}</code> / <code>QuickFilter{name}</code> / <code>LensPrefix{lens}</code> / <code>LParen</code> / <code>RParen</code> / <code>Bang</code> / <code>And</code> / <code>Or</code> / <code>Not</code>), để thanh tìm kiếm có thể tô sáng token ngay khi người dùng gõ. <code>ErrorInfo { span, message, code: ErrorCode }</code> chiếu mọi biến thể <code>ParseError</code> thành một khoảng vị trí + thông báo phù hợp cho giao diện + một <code>ErrorCode</code> máy đọc được (<code>Empty</code> / <code>UnexpectedEof</code> / <code>UnexpectedToken</code> / <code>UnbalancedParens</code> / <code>InvalidRegex</code> / <code>InvalidWildcard</code> / <code>UnknownModifier</code> / <code>InvalidModifierValue</code> / <code>StrictEverythingViolation</code>). <code>AstNode</code> tuần tự hóa được phản chiếu <code>QueryNode</code> trừ phần tải <code>Arc&lt;Regex&gt;</code> (mã nguồn regex được giữ dưới dạng chuỗi — bên tiêu thụ IPC tự biên dịch ở phía mình); <code>ModifierDetail</code> mang tập trường nhỏ nhất mà giao diện cần cho từng công cụ sửa đổi (size: <code>{op, bytes}</code>, date: <code>{op, epoch_day}</code> hoặc <code>{name}</code>, ext: <code>{extensions}</code>, attrib: <code>{letters}</code>, path/parent/child/similar: <code>{needle}</code>, các biến thể âm thanh: <code>{op, value}</code>, dành sẵn: <code>{value}</code>). <code>parse_to_report</code> không bao giờ trả về <code>Err</code> — ngay cả nguồn rỗng cũng cho ra một báo cáo đầy đủ; với <code>--strict-everything</code>, nó quét trước luồng token và báo <em>mọi</em> vi phạm về công cụ sửa đổi / tiền tố ống kính chỉ có ở Freally trong một lượt (thay vì dừng ở lỗi đầu tiên như <code>parse_with</code>). Đường nóng (sổ sách của bộ phân tích + <code>tokenize</code>) không đổi — các kiểu mới đều được suy ra. Thay đổi bên trong bộ phân tích: <code>Token</code> có thêm trường <code>byte_len: usize</code>, để lớp báo cáo có thể tổng hợp khoảng vị trí của từng token mà không phải tách token lại. Phụ thuộc lúc chạy mới <code>serde = workspace</code> cho các kiểu mới (vốn đã là phụ thuộc của workspace nhờ bộ nhớ đệm âm thanh của giai đoạn 9). Kiểm thử mới: 67 kiểm thử đơn vị trong <code>freally-query</code> (bộ phân tích + bộ nhớ đệm + bộ tối ưu + báo cáo), 17 ca kiểm thử khói giai đoạn 10 trong <code>tests/smoke/phase_10_query.rs</code> (được xuất lại thành <code>crates/freally-query/tests/phase_10_query.rs</code>), 21 kiểm thử fixture DSL của Freally trong <code>crates/freally-query/tests/freally_dsl.rs</code> (≥200 truy vấn được sinh), 3 kiểm thử tương thích voidtools, gồm cả <code>three_hundred_voidtools_queries_parse</code> mới (≥300 tổng cộng: 120+ chọn thủ công + bộ sinh theo thuật toán). Cổng hồi quy của Quy tắc thường trực #8 là fixture 50 truy vấn nằm trong tập lớn hơn 300+.","changelog.07f1d2595011":"<strong>Sai khác so với Build Guide.</strong> Prompt của giai đoạn 10 viết: “Thay bộ phân tích tùy biến của giai đoạn 5 bằng một ngữ pháp chumsky (hoặc pest).” Chúng tôi chọn <strong>gia cố bộ phân tích đệ quy xuống hiện có</strong> thay vì viết lại, vì bề mặt của giai đoạn 5 là một hợp đồng 1:1 với Everything của voidtools (Quy tắc thường trực #8) với nhiều ca biên — <code>(a)!b</code> được phân tích thành <code>(a) AND !b</code>; <code>regex:</code> chỉ tiêu thụ đến dấu ngoặc / khoảng trắng kế tiếp; <code>attrib:HRA</code> là một <em>tập</em> cờ, không phải chuỗi; việc phân định giữa bộ lọc nhanh <code>audio:</code> và tiền tố ống kính xoay quanh loại của token kế tiếp. Mã hóa lại mọi điểm kỳ quặc bằng API combinator của chumsky 0.10 hoặc trong một ngữ pháp PEG <code>query.pest</code> mà không làm hồi quy fixture 50 truy vấn là rủi ro cao mà lợi ích thấp. Bộ phân tích viết tay đã gia cố đạt mọi mục tiêu của giai đoạn 10 — theo dõi khoảng vị trí từng token qua <code>Token::byte_len</code>, lỗi theo từng token qua <code>ParseReport::errors</code>, chế độ strict-everything, tiền tố ống kính, bộ tối ưu — mà không gây rủi ro nào cho hợp đồng của Quy tắc thường trực #8. Việc mở rộng lên hơn 300 fixture voidtools là một <em>cổng hồi quy</em>, không phải mục tiêu chuyển đổi. Đợt hiệu năng của giai đoạn 13 sẽ đánh giá liệu việc chuyển sang chumsky có đáng không khi đã có số liệu benchmark.","changelog.c2c6adddd634":"<strong>[mọi nền tảng]</strong> Giai đoạn 9: trình trích xuất âm thanh (<code>freally-audio</code>) — bộ giải mã dựa trên symphonia + đo độ to theo EBU R128 (qua crate thuần Rust <code>ebur128 = &quot;0.1&quot;</code>) + tỷ lệ khoảng lặng + dải động, cùng các công cụ sửa đổi <code>lufs:</code> / <code>codec:</code> / <code>length:</code> / <code>rate:</code> / <code>silence:</code> / <code>dr:</code> trong DSL truy vấn. Bề mặt công khai: <code>pub fn analyze_file(path: &amp;Path) -&gt; Result&lt;AudioAttributes, AudioError&gt;</code> cùng <code>analyze_with_opts(path, AnalysisOpts)</code> cho đường hủy hợp tác + hạn mức thời gian; <code>pub trait AudioAttributesProvider</code> (lớp trừu tượng dạng bộ nhớ đệm mà bộ thực thi làm việc cùng); <code>pub struct AudioCache</code> (bộ nhớ đệm JSON trong bộ nhớ + trên đĩa, vô hiệu theo mtime, trích xuất một lượt duy nhất qua <code>Condvar</code>, và hạn mức thời gian cho mỗi lần trích xuất mặc định là <code>DEFAULT_AUDIO_TIME_BUDGET = 5 s</code>, để một tệp âm thanh thù địch không thể lặp vô hạn). <code>AudioAttributes</code> mang <code>codec</code> (id ngắn của symphonia viết thường — <code>flac</code> / <code>mp3</code> / <code>aac</code> / <code>vorbis</code> / <code>pcm_s16</code> / <code>alac</code> / …), <code>sample_rate</code>, <code>channels</code>, <code>bit_depth</code>, <code>duration_ns</code>, <code>lufs_integrated</code>, <code>lufs_short_term_p99</code>, <code>lufs_short_term_p10</code>, <code>peak_dbfs</code> (true peak qua bộ lấy mẫu tăng đa pha 4× của crate ebur128 — đáp ứng đặc tả của Build Guide mà không cần một bộ lọc FIR viết tay), <code>silence_ratio</code> (% mẫu dưới <code>−60 dBFS</code>; tính theo từng mẫu để phép toán không phụ thuộc số kênh — xem hồi quy <code>mono_and_correlated_stereo_report_same_ratio</code>) và <code>dynamic_range_lu</code> (<code>short_term_p99 − short_term_p10</code>; thu về <code>0</code> với các đoạn dưới 3 giây mà cửa sổ trượt ngắn hạn chưa bao giờ đầy, với các phân vị được biểu diễn là <code>f32::NEG_INFINITY</code>, để một truy vấn <code>lufs:&gt;x</code> không bao giờ khớp nhầm). Các trường LUFS / đỉnh giữ được các giá trị không hữu hạn (<code>±∞</code> / <code>NaN</code>) qua vòng đi-về nhờ một hàm hỗ trợ JSON tùy chỉnh <code>lufs_serde</code> dùng ba chuỗi canh (<code>&quot;-inf&quot;</code> / <code>&quot;+inf&quot;</code> / <code>&quot;nan&quot;</code>) — nếu không, hành vi mặc định ghi <code>null</code> cho giá trị không hữu hạn của <code>serde_json</code> sẽ âm thầm làm hỏng bộ nhớ đệm; <code>unknown_sentinel_rejects</code> chặn hồi quy trên nhánh lỗi có kiểu. Số kênh bị giới hạn cứng ở <code>MAX_CHANNELS = 64</code>, để một header sai dạng không thể ép những lần cấp phát khổng lồ theo từng kênh trước khi hộp cát kịp phát hiện. Bộ phân tích trả về các lỗi có kiểu <code>AudioError::NotAudio</code> / <code>Probe</code> / <code>Decode</code> / <code>Empty</code> / <code>Unsupported</code> / <code>Cancelled</code> / <code>Json</code> / <code>NonUtf8Path</code>. DSL truy vấn thêm các bộ phân tích <code>parse_audio_lufs</code> / <code>_codec</code> / <code>_length</code> / <code>_rate</code> / <code>_silence</code> / <code>_dr</code>, dùng lại hình dạng <code>split_op</code> của giai đoạn 5 (<code>&lt;</code> / <code>&lt;=</code> / <code>&gt;</code> / <code>&gt;=</code> / <code>=</code> / để trống = <code>==</code>); <code>length:</code> nhận giây, <code>mm:ss</code> và <code>hh:mm:ss</code> (có chặn tràn phút nên <code>length:1:90</code> bị từ chối); <code>rate:</code> nhận đơn vị <code>Hz</code> / <code>kHz</code>; <code>silence:</code> nhận cả tỷ lệ lẫn phần trăm; <code>dr:</code> từ chối giá trị âm; <code>duration:</code> là bí danh của <code>length:</code> và <code>samplerate:</code> là bí danh của <code>rate:</code>, theo thói quen của người dùng Everything (voidtools). Bộ thực thi thêm <code>pub fn execute_with_audio(idx, similarity_opt, audio_opt, q, opts)</code>, hàm này phát hiện các truy vấn có phần âm thanh qua <code>has_audio_anywhere</code>, yêu cầu một <code>AudioAttributesProvider</code> (nếu không có sẽ trả về <code>QueryError::AudioProviderUnavailable</code> — một lỗi có kiểu thay vì kết quả rỗng, khớp với hợp đồng <code>SimilarityIndexUnavailable</code> của giai đoạn 6), và với từng hàng thì tra <code>AudioAttributes</code> qua nhà cung cấp trước khi chạy <code>eval_audio_predicate</code> trên các thuộc tính đã lưu đệm. Các tổ hợp âm thanh với ống kính tương đồng (<code>similar:bassdrop codec:flac length:&gt;3:00</code>) chạy trọn vẹn qua cùng đường thực thi. Các lần kiểm tra hủy hợp tác diễn ra một lần cho mỗi gói của symphonia (<code>Ordering::Acquire</code> trên biến nguyên tử hủy, khớp với lần lật <code>Release</code> từ bộ giám sát); <code>SampleBuffer</code> được đặt lại khi gặp <code>SymphoniaError::ResetRequired</code>, để gói kế tiếp cấp phát mới theo <code>capacity()</code> của bộ giải mã mới (tránh panic do khẳng định dung lượng của <code>copy_interleaved_typed</code>). <code>TimeBudgetSupervisor</code> là một luồng tách rời, lật cờ hủy khi hết hạn mức và tự dọn dẹp qua cờ <code>done</code> được lật trong <code>Drop</code> của bộ giám sát. Phụ thuộc lúc chạy mới (đều có giấy phép dễ dãi, nằm trong danh sách cho phép của deny.toml): <code>symphonia = &quot;0.5&quot;</code> (MPL-2.0; bộ giải mã âm thanh thuần Rust; các tính năng được bật: aac, alac, flac, isomp4, mp3, ogg, pcm, vorbis, wav, aiff, opt-simd — Opus cố ý bị tắt vì các vector kiểm thử ở thượng nguồn mang dữ liệu kiểu GPL mà chính sách deny cấm; sẽ xem lại khi có crate Opus chỉ dùng MIT), <code>ebur128 = &quot;0.1&quot;</code> (MIT/Apache-2.0; bản chuyển thuần Rust của libebur128), cùng các phụ thuộc sẵn có của workspace (<code>serde_json</code>, <code>parking_lot</code>, <code>tracing</code>, <code>thiserror</code>, <code>tempfile</code> cho kiểm thử). Kiểm thử khói <code>tests/smoke/phase_09_audio.rs</code> (10 ca — được xuất lại trong <code>crates/freally-query/tests/phase_09_audio.rs</code>) bao phủ vòng đi-về của bộ phân tích trên các fixture WAV tổng hợp (sóng sin 1 kHz ở −23 dBFS đọc ra ≈ −23 LUFS trong phạm vi ±1 LU; khoảng lặng thuần đọc ra <code>silence_ratio &gt; 0.99</code> và LUFS tích hợp = <code>f32::NEG_INFINITY</code>), vòng đi-về trên đĩa của bộ nhớ đệm âm thanh + vô hiệu theo mtime, việc phân tích cả sáu công cụ sửa đổi âm thanh, ví dụ ghép <code>lufs:&lt;-14 codec:flac length:&gt;3:00</code> từ prompt của Build Guide, cổng có kiểu <code>AudioProviderUnavailable</code>, việc lọc trọn vẹn bằng <code>execute_with_audio</code> trên một <code>Index</code> trong bộ nhớ chứa các tệp âm thanh tổng hợp (sin to + sin nhỏ kiểm chứng cả hai chiều của <code>lufs:&gt;-20</code> / <code>lufs:&lt;-20</code>), việc khớp epsilon của <code>silence:=</code> với âm thanh hoàn toàn im lặng, nhánh <code>NullProvider</code> (công cụ sửa đổi âm thanh không khớp gì thay vì panic), và các đường hủy giữa chừng của bộ giám sát bằng cờ hủy / hạn mức thời gian. Giai đoạn 9 không thêm chuỗi giao diện mới nào — các công cụ sửa đổi có dạng lệnh (như <code>size:</code> / <code>ext:</code>); <code>xtask i18n-lint</code> vẫn xanh ở 5 khóa × 17 ngôn ngữ không phải ngôn ngữ nguồn.","changelog.138d44119faa":"<strong>Sai khác so với Build Guide.</strong> Hai ghi chú nội tuyến về các phụ thuộc không khớp nguyên văn với Build Guide:","changelog.c49ebee11cd1":"<strong>Bộ giải mã âm thanh</strong>: Build Guide nêu “symphonia” — được dùng đúng như vậy. Build Guide cũng nêu “ebur128 (libebur128)”; chúng tôi dùng crate thuần Rust <code>ebur128 = &quot;0.1&quot;</code> (bản chuyển của Sebastian Dröge) thay vì thư viện C, để giữ workspace thuần Rust và tránh các bước cài thư viện hệ thống trên CI ba hệ điều hành.","changelog.fb9344590719":"<strong>Hỗ trợ Opus</strong>: Build Guide nêu Opus trong số các định dạng được hỗ trợ. Chúng tôi bỏ nó ở v0.19.84 vì tính năng <code>opus</code> của symphonia kéo theo các vector kiểm thử kiểu GPL, xung đột với lệnh cấm AGPL/GPL của <code>cargo-deny</code>. Một vùng chứa OGG mang Opus sẽ hiện ra dưới dạng lỗi <code>Probe</code>/<code>Decode</code> thay vì một kết quả khớp gây hiểu lầm; sẽ xem lại khi có bộ giải mã Opus chỉ dùng MIT. Thêm hai ghi chú: <strong>Bộ kiểm tra tuân thủ EBU R128</strong>: prompt của giai đoạn 9 nêu “các đoạn tham chiếu đã biết LUFS (bộ kiểm tra tuân thủ EBU R128), dung sai ±0.1 LU” làm cổng kiểm tra. Kiểm thử khói đi kèm một bộ thử sóng sin tổng hợp ở ±1 LU (sóng sin 1 kHz ở −23 dBFS đọc ra ≈ −23 LUFS sau trọng số K); các đoạn EBU đã công bố không được nhúng vì workspace hướng tới việc không có fixture nhị phân nào trong cây mã. Đợt hiệu năng của giai đoạn 13 sẽ thêm bộ kiểm tra tuân thủ vào ma trận CI khi đã quyết định cách xử lý fixture nhị phân. <strong>Kết nối hộp cát</strong>: bộ phân tích âm thanh <em>không</em> chạy bên trong <code>Sandbox</code> của <code>sandbox-extractors</code> thuộc giai đoạn 7 — bộ giám sát đó được thiết kế cho các trình trích xuất <code>Extractor</code> (dạng văn bản), còn âm thanh tạo ra <code>AudioAttributes</code> có cấu trúc. Crate âm thanh có <code>TimeBudgetSupervisor</code> riêng với cùng hạn mức mặc định 5 giây; hợp đồng hủy hợp tác giống hệt (nạp <code>Acquire</code> trên biến nguyên tử hủy cho mỗi gói). Việc cách ly bằng tiến trình con cho các tệp âm thanh thật sự thù địch thuộc cùng đợt đánh giá ở giai đoạn 13, vốn bao phủ cả đường giải mã PDF không hợp tác.","changelog.1eeff18b7504":"<strong>[mọi nền tảng]</strong> Giai đoạn 8: các trình trích xuất tài liệu (<code>freally-extractors::extractors</code>) — sáu trình trích xuất cắm được, đăng ký với <code>Pipeline</code> của giai đoạn 7, cùng các hàm hỗ trợ <code>register_all(builder)</code> / <code>default_pipeline()</code> nối chúng theo thứ tự điều phối. Phạm vi: <strong>(1) Văn bản thuần + Markdown</strong> — đọc tối đa <code>PLAIN_TEXT_CAP_BYTES = 5 MiB</code>, phát hiện dấu thứ tự byte UTF-8 / UTF-16 LE / UTF-16 BE, giải mã phần thân sang UTF-8 và đẩy văn bản đã giải mã vào sink; trình trích xuất này cũng là đường hứng mọi tệp mà không trình trích xuất nào khác nhận (danh sách phần mở rộng cho phép <code>.txt</code> / <code>.text</code> / <code>.md</code> / <code>.markdown</code> / <code>.mkd</code> / <code>.log</code> / <code>.rst</code> / <code>.adoc</code> / <code>.asciidoc</code> / <code>.rtf</code> cùng heuristic <code>looks_like_text</code> trên các byte đầu, chấp nhận 1 byte NUL lạc và từ chối từ 2 trở lên). <strong>(2) PDF</strong> — <code>pdf-extract = &quot;0.10&quot;</code> (MIT, thuần Rust, hệ sinh thái pdf-rs) phân tích tài liệu và xuất văn bản với <code>U+000C</code> giữa các trang, để đoạn trích tìm kiếm có thể dẫn số trang; PDF được mã hóa / có mật khẩu trả về <code>ExtractError::Unsupported(...)</code>, đầu vào sai dạng trả về <code>ExtractError::Malformed(...)</code>. <strong>(3) Office</strong> — <code>XlsxExtractor</code> dùng <code>calamine = &quot;0.34&quot;</code> (MIT) và xuất mỗi ô không rỗng thành một dòng dạng <code>Sheet1!A1=value</code>; <code>DocxExtractor</code> và <code>PptxExtractor</code> phân tích OOXML trực tiếp qua <code>zip = &quot;5&quot;</code> + <code>quick-xml = &quot;0.39&quot;</code>, nên không phải phát hành phụ thuộc <code>ooxmlsdk-rs</code> (xem ghi chú sai khác). docx vẽ các tiêu đề thành Markdown (<code># Title</code>, <code>## Sub</code>, …) và làm phẳng bảng thành các dòng <code>| cell | cell |\\n</code>; pptx duyệt các trang chiếu theo thứ tự số và thêm tiền tố <code># Slide N: &lt;title&gt;</code> cho từng trang. <strong>(4) Mã nguồn</strong> — runtime <code>tree-sitter = &quot;0.25&quot;</code> + 32 crate ngữ pháp bao phủ Rust, Python, JS, TS/TSX, Go, Java, C, C++, C#, Ruby, Bash, Lua, PHP, Kotlin, Scala, Swift, Haskell, OCaml, Elixir, Erlang, Clojure, Elm, Dart, R, Julia, Zig, Nix, TOML, YAML, JSON, HTML, CSS, SQL. Mỗi lần phân tích xuất các phần <code>[lang]</code> / <code>[identifiers]</code> / <code>[strings]</code> / <code>[comments]</code>; định danh được khử trùng lặp, chuỗi + chú thích giữ nguyên dạng nguyên văn để <code>content:&quot;hello world&quot;</code> khớp với mã nguồn gốc. Các lần kiểm tra hủy hợp tác diễn ra sau mỗi <code>CANCEL_CHECK_EVERY = 1024</code> nút, để bộ giám sát có thể ngắt một lượt duyệt cây dài. <strong>(5) Xem lướt tệp nén</strong> — <code>zip = &quot;5&quot;</code> + <code>sevenz-rust2 = &quot;0.21&quot;</code> + <code>tar = &quot;0.4&quot;</code> liệt kê các mục mà không giải nén byte ra đĩa; đầu ra có dạng <code>archive.zip!path/to/inner.txt size=1234</code> cho mỗi mục (daemon chuyển đường dẫn ảo này cho trình lập chỉ mục, để tìm <code>inner.txt</code> sẽ khớp với nội dung tệp nén). Giới hạn cứng <code>MAX_ENTRIES = 100_000</code> cho mỗi tệp nén; một tệp tar chứa 1M tệp sẽ không đốt cạn sink và hạn mức thời gian. <strong>(6) Dữ liệu có cấu trúc</strong> — <code>serde_json</code> (workspace) + <code>csv = &quot;1&quot;</code> + <code>serde_yaml_ng = &quot;0.10&quot;</code> làm phẳng thành các dòng <code>key=value</code>: JSON / YAML dùng khóa có dấu chấm (<code>address.zip=10001</code>) với <code>[idx]</code> cho mảng; CSV xuất <code>header=value</code> cho mỗi hàng không phải tiêu đề, quay về <code>col0=value</code> khi thiếu tiêu đề; YAML nhiều tài liệu thêm tiền tố <code>[doc=N]</code> cho mỗi tài liệu. Kiểm thử khói <code>tests/smoke/phase_08_doc_extractors.rs</code> (16 ca) bao phủ việc đăng ký <code>default_pipeline()</code>, thứ tự điều phối (xlsx thắng archive-peek với <code>.xlsx</code>; archive-peek thắng với <code>.zip</code> thường; PDF thắng nhờ magic <code>%PDF-</code>; văn bản thuần hứng <code>.log</code>), việc bỏ BOM của văn bản thuần, làm phẳng JSON / CSV / YAML, liệt kê zip với đường dẫn ảo, chuyển kiểu tiêu đề của docx → Markdown, thứ tự trang chiếu của pptx, và việc bắt định danh / chuỗi / chú thích của trình trích xuất mã. Phụ thuộc lúc chạy mới (đều có giấy phép dễ dãi, nằm trong danh sách cho phép của deny.toml): <code>pdf-extract = &quot;0.10&quot;</code> (MIT), <code>calamine = &quot;0.34&quot;</code> (MIT/Apache-2.0), <code>zip = &quot;5&quot;</code> (MIT), <code>quick-xml = &quot;0.39&quot;</code> (MIT), <code>sevenz-rust2 = &quot;0.21&quot;</code> (Apache-2.0), <code>tar = &quot;0.4&quot;</code> (MIT/Apache-2.0), <code>csv = &quot;1&quot;</code> (Unlicense/MIT), <code>serde_yaml_ng = &quot;0.10&quot;</code> (MIT/Apache-2.0), <code>tree-sitter = &quot;0.25&quot;</code> (MIT) cùng 32 crate ngữ pháp kể trên (pha trộn MIT/Apache-2.0 — giấy phép của mọi ngữ pháp đều nằm trong danh sách cho phép của deny.toml).","changelog.eeeac6857769":"<strong>Sai khác so với Build Guide.</strong> Hai phụ thuộc được nêu tên đã bị thay, để giữ CI 3 hệ điều hành luôn xanh và lịch 18 ngôn ngữ đúng tiến độ:","changelog.56e5dde6f237":"<strong>Xem lướt tệp nén:</strong> Build Guide nêu <code>compress-tools</code> (libarchive). libarchive là thư viện hệ thống — máy CI Windows không có sẵn nó và việc điều phối <code>vcpkg</code> sẽ chặn cả giai đoạn. Chúng tôi dùng bộ ba thuần Rust (<code>zip</code> + <code>sevenz-rust2</code> + <code>tar</code>); kết quả vẫn là đầu ra đường dẫn ảo <code>archive.ext!entry size=N</code> mà Build Guide yêu cầu, không cần phụ thuộc hệ thống.","changelog.bd47ec1aa5f2":"<strong>Office:</strong> Build Guide nêu <code>ooxmlsdk-rs</code> cho docx + pptx. Tính đến 2026-Q1, crate đó không còn được bảo trì trên crates.io và thiếu hỗ trợ Rust-2024. Office Open XML là zip + XML, nên chúng tôi đọc trực tiếp bằng <code>zip</code> + <code>quick-xml</code>. Kết quả thực: bề mặt tấn công nhỏ hơn (trình lập chỉ mục chỉ đọc <em>văn bản</em>, không đọc kiểu dáng / bố cục / đối tượng nhúng) và bớt một phụ thuộc phải ghim. Thêm hai ghi chú: <strong>Dockerfile</strong> chưa có ngữ pháp trong cây mã vì <code>tree-sitter-dockerfile</code> duy nhất đã phát hành (0.2.0) vẫn gắn với runtime tree-sitter 0.20, xung đột với runtime 0.25 của chúng tôi qua quy tắc <code>links = &quot;tree-sitter&quot;</code> của cargo; hiện tại Dockerfile rơi xuống trình trích xuất văn bản thuần, và chúng tôi sẽ xem lại khi ngữ pháp được cập nhật. <strong>Sự hợp tác của PDF</strong> tính trên toàn tài liệu thay vì từng trang, vì <code>pdf-extract</code> chặn trong lúc phân tích — một PDF nặng vượt hạn mức thời gian của hộp cát sẽ kết thúc bằng việc rò rỉ luồng worker (hợp đồng đã ghi của hộp cát cho các trình trích xuất không hợp tác); cách ly bằng tiến trình con là đợt đánh giá của giai đoạn 13.","changelog.9aec97cffe7b":"<strong>[mọi nền tảng]</strong> Giai đoạn 7: khung trình trích xuất định dạng (<code>freally-extractors</code>) — trait, bộ điều phối, hộp cát cho từng lần trích xuất, hàng đợi trích xuất có giới hạn, kho blob định địa chỉ theo nội dung, và chế độ theo từng trình trích xuất (Lười / Háo hức / Đã tắt). Bề mặt công khai khớp với prompt giai đoạn 7 của Build Guide: <code>pub trait Extractor: Send + Sync { fn id(&amp;self) -&gt; ExtractorId; fn matches(&amp;self, path: &amp;Path, magic: &amp;[u8]) -&gt; bool; fn extract(&amp;self, path: &amp;Path, sink: &amp;mut TextSink) -&gt; Result&lt;ExtractionStats, ExtractError&gt;; }</code>. <code>Pipeline::builder().register(...).build()</code> là bước đăng ký lúc biên dịch; <code>Pipeline::dispatch_path(path)</code> đọc tối đa <code>MAGIC_HEAD_BYTES = 32</code> từ đầu tệp ứng viên và duyệt các trình trích xuất đã đăng ký theo thứ tự đăng ký, bỏ qua những cái có <code>ExtractorMode</code> hiệu lực là <code>Disabled</code>; <code>Pipeline::replace_settings</code> cho phép daemon đổi cài đặt ngay khi đang chạy mà không cần khởi động lại. Phương thức trait <code>Extractor::extract</code> nhận một <code>&amp;mut TextSink</code> (bộ ghi byte có giới hạn, với cờ hủy của hộp cát được dẫn qua <code>is_cancelled()</code>); các lần ghi vượt giới hạn văn bản cho mỗi lần trích xuất trả về <code>SinkOverflow</code>, mà trình trích xuất gộp thành <code>ExtractError::OutputTooLarge</code>. <code>Sandbox::execute(Arc&lt;dyn Extractor&gt;, PathBuf)</code> tạo một luồng worker gọi trình trích xuất, còn luồng gọi đóng vai bộ giám sát — <code>mpsc::sync_channel::recv_timeout</code> thăm dò mỗi nhịp (mặc định 100 ms), áp hạn mức thời gian 5 giây bằng cách lật cờ hủy và chờ một khoảng ân hạn hủy (mặc định 250 ms) trước khi trả về <code>SandboxError::TimeBudget</code>, bất kể worker đã bỏ cuộc hay chưa (trình trích xuất không hợp tác làm rò rỉ một luồng worker mỗi lần vi phạm — hợp đồng đã ghi; giai đoạn 13 đánh giá cách ly bằng tiến trình con cho các định dạng thù địch của bên thứ ba); bộ canh RSS đọc dòng <code>VmRSS:</code> của <code>/proc/self/status</code> trên Linux, <code>GetProcessMemoryInfo</code> trên Windows, và không làm gì trên macOS / Unix khác (prompt giai đoạn 7: “không làm gì (macOS — dựa vào hạn mức thời gian)”). Các trình trích xuất hợp tác kiểm tra <code>sink.is_cancelled()</code> giữa các phần việc lớn và trả về <code>ExtractError::Cancelled</code>; hộp cát gộp lại thành <code>SandboxError::TimeBudget</code> hoặc <code>SandboxError::MemoryCeiling</code> dựa trên lý do vi phạm mà nó đã ghi nhận. <code>ExtractionQueue</code> là một <code>BinaryHeap&lt;Entry&gt;</code> có giới hạn với khóa <code>(mtime_ns desc, FIFO seq)</code>, để tệp vừa được chạm tới được điều phối trước và các mục cùng mtime ra theo thứ tự chèn; <code>try_push</code> trả về <code>QueueError::Full(capacity)</code> khi heap đạt dung lượng và <code>QueueError::Closed</code> sau <code>close()</code>, theo cùng cách đóng an toàn như <code>EventQueue</code> của giai đoạn 4 (<code>closed</code> nằm trong cùng <code>Mutex</code> với heap, để một lệnh <code>close()</code> đồng thời không thể chạy đua với phép kiểm tra “heap có rỗng không?” của bên đang chờ). <code>BlobStore::open(&lt;index_root&gt;/extracted)</code> tạo thư mục gốc; <code>put(content)</code> tính <code>BlobId = blake3(content)</code> (32 B → 64 ký tự hex), mã hóa nội dung bằng zstd (mặc định mức 3 — đợt hiệu năng của giai đoạn 13 đánh giá việc hạ xuống mức 1 nếu nén chiếm phần lớn thời gian trích xuất), và ghi nguyên tử qua tệp tạm + đổi tên trong cùng thư mục shard tới <code>&lt;root&gt;/&lt;first2hex&gt;/&lt;full-hex&gt;</code>; <code>get(id)</code> ánh xạ bộ nhớ khung đã nén qua <code>memmap2::Mmap</code> và trả về <code>Vec&lt;u8&gt;</code> đã giải nén; <code>for_each(|id|)</code> duyệt kho đang dùng, bỏ qua các phần dở <code>.tmp-*</code> và tên tệp không phải hex ở mức log <code>warn</code>. Việc khử trùng lặp bất biến trên <code>put</code> là ngầm định và theo địa chỉ nội dung; <code>BlobStoreStats</code> (<code>puts</code> / <code>dedup_hits</code> / <code>get_hits</code> / <code>get_misses</code> / <code>bytes_written</code> / <code>bytes_decompressed</code>) cung cấp dữ liệu cho khung trạng thái của daemon. <code>ExtractorMode::{Eager, Lazy, Disabled}</code> mặc định là <code>Lazy</code> (chỉ mục vừa khởi tạo không đốt CPU vào việc trích xuất nội dung trước khi người dùng tỏ ra quan tâm đến tìm kiếm nội dung); <code>PipelineSettings</code> mang mặc định toàn cục cùng một <code>HashMap&lt;String, ExtractorMode&gt;</code> các ghi đè theo từng trình trích xuất (khóa theo <code>ExtractorId::as_str()</code> để tệp JSON ổn định qua các lần nâng phiên bản crate), các hạn mức thời gian / bộ nhớ / giới hạn sink, và dung lượng hàng đợi. Cài đặt đi-về qua <code>serde_json</code> gọn gàng — hộp thoại cài đặt của giai đoạn 12 sẽ quản lý định dạng tệp JSON. Phụ thuộc lúc chạy mới (đều có giấy phép dễ dãi, nằm trong danh sách cho phép của deny.toml): <code>zstd = &quot;0.13&quot;</code> (BSD-3-Clause; vốn đã được kéo vào qua Tantivy, khai báo trực tiếp ở đây cho đường nén/giải nén của kho blob), <code>memmap2 = &quot;0.9&quot;</code> (MIT/Apache-2.0; vốn đã được kéo vào qua <code>freally-index</code>, khai báo trực tiếp ở đây cho việc đọc mmap của kho blob), <code>blake3 = &quot;1&quot;</code> (CC0/Apache-2.0; cùng nguyên hàm định địa chỉ theo nội dung mà giai đoạn 4 + giai đoạn 6 đã dùng), <code>parking_lot = &quot;0.12&quot;</code> (MIT/Apache-2.0; khớp với nguyên hàm khóa của phần còn lại trong workspace), <code>serde_json = workspace</code> (MIT/Apache-2.0; tuần tự hóa cài đặt), <code>windows-sys = &quot;0.59&quot;</code> với các tính năng <code>Win32_System_ProcessStatus</code> + <code>Win32_System_Threading</code> trên Windows cho <code>GetProcessMemoryInfo</code>, và <code>libc = &quot;0.2&quot;</code> trên Linux + macOS (phân tích chỉ đọc <code>/proc/self/status</code> trên Linux; trên macOS chỉ có mặt để dành cho các hook RSS sau này). Kiểm thử khói <code>tests/smoke/phase_07_extractor_fw.rs</code> (17 ca) bao phủ việc điều phối của Pipeline (phần mở rộng + magic + cái khớp đầu tiên thắng + bỏ qua cái bị tắt + đọc magic của tệp ngắn), Sandbox (hạn mức thời gian hợp tác kích hoạt trong hạn mức + ân hạn + truyền thẳng lỗi của trình trích xuất + đường thành công), Queue (ưu tiên + áp lực ngược + đóng hàng đợi giải phóng pop đang chặn), BlobStore (đi-về + khử trùng lặp + bố cục + lưu bền + đi-về hex), và đi-về JSON của Settings.","changelog.d64d1c8e1432":"<strong>[mọi nền tảng]</strong> Giai đoạn 6: ống kính tương đồng tên tệp (<code>freally-similarity</code>) — chỉ mục tên tệp gần trùng lặp dùng MinHash trên bigram + LSH 16×8. <code>SimilarityIndex::open(dir)</code> mở hoặc tạo <code>minhash.idx</code> đặt tại thư mục được cung cấp; <code>upsert(file_id, name)</code> chuyển đầu vào thành chữ thường, bỏ phần mở rộng ở cuối, tính một chữ ký MinHash <code>[u64; 128]</code> qua một họ hàm băm tuyến tính tất định (các cặp <code>(a, b)</code> được gieo bằng SplitMix64, cố định <code>MINHASH_SEED = 0x534F5552_43455252</code>), và chèn hàng vào 16 dải LSH, mỗi dải 8 mã băm; <code>remove(file_id)</code> đánh dấu xóa hàng và gỡ nó khỏi mọi dải, để một mục dải cũ không thể làm lộ ra một kết quả khớp đã bị xóa. <code>apply(&amp;[JournalEvent])</code> tiêu thụ các sự kiện Create / Rename / Delete (Modify và AttrChange không làm gì vì tên tệp không đổi) và suy lại <code>file_id</code> qua cùng phép cắt <code>blake3(OsStr-bytes)[..8]</code> mà <code>freally-index</code> dùng, để một <code>SimilarityHit::file_id</code> đi-về qua <code>Index::store::get_many</code> gọn gàng. <code>candidates(query, &amp;SimilarityOpts)</code> chạy tra cứu LSH, chấm điểm từng ứng viên bằng ước lượng Jaccard, loại các kết quả dưới ngưỡng (mặc định <code>DEFAULT_JACCARD_THRESHOLD = 0.30</code>), sắp xếp theo Jaccard giảm dần với các trường hợp hòa được phân định theo <code>file_id</code> tăng dần để đầu ra tất định, và cắt bớt theo <code>candidate_cap</code>. <code>flush()</code> ghi lại <code>minhash.idx</code> một cách nguyên tử qua tệp tạm + đổi tên — <code>[Header — 32 B] [Heap] [Rows: file_id u64 + name_off u32 + name_len u32 + signature [u64; 128]]</code> — magic <code>SRC-MNHS</code>, phiên bản 1; <code>open()</code> dựng lại bản đồ dải từ chữ ký của mỗi hàng còn sống để định dạng tệp trên đĩa luôn gọn (ghi chú cho đợt hiệu năng giai đoạn 13: lưu thẳng bản đồ dải khi SA-IS được đưa vào). DSL truy vấn (<code>freally-query</code>) giờ phân tích <code>similar:&lt;needle&gt;</code> thành biến thể mới <code>ModifierKind::Similar(String)</code> — được đưa ra khỏi tập <code>Reserved</code> của giai đoạn 5; một chuỗi tìm rỗng (<code>similar:</code>) báo lỗi <code>ParseError::InvalidModifierValue</code>. Điểm vào mới <code>execute_with(idx, similarity, q, opts)</code> định tuyến mọi truy vấn mang công cụ sửa đổi <code>Similar</code> ở cấp cao nhất qua <code>SimilarityIndex</code> được cung cấp (ứng viên LSH → hydrate từ SQLite → lọc các vị từ còn lại → sắp xếp Jaccard giảm dần, trừ khi người dùng đã chủ động chọn một <code>SortSpec</code> khác mặc định); <code>execute(idx, q, opts)</code> cũ giờ là lớp bọc mỏng quanh <code>execute_with(idx, None, …)</code>, trả về lỗi có kiểu <code>QueryError::SimilarityIndexUnavailable</code> khi gặp truy vấn <code>similar:</code>, để bên gọi thấy một thông báo rõ ràng thay vì kết quả rỗng. <code>similar:</code> bị vùi bên trong <code>OR</code> / <code>NOT</code> / AND lồng nhau trả về <code>QueryError::UnsupportedSimilarPosition</code> — giai đoạn 6 phát hành bản đầu chỉ hỗ trợ cấp cao nhất, và giới hạn này được gỡ bởi lượt tối ưu của giai đoạn 10. Biến thể mới <code>SortField::Relevance</code> sắp xếp theo Jaccard giảm dần khi có truy vấn tương đồng và quay về thứ tự <code>Name</code> với truy vấn không phải tương đồng (khớp với ngữ nghĩa “Sắp xếp theo mức độ liên quan” của Everything (voidtools); giao diện giai đoạn 11 đưa tùy chọn này ra). Chữ ký tên tệp được tính trên <em>phần gốc</em> của tên (đã bỏ phần mở rộng), để người dùng gõ <code>similar:report-final</code> khớp gọn với <code>report-final.pdf</code> đã lập chỉ mục mà không bị phạt 4-5 bigram vì <code>.pdf</code> ở cuối; tên đầy đủ viết thường vẫn nằm trong heap để chẩn đoán. Các cổng của đặc tả giai đoạn 6: kho ngữ liệu tổng hợp 5 000 tên (hạt giống SplitMix64 tất định) với 50 bản gần trùng lặp đã biết (tăng hậu tố <code>-v2</code> + nối thẻ <code>-draft</code> + xóa 1 ký tự, được chọn tránh xa điểm gãy của LSH ở Jaccard ≈ 0.73) đạt ngưỡng truy hồi 95 % của đặc tả (<code>crates/freally-similarity/tests/recall.rs</code>); một kiểm thử khói <code>tests/smoke/phase_06_similarity.rs</code> bao phủ các bất biến phân tích/định tuyến/kết hợp/lưu trữ/vị trí lỗi. Phụ thuộc lúc chạy mới (đều có giấy phép dễ dãi, nằm trong danh sách cho phép của deny.toml): <code>blake3 = &quot;1&quot;</code> (vốn đã được kéo vào qua <code>freally-index</code>; khai báo trực tiếp ở đây để suy ra file_id); chuỗi <code>parking_lot</code> / <code>thiserror</code> / <code>tracing</code> / <code>freally-journal</code> sẵn có.","changelog.1b0bc0f992e4":"<strong>[mọi nền tảng]</strong> Khung ban đầu của giai đoạn 0: workspace Cargo; vỏ giao diện Tauri 2 + Svelte 5 ở 1100×720, nền tối; 18 tệp <code>.ftl</code> khung cho các ngôn ngữ; <code>xtask</code> (<code>i18n-lint</code>, <code>third-party-notices</code>, <code>icon-build</code>, <code>release</code>); CI GitHub Actions cho 3 hệ điều hành; chính sách giấy phép trong <code>deny.toml</code> (AGPL bị cấm tuyệt đối); bộ biểu tượng kính lúp màu xanh baby. Thẻ công khai đầu tiên sẽ là <strong>v0.19.84</strong>.","changelog.24697757938e":"<strong>[chỉ Windows]</strong> Giai đoạn 1: trình theo dõi nhật ký USN của NTFS (<code>freally-journal-win</code>): <code>JournalSubscriber::open</code> truy vấn nhật ký qua <code>FSCTL_QUERY_USN_JOURNAL</code>, <code>bootstrap()</code> liệt kê MFT qua <code>FSCTL_ENUM_USN_DATA</code>, <code>subscribe()</code> truyền các sự kiện tăng dần qua <code>FSCTL_READ_USN_JOURNAL</code>, và một con trỏ theo từng ổ đĩa (số sê-ri ổ đĩa + ID nhật ký + USN kế tiếp) được lưu tại <code>%LOCALAPPDATA%\\Freally\\cursors\\&lt;serial&gt;.json</code> với cách lưu nguyên tử bằng đổi tên. Các cờ lý do được ánh xạ sang <code>JournalEvent::{Create, Modify, Delete, Rename, AttrChange}</code>. Sẽ được cân bằng bởi trình theo dõi FSEvents của macOS ở giai đoạn 2 và trình theo dõi inotify/fanotify của Linux ở giai đoạn 3.","changelog.b71505a013b6":"<strong>[chỉ Windows]</strong> Nối <code>freally-indexd</code> với Service Control Manager: các lệnh con <code>install</code> / <code>uninstall</code> / <code>service</code> đăng ký và chạy dịch vụ Windows <code>Freally-Indexd</code> (tự khởi động, chấp nhận lệnh dừng từ SCM). Giai đoạn 4 lấp đầy trình theo dõi theo từng ổ đĩa + lõi chỉ mục bên trong thân dịch vụ.","changelog.cc1fb2dcf2b9":"<strong>[chỉ macOS]</strong> Giai đoạn 2: trình theo dõi nhật ký FSEvents (<code>freally-journal-mac</code>): <code>JournalSubscriber::open</code> phân giải một thư mục gốc theo dõi tuyệt đối, ghi lại <code>stat.st_dev</code> + <code>statfs.f_fstypename</code> của nó, và nạp (hoặc tạo trong lần chạy đầu) một con trỏ cho từng điểm theo dõi tại <code>~/Library/Application Support/Freally/cursors/&lt;root_hash&gt;.json</code>. <code>bootstrap()</code> duyệt cây và phát các sự kiện <code>JournalEvent::Create</code> tổng hợp. <code>subscribe()</code> tạo một luồng CFRunLoop riêng chạy <code>FSEventStreamCreate(latency=0.5s, FileEvents | NoDefer | UseCFTypes | WatchRoot)</code>, phân loại mặt nạ cờ của từng lô qua bảng cờ FSEvents → <code>JournalEvent</code>, thực hiện <strong>ghép cặp đổi tên theo từng lô</strong> (ghép hai nửa của một cặp <code>ItemRenamed</code> theo inode), quét lại tại chỗ các cây con khi gặp <code>MustScanSubDirs</code>, và lưu <code>last_event_id</code> để tiếp tục sau khi khởi động lại. Các cặp đổi tên nằm ở hai lô khác nhau bị suy giảm thành <code>Delete + Create</code> (một ghi chú cho đợt hiệu năng giai đoạn 13). Phụ thuộc lúc chạy <code>core-foundation = &quot;0.10&quot;</code>, <code>core-foundation-sys = &quot;0.8&quot;</code>, <code>fsevent-sys = &quot;4&quot;</code>, <code>libc = &quot;0.2&quot;</code> — đều MIT/Apache-2.0, nằm trong danh sách cho phép của deny.toml.","changelog.4fcde431e77b":"<strong>[chỉ macOS]</strong> Nối <code>freally-indexd</code> với launchd agent: các lệnh con <code>install</code> / <code>uninstall</code> / <code>service</code> đăng ký và chạy một launchd agent theo người dùng tại <code>~/Library/LaunchAgents/io.mikeweaver.freally.indexd.plist</code> với <code>RunAtLoad=true</code> + <code>KeepAlive=true</code>. Giai đoạn 4 lấp đầy trình theo dõi theo từng thư mục gốc + lõi chỉ mục bên trong thân agent. Chế độ chạy tiền cảnh <code>run --root &lt;path&gt;</code> in các sự kiện FSEvents ra stdout để kiểm tra thủ công / bằng kiểm thử khói.","changelog.051c4dd1753a":"<strong>[mọi nền tảng]</strong> Lớp mặt tiền <code>freally-journal</code> giờ xuất lại <code>open</code> / <code>JournalEvent</code> / <code>JournalError</code> / <code>JournalSubscriber</code> chính thức từ <code>freally-journal-mac</code> khi <code>cfg(target_os = &quot;macos&quot;)</code>. Linux vẫn dùng bề mặt có kiểu nhưng mới chỉ là stub; giai đoạn 3 sẽ thay thế nó.","changelog.8b1b0978d0a2":"<strong>[chỉ Linux]</strong> Giai đoạn 3: trình theo dõi nhật ký inotify+fanotify (<code>freally-journal-lin</code>): <code>JournalSubscriber::open</code> phân giải một thư mục gốc theo dõi tuyệt đối, ghi lại <code>stat.st_dev</code> + tên ánh xạ từ số ma thuật của <code>statfs.f_type</code> (ext4/btrfs/zfs/xfs/f2fs/tmpfs/...), phát hiện <code>CAP_SYS_ADMIN</code> qua dòng <code>CapEff:</code> của <code>/proc/self/status</code>, và nạp (hoặc tạo trong lần chạy đầu) một con trỏ cho từng điểm theo dõi tại <code>~/.local/share/freally/cursors/&lt;root_hash&gt;.json</code> (có tính đến XDG_DATA_HOME). <code>bootstrap()</code> duyệt cây qua <code>getdents64(2)</code> thô (nhanh hơn <code>read_dir</code> trên cây rất lớn) với bộ chặn vòng lặp theo <code>(st_dev, st_ino)</code> và phát các sự kiện <code>JournalEvent::Create</code> tổng hợp. <code>subscribe()</code> tạo một luồng riêng chạy backend được chọn: <strong>inotify</strong> (mặc định, không cần đặc quyền) — <code>inotify_add_watch</code> đệ quy bao phủ create/modify/close-write/delete/move/attr, với <code>IN_Q_OVERFLOW</code> kích hoạt việc quét lại toàn cây bằng <code>getdents64</code>; hoặc <strong>fanotify</strong> (cần CAP_SYS_ADMIN) — một <code>fanotify_mark(FAN_MARK_FILESYSTEM)</code> duy nhất với <code>FAN_REPORT_DFID_NAME</code>, để việc theo dấu đổi tên vẫn đứng vững khi đi xuyên subvolume Btrfs và overlayfs, điều mà inotify không tái hiện được. Bộ phân loại mặt nạ inotify theo đúng thứ tự ưu tiên lý do USN của giai đoạn 1 (<code>Delete &gt; Create</code>, <code>Rename &gt; Create</code>, <code>IN_CLOSE_WRITE</code> chốt <code>Modify</code>). Ghép cặp đổi tên theo từng lô qua cookie của inotify / bản ghi thông tin <code>OLD_DFID_NAME</code> của fanotify; các cặp bị tách giữa hai lô suy giảm thành <code>Delete + Create</code> (ghi chú cho đợt hiệu năng giai đoạn 13). Lỗi <code>EPERM/EINVAL/ENOSYS</code> của fanotify lúc khởi tạo sẽ rơi xuống inotify, để các kernel &lt; 5.17 (không có <code>FAN_REPORT_DFID_NAME</code>) và các bản dựng <code>CONFIG_FANOTIFY=n</code> vẫn hoạt động. Phụ thuộc lúc chạy chỉ có <code>libc = &quot;0.2&quot;</code> — một đường gọi hệ thống thô thuần túy.","changelog.f558e7c13bef":"<strong>[chỉ Linux]</strong> Nối <code>freally-indexd</code> với unit người dùng của systemd: các lệnh con <code>install</code> / <code>uninstall</code> / <code>service</code> ghi <code>~/.config/systemd/user/freally-indexd.service</code> với <code>Type=simple</code> + <code>Restart=always</code> + <code>WantedBy=default.target</code> (theo đặc tả giai đoạn 3) và chạy <code>systemctl --user enable --now</code>. <code>ExecStart</code> đặt đường dẫn tệp nhị phân trong dấu ngoặc kép, để bản cài với <code>--binary &quot;/path with spaces/freally-indexd&quot;</code> không bị trình phân tích unit nhạy với khoảng trắng của systemd làm hỏng. Giai đoạn 4 lấp đầy trình theo dõi theo từng thư mục gốc + lõi chỉ mục bên trong thân dịch vụ. Chế độ chạy tiền cảnh <code>run --root &lt;path&gt;</code> in các sự kiện inotify/fanotify ra stdout để kiểm tra thủ công / bằng kiểm thử khói.","changelog.c891685c91b5":"<strong>[chỉ Linux]</strong> Chính sách Polkit tại <code>crates/freally-indexd/polkit/io.mikeweaver.freally.policy</code> khai báo hành động <code>io.mikeweaver.freally.elevate</code> cho luồng nâng cấp tùy chọn lên fanotify. <code>auth_self_keep</code> (≈5 min) hỏi người dùng đang hoạt động mật khẩu của chính họ; các chú thích <code>org.freedesktop.policykit.exec.path</code> + <code>argv1</code> ghim <code>/usr/local/bin/freally-indexd elevate</code>, để ID hành động không thể bị dùng lại cho một tệp nhị phân khác. Người bảo trì bản phân phối cài tệp này vào <code>/usr/share/polkit-1/actions/</code>.","changelog.5ce16f33ef5f":"<strong>[mọi nền tảng]</strong> Lớp mặt tiền <code>freally-journal</code> giờ xuất lại <code>open</code> / <code>JournalEvent</code> / <code>JournalError</code> / <code>JournalSubscriber</code> / <code>WatchCursor</code> chính thức từ <code>freally-journal-lin</code> khi <code>cfg(target_os = &quot;linux&quot;)</code>. Các đích Unix khác (FreeBSD, OpenBSD, illumos) vẫn giữ bề mặt <code>portable_stub</code> có kiểu nhưng mới chỉ là stub.","changelog.369e1b7b5e7f":"Đã sửa (đợt rà soát giai đoạn 8)","changelog.600f17cedae8":"<strong>[mọi nền tảng]</strong> Trình trích xuất văn bản thuần của giai đoạn 8 giờ phát hiện bảng mã <em>trước</em> khi chạy bước cắt phần vượt giới hạn. Phiên bản trước luôn chạy một vòng cắt <code>from_utf8</code> lặp đi lặp lại trên bộ đệm đã cắt, bất kể bảng mã — với đầu vào UTF-16 vượt giới hạn 5 MiB (≈ 2.5 M điểm mã), vòng lặp bỏ dần byte cho đến khi gặp một tiền tố có dạng UTF-8, thường để lại bộ đệm có số byte lẻ, rồi <code>decode</code> từ chối nó dưới dạng <code>ExtractError::Malformed</code>. Với việc cắt có nhận biết bảng mã, UTF-16 được cắt tại ranh giới byte chẵn và UTF-8 được cắt tại ranh giới điểm mã qua hàm hỗ trợ mới <code>trim_to_utf8_boundary</code>. Hồi quy mới <code>utf16_le_overshoot_truncates_at_even_boundary_not_malformed</code> khóa chặt hợp đồng này.","changelog.29036e7ef80a":"<strong>[mọi nền tảng]</strong> Các trình trích xuất xem lướt tệp nén + dữ liệu có cấu trúc của giai đoạn 8 giờ làm sạch các ký tự điều khiển xuống dòng (<code>\\n</code> / <code>\\r</code> / <code>\\0</code>) trong tên mục của tệp nén, giá trị trường CSV và giá trị chuỗi vô hướng của JSON / YAML qua hàm hỗ trợ mới <code>extractors::util::sanitize_inline</code>. Trước đây một mục zip / 7z / tar thù địch có thể khai báo tên chứa <code>\\n</code> và chèn các hàng ma vào blob tìm kiếm (một mục giả làm nhiều mục); lỗi tương tự tồn tại ở bề mặt giá trị vô hướng của CSV / JSON / YAML, nơi các trường trong ngoặc kép có thể hợp lệ chứa ký tự xuống dòng. Đầu ra đã làm sạch giữ nguyên khả năng truy hồi khi tìm kiếm bằng cách thoát các byte (<code>\\\\n</code> / <code>\\\\r</code> / <code>\\\\0</code>) thay vì bỏ chúng. Các hồi quy mới <code>entry_name_with_newline_is_sanitized</code> (tệp nén), <code>csv_field_with_newline_is_sanitized</code> và <code>json_string_value_with_newline_is_sanitized</code> bao phủ hợp đồng trên từng bề mặt.","changelog.85af001a0e9a":"<strong>[mọi nền tảng]</strong> Các bộ phân tích docx + pptx của giai đoạn 8 giờ kiểm tra <code>sink.is_cancelled()</code> theo hạn mức sự kiện thay vì theo từng đoạn văn (docx) / chỉ theo từng trang chiếu (pptx). Một tệp docx thù địch có một <code>&lt;w:p&gt;</code> khổng lồ (hàng nghìn run <code>&lt;w:t&gt;</code> nối nhau) từng có thể ở lì trong <code>parse_docx_body</code> nhiều giây mà không nhường cho cờ hủy; bộ phân tích XML trang chiếu của pptx hoàn toàn không có kiểm tra hủy bên trong. Bản sửa đếm mọi sự kiện quick-xml và kiểm tra cờ sau mỗi 32 sự kiện — bản thân lần nạp chỉ là một biến nguyên tử <code>Ordering::Relaxed</code>, chi phí dưới một nano giây. Khoảng ân hạn của hộp cát giai đoạn 7 vẫn là lưới an toàn cho trường hợp xấu nhất, nhưng việc dừng hợp tác giờ diễn ra trong một hạn mức có giới hạn, bất kể XML đầu vào có hình dạng thế nào.","changelog.85445058bd37":"<strong>[mọi nền tảng]</strong> Trình trích xuất docx của giai đoạn 8 giờ bỏ qua các đoạn văn có kiểu tiêu đề nhưng không có chữ. Phiên bản trước xuất một <code># \\n\\n</code> trơ trọi (hoặc nhiều dấu thăng hơn) vào blob tìm kiếm cho các khối <code>&lt;w:p&gt;</code> rỗng mang <code>&lt;w:pStyle w:val=&quot;HeadingN&quot;/&gt;</code>; các token như <code>#</code> là nhiễu, bị tính vào giới hạn của sink mà không giúp gì cho truy hồi. Hồi quy mới <code>docx_skips_empty_heading_paragraphs</code> bao phủ trường hợp này.","changelog.1dad52d35905":"<strong>[mọi nền tảng]</strong> Các trình trích xuất mã + văn bản thuần của giai đoạn 8 giờ cắt bộ đệm vượt giới hạn về ranh giới điểm mã UTF-8 trong O(1) qua phép lùi theo byte tiếp nối dùng chung <code>trim_to_utf8_boundary</code>, thay cho vòng lặp cũ <code>while !std::str::from_utf8(&amp;buf).is_ok() { buf.pop(); }</code> vốn quét lại toàn bộ bộ đệm 4 / 5 MiB sau mỗi lần pop (trường hợp xấu nhất O(N²)). Sáu kiểm thử đơn vị trong <code>extractors::util::tests</code> chặn hồi quy cho các trường hợp điểm mã trọn vẹn, điểm mã dở dang, ranh giới ASCII, toàn byte tiếp nối và bộ đệm rỗng.","changelog.4e47265991ba":"<strong>[mọi nền tảng]</strong> Bảng trong docx của giai đoạn 8 (<code>&lt;w:tbl&gt;</code> / <code>&lt;w:tr&gt;</code> / <code>&lt;w:tc&gt;</code>) đã có độ phủ kiểm thử rõ ràng. <code>parse_docx_body</code> vốn đã xử lý các thẻ bảng nhưng chưa kiểm thử nào chạy qua đường này; một hồi quy ở đó sẽ âm thầm loại nội dung bảng khỏi khả năng truy hồi của tìm kiếm với mọi tệp docx có bảng. <code>docx_renders_tables_as_pipe_rows</code> mới khóa chặt cách hiển thị <code>| cell | cell |</code>.","changelog.f8937347b501":"<strong>[mọi nền tảng]</strong> YAML nhiều tài liệu của giai đoạn 8 (dấu phân tách <code>---</code>) đã có độ phủ kiểm thử rõ ràng. Đường <code>flatten_yaml</code> xuất các khóa có tiền tố <code>[doc=N]</code> nhưng chưa kiểm thử nào bao phủ logic tiền tố; <code>flattens_multi_document_yaml_with_doc_prefix</code> mới bảo đảm một lần tái cấu trúc sau này không thể âm thầm gộp mất ranh giới giữa các tài liệu.","changelog.585aef173030":"Đã sửa (đợt rà soát giai đoạn 5)","changelog.0aa74d3eaa36":"<strong>[mọi nền tảng]</strong> Bộ phân tích truy vấn của giai đoạn 5 giờ coi <code>!</code> đứng sau <code>)</code> là NOT tiền tố — <code>(a)!b</code> được phân tích thành <code>(a) AND !b</code>, khớp với hành vi đã được ghi trong tài liệu của Everything (voidtools). Trước đây phép kiểm tra ranh giới byte và token bỏ sót <code>RParen</code>, nên <code>!b</code> ở cuối bị gộp thành một chuỗi nguyên văn <code>!b</code> và phép phủ định âm thầm bị bỏ (hồi quy của Quy tắc thường trực #8). Kiểm thử bộ phân tích mới <code>bang_after_rparen_is_not</code> khóa chặt hợp đồng này.","changelog.7a304dd66705":"<strong>[mọi nền tảng]</strong> Bộ nhớ đệm kế hoạch của giai đoạn 5 không còn sửa đổi kế hoạch đã lưu khi <code>match_mode.match_path</code> đang bật. Việc xóa hạt giống cho phép tìm theo đường dẫn bỏ qua bộ lọc sơ bộ trigram giờ chỉ chạy lúc thực thi — <code>ExecPlan</code> vẫn là một hàm thuần của chuỗi truy vấn, nên hai bên gọi đồng thời với cùng truy vấn nhưng khác thiết lập <code>match_path</code> không còn có thể làm hỏng kế hoạch đã lưu của nhau. Kiểm thử nối mới <code>plan_cache_survives_match_path_toggle</code> bao phủ trường hợp này.","changelog.fa995dcc342d":"<strong>[mọi nền tảng]</strong> <code>parse_iso_day</code> của giai đoạn 5 từ chối ngay từ đầu các ngày không thể có trên lịch (30 tháng 2, 31 tháng 4, 29 tháng 2 năm không nhuận, …) qua bộ kiểm tra mới <code>days_in_month</code> (phép tính ngày từ epoch của Howard Hinnant chấp nhận mọi ngày từ 1-31 cho mọi tháng, âm thầm đẩy phần tràn sang tháng sau). Voidtools từ chối những ngày này — hồi quy của Quy tắc thường trực #8. Kiểm thử bộ phân tích mới <code>invalid_calendar_days_reject</code> bao phủ các trường hợp năm nhuận + cuối tháng.","changelog.a94bbcf610a6":"<strong>[mọi nền tảng]</strong> Danh sách công cụ sửa đổi dành sẵn của giai đoạn 5 được mở rộng để bao phủ các token theo thói quen của người dùng Everything (voidtools) (<code>wfn:</code>, <code>wholefilename:</code>, <code>case:</code>, <code>count:</code>, <code>dupe:</code>, <code>nodiacritics:</code>), để người dùng gõ chúng nhận được <code>QueryError::UnsupportedModifier</code> có kiểu lúc thực thi thay vì một lỗi phân tích. Phân tích được nhưng thất bại rõ ràng là hợp đồng của Quy tắc thường trực #8 cho đến khi mỗi công tắc đó ra mắt cùng giai đoạn sở hữu ống kính của nó. Kiểm thử bộ phân tích mới <code>voidtools_reserved_toggles_parse</code> bao phủ cả nhóm.","changelog.6543bc5ccebd":"<strong>[mọi nền tảng]</strong> <code>eval_full</code> của giai đoạn 5 giờ chuyển đường dẫn ứng viên thành chữ thường một lần cho mỗi hàng khi <code>match_path</code> đang bật, thay vì chuyển lại cho từng nút con AND / OR — chuỗi đường dẫn chữ thường được đưa lên <code>NameEvaluator::matches_full</code> và truyền xuyên qua <code>eval_full</code> dưới dạng <code>Option&lt;&amp;str&gt;</code>. Bỏ được một lần cấp phát <code>to_lowercase()</code> cho mỗi con AND, vốn tăng theo độ sâu của truy vấn.","changelog.cd2b5074233d":"<strong>[mọi nền tảng]</strong> <code>eval_modifier::Reserved</code> của giai đoạn 5 giờ gọi <code>debug_assert!</code> khi bị chạm tới — <code>validate_supported</code> là cổng đã ghi trong tài liệu ở đầu <code>execute()</code>, và một công cụ sửa đổi Reserved đi tới bước đánh giá nghĩa là bên gọi đã tự dựng AST <code>Query</code> bằng tay và vượt qua cổng. Nhánh <code>false</code> âm thầm trước đây là mã chết trên các đường gọi được hỗ trợ và giờ thất bại rõ ràng khi có <code>cfg(debug_assertions)</code>.","changelog.dc40e0e57b5d":"<strong>[mọi nền tảng]</strong> Giai đoạn 5: ống kính tên tệp (<code>freally-query</code>) — bộ phân tích + bộ thực thi DSL theo kiểu Everything của voidtools trên chỉ mục của giai đoạn 4. <code>parse(s)</code> dựng một AST <code>Query</code> bao phủ các cụm chuỗi con nguyên văn / ký tự đại diện (<code>*</code>, <code>?</code>) / regex (tiền tố <code>regex:</code>), toán tử logic (<code>AND</code> / <code>OR</code> / <code>NOT</code> / tiền tố <code>!</code>, AND ngầm giữa các nguyên tử liền kề, nhóm trong ngoặc), và các vị từ công cụ sửa đổi: <code>size:</code> (với <code>&gt;</code>, <code>&lt;</code>, <code>&gt;=</code>, <code>&lt;=</code>, <code>=</code>, đơn vị <code>b</code>/<code>kb</code>/<code>mb</code>/<code>gb</code>/<code>tb</code>), <code>date:</code> (bí danh tương đối <code>today</code> / <code>yesterday</code> / <code>thisweek</code> / <code>lastweek</code> / <code>thismonth</code> / <code>lastmonth</code> / <code>thisyear</code> / <code>lastyear</code> cùng <code>YYYY-MM-DD</code> tuyệt đối có toán tử so sánh), <code>ext:</code> (một phần mở rộng hoặc danh sách phân tách bằng <code>;</code>, bỏ dấu <code>.</code>), <code>attrib:</code> (tập chữ cái thuộc tính Windows <code>R</code>/<code>H</code>/<code>S</code>/<code>A</code>/<code>D</code>/<code>C</code>/<code>E</code>/<code>T</code>/<code>O</code>/<code>L</code>), <code>path:</code> / <code>parent:</code> / <code>child:</code> (so khớp chuỗi con; tôn trọng các bí danh <code>name:</code> / <code>folder:</code>). Các bí danh bộ lọc nhanh <code>audio:</code> / <code>video:</code> / <code>image:</code> / <code>document:</code> / <code>executable:</code> / <code>archive:</code> mở rộng thành các tập phần mở rộng định sẵn. Các công cụ sửa đổi của các ống kính tương lai (<code>content:</code> / <code>lufs:</code> / <code>codec:</code> / <code>channels:</code> / <code>samplerate:</code> / <code>length:</code> / <code>similar:</code> / <code>duration:</code> / <code>type:</code> / <code>lang:</code>) phân tích được nhưng bị chặn bởi <code>validate_supported</code>, trả về <code>QueryError::UnsupportedModifier</code> cho đến khi giai đoạn sở hữu chúng ra mắt. <code>execute(idx, query, ExecOpts)</code> lập kế hoạch truy vấn (chuỗi con nguyên văn dài nhất trở thành hạt giống trigram; OR phá hạt giống thành một lượt quét các hàng còn sống), lấy ứng viên từ chỉ mục tên tự xây qua các API byte mượn mới <code>for_each_candidate_named</code> / <code>for_each_live</code>, chạy các vị từ phía tên, hydrate các hàng còn lại qua lệnh lấy theo lô với mệnh đề IN mới <code>Store::get_many</code>, đánh giá các vị từ trên bản ghi đầy đủ, áp <code>SortSpec</code> (tên / đường dẫn / kích thước / ngày / loại / phần mở rộng, tăng/giảm), và truyền kết quả qua <code>ResultSet::first_batch</code> / <code>collect</code>. Các công tắc <code>MatchMode</code> (<code>match_case</code> / <code>whole_word</code> / <code>match_path</code> / <code>match_diacritics</code>) được áp lúc thực thi; <code>match_path</code> mở rộng mục tiêu tìm kiếm ra toàn bộ đường dẫn đã chuẩn hóa bằng cách bỏ qua bộ lọc sơ bộ của chỉ mục tên (ghi chú cho đợt hiệu năng giai đoạn 13); <code>match_diacritics: false</code> loại bỏ dấu kết hợp qua NFKD trước khi so chuỗi con. <code>PlanCache</code> LRU 16 mục (<code>PlanCache::default16</code>) lấy chuỗi truy vấn đã cắt khoảng trắng làm khóa và dùng lại AST đã phân tích + kế hoạch khi gõ lại cùng nội dung. Phụ thuộc lúc chạy mới (đều có giấy phép dễ dãi, nằm trong danh sách cho phép của deny.toml): <code>regex = &quot;1&quot;</code> (MIT/Apache-2.0), <code>unicode-normalization = &quot;0.1&quot;</code> (MIT/Apache-2.0). <code>name_index</code> của <code>crates/freally-index</code> đổi phép giao trigram từ <code>BTreeSet</code> sang phép trộn hai con trỏ trên danh sách posting đã sắp xếp (ghi chú PERF trong Build Guide §<code>name_index</code>) và phơi bày <code>name_bytes</code> / <code>for_each_candidate_named</code> / <code>for_each_live</code> cho ống kính; <code>Store::get_many</code> chia 250 id cho mỗi mệnh đề IN để nằm dưới <code>SQLITE_MAX_VARIABLE_NUMBER</code> của SQLite. <code>xtask gen-fixture</code> tổng hợp một luồng bản ghi tệp SplitMix64 tất định cho benchmark hiệu năng của giai đoạn 5 (<code>cargo bench -p freally-query --bench filename_lens</code>); benchmark in P50 / P99 theo từng kịch bản kèm dấu FAIL và chỉ thoát với mã khác không khi <code>FREALLY_BENCH_GATE=1</code>. Fixture <code>tests/voidtools_compat.rs</code> cố định 50 truy vấn Everything thật — cổng hồi quy của Quy tắc thường trực #8; <code>tests/wiring.rs</code> bao phủ trọn vẹn bộ thực thi trên một chỉ mục dựa trên <code>tempfile</code>; <code>tests/smoke/phase_05_filename_lens.rs</code> là kiểm thử khói không phụ thuộc hệ điều hành, chạy trên mọi mục của ma trận CI.","changelog.0af41265e3fd":"<strong>[mọi nền tảng]</strong> Giai đoạn 4: lõi chỉ mục (<code>freally-index</code>) — lớp mặt tiền không phụ thuộc hệ điều hành, tiêu thụ enum dùng chung <code>JournalEvent</code> và điều phối ba kho lưu trữ bền: một chỉ mục Tantivy (<code>index.tantivy/</code>) cho tìm kiếm toàn văn + theo khía cạnh, một <code>files.db</code> chính thức của SQLite ở chế độ WAL + <code>synchronous=NORMAL</code> cho hàng sự thật bền vững <code>FileRecord</code>, và một chỉ mục tên tự xây dựa trên mmap (<code>name.idx</code> là heap chuỗi đóng gói + posting đảo ngược theo trigram; <code>name.suf</code> là mảng hậu tố theo thứ tự từ điển) để sinh ứng viên theo chuỗi con. <code>Index::open(root)</code> tạo cây thư mục, mở hoặc tạo từng kho, và hòa giải sai lệch bằng cách phát lại kho chính thức vào chỉ mục tên khi số hàng không khớp. <code>Index::apply(&amp;[JournalEvent])</code> đưa các sự kiện Create / Modify / Delete / Rename / AttrChange qua thao tác xóa-rồi-thêm của Tantivy + upsert của SQLite + upsert/xóa của chỉ mục tên, với <code>file_id = blake3(path)[0..8]</code> làm khóa ổn định. <code>Index::commit()</code> xả Tantivy, ghi lại nguyên tử <code>name.idx</code> + <code>name.suf</code> qua tệp tạm + đổi tên, checkpoint WAL của SQLite vào cơ sở dữ liệu chính, và lưu <code>manifest.json</code> với <code>tantivy_generation</code> đã tăng cùng các con trỏ theo từng ổ đĩa được ghi qua <code>Index::record_cursor</code>. <code>EventQueue</code> có giới hạn (dung lượng mặc định 10 000 — theo đặc tả của Build Guide) báo áp lực ngược bằng <code>IndexError::QueueFull</code> thay vì âm thầm bỏ sự kiện; <code>push_blocking</code> tôn trọng cùng ngữ nghĩa đóng. Thư mục gốc chỉ mục mặc định theo từng hệ điều hành (<code>%LOCALAPPDATA%\\Freally\\index</code> / <code>~/Library/Application Support/Freally/index</code> / <code>${XDG_DATA_HOME:-~/.local/share}/freally/index</code>) qua <code>default_index_root()</code>. Phụ thuộc lúc chạy mới (đều có giấy phép dễ dãi, nằm trong danh sách cho phép của deny.toml): <code>tantivy = &quot;0.26&quot;</code> (MIT), <code>rusqlite = &quot;0.37&quot;</code> với tính năng <code>bundled</code> (MIT) — kéo theo <code>libsqlite3-sys</code> + SQLite đóng gói kèm (phạm vi công cộng, được cho phép dưới <code>Unlicense</code>), <code>memmap2 = &quot;0.9&quot;</code> (MIT/Apache-2.0), <code>blake3 = &quot;1&quot;</code> (CC0/Apache-2.0), <code>parking_lot = &quot;0.12&quot;</code> (MIT/Apache-2.0). Kiểm thử khói <code>tests/smoke/phase_04_index.rs</code> bao phủ bố cục thư mục, vòng đi-về đầy đủ của sự kiện, khôi phục từ SQLite sau kill-9, lưu bền con trỏ trong manifest, áp lực ngược của hàng đợi, và khử trùng lặp xóa-rồi-thêm của Tantivy.","changelog.8167310c5eff":"<strong>[mọi nền tảng]</strong> Lớp mặt tiền <code>freally-journal</code> giờ xuất lại <code>JournalEvent</code> / <code>JournalError</code> / <code>JournalSubscriber</code> chính thức từ trình theo dõi Windows khi <code>cfg(windows)</code>, trình theo dõi macOS khi <code>cfg(target_os = &quot;macos&quot;)</code>, và trình theo dõi Linux khi <code>cfg(target_os = &quot;linux&quot;)</code>. Các đích Unix khác vẫn giữ bề mặt <code>portable_stub</code> có kiểu nhưng mới chỉ là stub.","changelog.f11a02c6c5f1":"<strong>[macOS + Linux]</strong> Cờ <code>--root &lt;path&gt;</code> của lệnh con <code>Run</code> trong <code>freally-indexd</code> (được ưu tiên dùng trên macOS / Linux) giờ cũng điều khiển trình theo dõi nhật ký của Linux; <code>--volume</code> sẵn có tiếp tục hoạt động như một từ đồng nghĩa trên mọi hệ điều hành.","changelog.6897dd8bf8f4":"Đã sửa (đợt rà soát giai đoạn 4)","changelog.2ed95ca28b12":"<strong>[mọi nền tảng]</strong> <code>Index::apply</code> của giai đoạn 4 giờ suy giảm một <code>JournalEvent::Rename</code> có <code>old_path</code> chưa từng được lập chỉ mục (cặp đổi tên giữa hai lô mà trình theo dõi nhật ký không ghép được) thành <code>Delete(old) + synthetic Create(new)</code>, thay vì ghi một hàng Tantivy / chỉ mục tên không có hàng sự thật trong <code>files.db</code>. Phản chiếu hợp đồng dự phòng giữa các lô mà các trình theo dõi nhật ký đã công bố; kiểm thử khói mới <code>rename_of_unknown_path_degrades_to_delete_plus_create</code> bao phủ trường hợp này.","changelog.85d4a5272278":"<strong>[mọi nền tảng]</strong> <code>EventQueue::close</code> của giai đoạn 4 không còn chạy đua với <code>wait_for_events</code> / <code>push_blocking</code> — <code>closed</code> giờ được lưu trong cùng <code>Mutex</code> với chính hàng đợi thay vì một <code>Mutex</code> đi kèm, để <code>notify_all</code> của <code>close()</code> không thể rơi vào giữa phép kiểm tra “hàng đợi có rỗng không?” của bên đang chờ và <code>Condvar::wait</code> của nó. Các kiểm thử khói mới <code>close_unblocks_push_blocking_and_wait_for_events</code> và <code>try_push_after_close_refuses</code> khóa chặt hợp đồng này.","changelog.8096900614c3":"<strong>[mọi nền tảng]</strong> <code>Manifest::load_or_default</code> của giai đoạn 4 giờ coi lỗi phân tích JSON là thiếu tệp kèm cảnh báo, thay vì một <code>IndexError::Manifest</code> cứng sẽ chặn <code>Index::open</code>. Kho chính thức SQLite và <code>meta.json</code> của Tantivy là bản ghi bền vững; manifest chỉ là bộ nhớ đệm theo từng lần commit mà <code>Index::commit</code> ghi lại ở mỗi chu kỳ. Kiểm thử khói mới <code>torn_manifest_does_not_block_open</code> bao phủ trường hợp này.","changelog.0f06a85ae4d4":"<strong>[mọi nền tảng]</strong> <code>derive_file_id</code> của giai đoạn 4 giờ băm trực tiếp <code>OsStr::as_encoded_bytes()</code> thay vì <code>to_string_lossy()</code>, để các đường dẫn chỉ khác nhau ở các byte UTF-8 không hợp lệ không bị gộp về cùng một id. Tác động thực tế hiếm gặp (tên tệp ext4 / Btrfs trên Linux là chuỗi byte tùy ý) nhưng bản sửa loại bỏ một lớp va chạm âm thầm trước khi giai đoạn 5 bắt đầu dựa vào <code>file_id</code> như một mã băm ổn định.","changelog.4f8d098583e4":"<strong>[chỉ Windows]</strong> Việc ghép cặp đổi tên của nhật ký USN trong <code>freally-journal-win</code> (giai đoạn 1) giờ xếp nửa tên CŨ của một lần đổi tên (và mọi bản ghi <code>FILE_DELETE</code>) vào loại <strong>kết thúc</strong>: phát ngay mà không cần <code>USN_REASON_CLOSE</code>. NTFS không phát bản ghi đóng cho phiên của tên cũ — ở đường dẫn đó không còn gì để chờ. Trước đây bộ phân loại trả về <code>Pending</code> cho các bản ghi <code>RENAME_OLD_NAME</code> thiếu <code>CLOSE</code>, bảng ghép cặp luôn rỗng, và bản ghi <code>RENAME_NEW_NAME | CLOSE</code> tương ứng âm thầm bị bỏ qua <code>?</code>. Hệ quả: <code>JournalEvent::Rename</code> chưa bao giờ được phát cho bất kỳ lần đổi tên nào trong cây. Lần chạy chẩn đoán lại trên một ổ NTFS thật đã xác nhận bản sửa; kiểm thử tích hợp <code>realtime_create_modify_rename_delete_round_trip</code> giờ đạt trọn vẹn và không còn bị <code>#[ignore]</code>.","changelog.6924516bf9eb":"<strong>[chỉ Windows]</strong> <code>JournalEvent::Delete</code> giờ tra bảng ghép cặp đổi tên theo FRN trước khi quay về kết quả <code>build_path</code> của bản ghi. Windows hiện đại dùng thao tác xóa theo ngữ nghĩa POSIX qua <code>NtSetInformationFile</code>, vốn đổi tên tệp thành một tên tạm <code>$.dF{guid}</code> trước khi phát <code>FILE_DELETE</code>; nếu không tra như vậy, bên tiêu thụ sẽ thấy <code>Delete $.dF{guid}</code> thay vì <code>Delete &lt;original_path&gt;</code>. Đây là biện pháp phòng thủ: kiểm thử làm lộ ra lỗi đổi tên chỉ thấy hành vi <code>DeleteFile</code> cổ điển ở đây, nhưng đường POSIX có thể xảy ra trong các tình huống tệp bị khóa / giữa các tiến trình.","changelog.6b2e8f83dd8e":"Ngừng hỗ trợ","changelog.43e7d9ac5463":"_(trống)_","changelog.261a0a91e8b7":"Cách cập nhật tệp này","changelog.7f595e71864a":"Mỗi giai đoạn phải thêm ít nhất một mục từ góc nhìn người dùng dưới <code>[Unreleased]</code> trước khi được đánh dấu là hoàn tất. Dùng các mục <strong>Đã thêm / Đã thay đổi / Đã sửa / Ngừng hỗ trợ / Đã xóa / Bảo mật</strong>. Nêu tên các crate và giấy phép mới. Đánh dấu thay đổi phá vỡ API bằng <code>**BREAKING:**</code> ở đầu.","changelog.421c995e549d":"Khi gắn thẻ một bản phát hành, đổi tên <code>[Unreleased]</code> thành <code>[X.Y.Z] — YYYY-MM-DD</code> và thêm một khối <code>[Unreleased]</code> mới.","changelog.d0320c0139a6":"Quy tắc đồng nhất giữa các nền tảng","changelog.453f4c970ef9":"Freally phát hành trên Windows, macOS và Linux từ v0.19.84. <strong>Mỗi mục phải nêu rõ phạm vi nền tảng</strong> bằng một tiền tố trong ngoặc vuông. Dùng một trong các tiền tố sau:","changelog.0242ad80ada4":"<code>[all platforms]</code> — thay đổi áp dụng cho Windows, macOS và Linux.","changelog.1a0018aa8db8":"<code>[Windows-only]</code>, <code>[macOS-only]</code>, <code>[Linux-only]</code> — công việc cho một hệ điều hành. Chấp nhận được giữa một giai đoạn; nên được cân bằng bởi các hệ điều hành khác ở các giai đoạn sau.","changelog.d6c3b60c9fed":"<code>[Windows + macOS]</code>, <code>[macOS + Linux]</code>, <code>[Windows + Linux]</code> — bao phủ một phần.","changelog.3211c26760b3":"<strong>Nên</strong> — tiền tố phạm vi rõ ràng:","changelog.40224131030f":"<strong>Không nên</strong> — không có tiền tố phạm vi (đợt rà soát giai đoạn sẽ từ chối):","changelog.70c52c7ae961":"Các đợt rà soát giai đoạn sẽ từ chối nhật ký thay đổi không nêu rõ phạm vi nền tảng."};
